    function fdGorunenUygulamaId(){
        const idler=['personelApp','personelDashboardApp','izinTakipApp','puantajApp','avansApp','icraApp','ekOdemeApp','kkdApp','vardiyaApp','magicpassApp','irsaliyeTakipApp','kiraTakipApp','ihracatApp','aracTakipApp','policeTakipApp','sirketApp'];
        return idler.find(id=>{const el=document.getElementById(id);return el&&getComputedStyle(el).display!=='none';})||'';
    }
    function fdOtomatikEsitlemeBilgisi(){
        const id=fdGorunenUygulamaId(),moduller={personelApp:'personel',personelDashboardApp:'personel',izinTakipApp:'izin',puantajApp:'puantaj',avansApp:'avans',icraApp:'icra',ekOdemeApp:'ekodeme',kkdApp:'kkd',vardiyaApp:'vardiya',magicpassApp:'vardiya',irsaliyeTakipApp:'irsaliye',kiraTakipApp:'kira',ihracatApp:'ihracat',aracTakipApp:'arac',policeTakipApp:'police',sirketApp:'sirket'};return{id,modul:moduller[id]||''};
    }
    function fdOtomatikEsitlemeEngelliMi(){
        if(document.hidden||!activeUser?.sirketId||!SUPABASE_MODE||!supabaseClient||supabaseKaydetmeBekleyen>0)return true;
        if(fdGorunenUygulamaId()==='vardiyaApp')return true;
        const aktif=document.activeElement;if(aktif&&['INPUT','TEXTAREA','SELECT'].includes(aktif.tagName))return true;
        if([...document.querySelectorAll('.modal-overlay')].some(el=>getComputedStyle(el).display!=='none'))return true;
        const overlay=document.getElementById('globalOverlay');return Boolean(overlay&&getComputedStyle(overlay).display!=='none');
    }
    function fdOtomatikEsitlemeEkraniniCiz(id){
        try{
            if(['personelApp','personelDashboardApp','izinTakipApp'].includes(id))initUI();
            else if(id==='puantajApp')renderPuantajMatrisi();
            else if(id==='avansApp'){renderAvansKayitListesi();renderAvansKesintiListesi();}
            else if(id==='icraApp')renderIcraListesi();
            else if(id==='ekOdemeApp')ekOdemeCizelgesiniHazirla();
            else if(id==='kkdApp')kkdCizelgesiniHazirla();
            else if(id==='vardiyaApp')vardiyaCiz();
            else if(id==='magicpassApp'){magicpassPersonelListesiCiz();magicpassAylikCizelgeyiCiz();magicpassGunlukRaporuCiz();}
            else if(id==='irsaliyeTakipApp')irsaliyeListele();
            else if(id==='kiraTakipApp')kiraTumunuCiz();
            else if(id==='ihracatApp')ihracatFirmalariniCiz();
            else if(id==='aracTakipApp')aracTumTakipListeleriniCiz();
            else if(id==='policeTakipApp')policeListesiniCiz();
            else if(id==='sirketApp')renderSirketYonetimi();
        }catch(error){console.warn('Otomatik ekran yenileme:',error);}
    }
