    function driveBelgeDosyaAdi(personelAdi, modul, belgeTuru) {
        const temizle = deger => String(deger || '')
            .trim()
            .toLocaleUpperCase('tr-TR')
            .replace(/[^A-ZÇĞİÖŞÜ0-9]+/g, '_')
            .replace(/^_+|_+$/g, '');
        return `${temizle(personelAdi)}_${temizle(modul)}_${temizle(belgeTuru)}.pdf`;
    }

    /* supabasePdfDosyaAdiTemizle → core/data-access.js */

    async function fdYazilimSupabasePdfYukle(dosya, personelId, kayitId, tur, eskiYol = '') {
        if (!SUPABASE_MODE || !supabaseClient) throw new Error('Supabase PDF servisi hazır değil.');
        const sirketId = aktifSirketId();
        if (!sirketId) throw new Error('Şirket bilgisi bulunamadı.');
        const yol = `${sirketId}/${personelId}/${kayitId}/${tur}_${Date.now()}_${supabasePdfDosyaAdiTemizle(dosya.name)}`;
        const { error } = await supabaseClient.storage.from('icra-pdf').upload(yol, dosya, { contentType:'application/pdf', upsert:false });
        if (error) throw error;
        if (eskiYol && String(eskiYol).includes('/')) {
            await supabaseClient.storage.from('icra-pdf').remove([String(eskiYol)]);
        }
        return { id:yol, url:`supabase:${yol}`, ad:dosya.name };
    }

    async function fdYazilimSupabasePdfSil(yol = '') {
        if (!yol || !String(yol).includes('/')) return true;
        const { error } = await supabaseClient.storage.from('icra-pdf').remove([String(yol)]);
        if (error) throw error;
        return true;
    }

    function veriOnbelleginiYukle() {
        try {
            const ham = localStorage.getItem(VERI_ONBELLEK_ANAHTARI) || sessionStorage.getItem(VERI_ONBELLEK_ANAHTARI) || localStorage.getItem(ESKI_VERI_ONBELLEK_ANAHTARI) || sessionStorage.getItem(ESKI_VERI_ONBELLEK_ANAHTARI);
            if (!ham) return;
            const veri = JSON.parse(ham);
            // Cached payroll/records belong to the authenticated actor, not the device.
            if (SUPABASE_MODE && (!activeUser?.supabaseUserId || veri.oturum !== fdPortalVeriOturumu())) return;
            if (!localStorage.getItem(VERI_ONBELLEK_ANAHTARI)) {
                try { localStorage.setItem(VERI_ONBELLEK_ANAHTARI, ham); } catch (e) { sessionStorage.setItem(VERI_ONBELLEK_ANAHTARI, ham); }
            }
            if (Array.isArray(veri.personeller)) personeller = veri.personeller;
            if (Array.isArray(veri.izinler)) {
                izinYerelOnbellekKopyasi = veri.izinler.map(item => ({ ...item }));
                izinYerelOnbellekZamani = Number(veri.zaman || 0);
                izinler = veri.izinler;
            }
            if (!SUPABASE_MODE && Array.isArray(veri.kullanicilar)) kullanicilar = veri.kullanicilar;
            if (Array.isArray(veri.puantaj)) puantajVerileri = veri.puantaj;
            if (Array.isArray(veri.avanslar)) avanslar = veri.avanslar;
            if (Array.isArray(veri.ekOdemeler)) ekOdemeler = veri.ekOdemeler;
            if (Array.isArray(veri.kkd)) kkdKayitlari = veri.kkd;
            if (Array.isArray(veri.vardiya)) vardiyaKayitlari = veri.vardiya;
            if (Array.isArray(veri.irsaliyeler)) tasimaIrsaliyeleri = veri.irsaliyeler;
            if (Array.isArray(veri.kiratakip)) kiraKayitlari = veri.kiratakip;
            if (Array.isArray(veri.ihracat)) ihracatFirmalari = veri.ihracat.map(f=>({ ...f,yuklemeler:Array.isArray(f.yuklemeler)?f.yuklemeler:[] }));
            if (Array.isArray(veri.araclar)) araclar = veri.araclar.map(a => ({ ...a, bakimlar:Array.isArray(a.bakimlar) ? a.bakimlar : [], mtvOdemeleri:Array.isArray(a.mtvOdemeleri) ? a.mtvOdemeleri : [], sigortaGecmisi:Array.isArray(a.sigortaGecmisi) ? a.sigortaGecmisi : [], vizeGecmisi:Array.isArray(a.vizeGecmisi) ? a.vizeGecmisi : [] }));
            if (Array.isArray(veri.akaryakit)) akaryakitKayitlari = veri.akaryakit;
            if (Array.isArray(veri.icralar)) {
                icralar = veri.icralar.map(i => {
                    if (typeof i.kesintiler === 'string') {
                        try { i.kesintiler = JSON.parse(i.kesintiler); } catch (e) { i.kesintiler = []; }
                    }
                    if (!Array.isArray(i.kesintiler)) i.kesintiler = [];
                    return i;
                });
            }
            if (Array.isArray(veri.sirketler)) sirketler = veri.sirketler;
            if (Array.isArray(veri.subeler)) subeler = veri.subeler;
            [
                ['personeller', veri.personeller],
                ['izinler', veri.izinler],
                ['kullanicilar', SUPABASE_MODE ? null : veri.kullanicilar],
                ['puantaj', veri.puantaj],
                ['avanslar', veri.avanslar],
                ['ekOdemeler', veri.ekOdemeler],
                ['kkd', veri.kkd],
                ['vardiya', veri.vardiya],
                ['irsaliyeler', veri.irsaliyeler],
                ['ihracat', veri.ihracat],
                ['icralar', veri.icralar],
                ['araclar', veri.araclar],
                ['akaryakit', veri.akaryakit],
                ['sirketler', veri.sirketler],
                ['subeler', veri.subeler]
            // Server mode treats cache rows as previews, not acknowledged server data.
            // Only an actual scoped load may make a module eligible for saving/deletion.
            ].forEach(([anahtar, dizi]) => { if (!SUPABASE_MODE && Array.isArray(dizi)) yuklenenVeriler.add(anahtar); });
            personeller.forEach(p => p.id = String(p.id));
            izinler.forEach(i => { i.id = Number(i.id); i.pId = String(i.pId); i.gun = Number(i.gun); });
        } catch (error) {
            console.warn('Veri önbelleği okunamadı:', error);
        }
    }

    function veriOnbelleginiKaydet() {
        if (['IsgUzmani','IsyeriHekimi'].includes(activeUser?.rol)) return;
        const veri = {
            zaman: Date.now(),
            oturum: SUPABASE_MODE ? fdPortalVeriOturumu() : '',
            personeller,
            izinler,
            kullanicilar: SUPABASE_MODE ? [] : kullanicilar,
            puantaj: puantajVerileri,
            avanslar,
            ekOdemeler,
            kkd: kkdKayitlari,
            vardiya: vardiyaKayitlari,
            irsaliyeler: tasimaIrsaliyeleri,
            kiratakip: kiraKayitlari,
            ihracat: ihracatFirmalari,
            icralar,
            araclar,
            akaryakit:akaryakitKayitlari,
            sirketler,
            subeler: subeler.map(item => ({
                ...item,
                iskur: item.iskur ? { ...item.iskur, sifre:'' } : item.iskur,
                sgkErisim: item.sgkErisim ? { ...item.sgkErisim, sistemSifresi:'', isyeriSifresi:'' } : item.sgkErisim
            }))
        };
        const ham = JSON.stringify(veri);
        try {
            localStorage.setItem(VERI_ONBELLEK_ANAHTARI, ham);
        } catch (error) {
            try { sessionStorage.setItem(VERI_ONBELLEK_ANAHTARI, ham); } catch (e) { console.warn('Veri önbelleğe yazılamadı:', e); }
        }
    }

    veriOnbelleginiYukle();
    if (SUPABASE_MODE) {
        kullanicilar = [];
        yuklenenVeriler.delete('kullanicilar');
    }

    window.addEventListener('DOMContentLoaded', async () => {
        mountDashboardInIzinModule();
        ekOdemeSekmeleriniKur();
        organizePersonnelForm();
        document.addEventListener('input', event => {
            const alan = event.target;
            if (!(alan instanceof HTMLInputElement || alan instanceof HTMLTextAreaElement)) return;
            if (alan.closest('#loginForm')) return;
            if (alan.closest('[data-case-preserve="true"]') || (alan instanceof HTMLInputElement && !['text', 'search', 'tel'].includes(String(alan.type || '').toLowerCase()))) return;
            const baslangic = alan.selectionStart;
            const bitis = alan.selectionEnd;
            const buyuk = String(alan.value || '').toLocaleUpperCase('tr-TR');
            if (alan.value === buyuk) return;
            alan.value = buyuk;
            if (baslangic !== null && bitis !== null) alan.setSelectionRange(baslangic, bitis);
        }, true);
        document.addEventListener('submit', event => {
            if (event.target.id === 'loginForm') return;
            event.target.querySelectorAll('input, textarea').forEach(alan => {
                if (alan.closest('[data-case-preserve="true"]') || (alan instanceof HTMLInputElement && !['text', 'search', 'tel'].includes(String(alan.type || '').toLowerCase()))) return;
                alan.value = String(alan.value || '').toLocaleUpperCase('tr-TR');
            });
        }, true);
        document.getElementById('pAskerlikDurumu').addEventListener('change', updateAskerlikTarihAlani);
        updateAskerlikTarihAlani();
        sirketModulunuBaslat();
        const rememberedUsername = localStorage.getItem('rememberedUsername');
        if (rememberedUsername) {
            document.getElementById('loginUser').value = rememberedUsername;
            document.getElementById('rememberLogin').checked = true;
        }
        loginSirketOnbelleginiYukle();
        populateLoginCompanySelect(true);
        document.getElementById('loginUser').addEventListener('input', girisKullaniciTipiniGuncelle);
        document.getElementById('loginCompany').addEventListener('change', () => {
            const select = document.getElementById('loginCompany');
            localStorage.setItem('lastSelectedCompanyId', select.value);
            localStorage.setItem('lastSelectedCompanyName', select.options[select.selectedIndex]?.text || '');
            if (document.getElementById('rememberLogin').checked) {
                localStorage.setItem('rememberedCompanyId', select.value);
                localStorage.setItem('rememberedCompanyName', select.options[select.selectedIndex]?.text || '');
            }
        });
        document.getElementById('rememberLogin').addEventListener('change', (event) => {
            if (event.target.checked) {
                const select = document.getElementById('loginCompany');
                localStorage.setItem('rememberedUsername', document.getElementById('loginUser').value.trim());
                localStorage.setItem('rememberedCompanyId', select.value || '');
                localStorage.setItem('rememberedCompanyName', select.options[select.selectedIndex]?.text || '');
            } else {
                localStorage.removeItem('rememberedUsername');
                localStorage.removeItem('rememberedCompanyId');
                localStorage.removeItem('rememberedCompanyName');
            }
        });
        document.getElementById('puanAySec').value = new Date().getMonth();
        if (SUPABASE_MODE) {
            document.querySelector('label[for="loginUser"]').textContent = 'Kullanıcı adı';
            document.getElementById('loginUser').type = 'text';
            document.getElementById('loginUser').placeholder = 'Kullanıcı adınızı girin';
            document.getElementById('loginCompanyGroup').style.display = '';
            document.querySelector('label[for="rememberLogin"]').style.display = '';
            supabaseGirisSirketleriniYukle();
            girisYuklemeSozu = Promise.resolve();
        } else {
            girisYuklemeSozu = driveVerileriniYukleBaslangicta('girizhizli').then(() => {
                if (sessionStorage.getItem('loggedInUser')) initUI();
            }).catch(error => {
                console.error('Giriş verileri yüklenemedi:', error);
            });
        }

        document.addEventListener('click', () => {
            document.getElementById('customContextMenu').style.display = 'none';
        });
    });

    function kayitYiliniSeciliEkrandanBul(modul) {
        if (modul === 'puantaj') return document.getElementById('puanYilSec')?.value || aktifKayitYili;
        if (modul === 'ekodeme') return String(document.getElementById('ekOdemeAySec')?.value || '').slice(0, 4) || aktifKayitYili;
        return aktifKayitYili || String(new Date().getFullYear());
    }

