    function eksikSirketKimlikleriniTamamla() {
        const mevcutKimlikler = new Set(sirketler.map(s => String(s.id || '')).filter(Boolean));
        const adayKimlikler = [...personeller, ...kullanicilar, ...subeler]
            .map(kayit => String(kayit?.sirketId || ''))
            .filter(id => id && !mevcutKimlikler.has(id));
        const benzersizAdaylar = [...new Set(adayKimlikler)];
        const kimliksizSirketler = sirketler.filter(s => !String(s.id || ''));
        if (kimliksizSirketler.length === 1 && benzersizAdaylar.length === 1) {
            kimliksizSirketler[0].id = benzersizAdaylar[0];
        }
    }

