    function anaMenuDonusButonunuGoster() {}

    function workspaceSekmesiniAktifEt(hedef) {
        const vardiyaApp = document.getElementById('vardiyaApp');
        if (vardiyaApp && hedef !== 'vardiya') vardiyaApp.style.display = 'none';
        const fonksiyonlar = {
            ozet: 'openPersonelDashboard', personel: 'openPersonelApp', izin: 'openIzinTakipApp',
            puantaj: 'openPuantajApp', prim: 'openPrimApp', avans: 'openAvansApp',
            icra: 'openIcraApp', vardiya: 'openVardiyaApp', giriscikis: 'openMagicpassApp'
        };
        document.querySelectorAll('.workspace-nav button').forEach(button => {
            const tiklama = button.getAttribute('onclick') || '';
            const aktif = button.dataset.workspace === hedef || (fonksiyonlar[hedef] && tiklama.includes(fonksiyonlar[hedef]));
            button.classList.toggle('active', Boolean(aktif));
        });
    }

    async function openVardiyaApp() {
        anaMenuDonusButonunuGoster();
        ['appHub','personelDashboardApp','personelApp','izinTakipApp','puantajApp','avansApp','sirketApp','icraApp','ekOdemeApp','kkdApp','aracTakipApp','ayarlarApp','magicpassApp'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.style.display = 'none';
        });
        document.getElementById('vardiyaApp').style.display = 'block';
        workspaceSekmesiniAktifEt('vardiya');
        const app = document.getElementById('vardiyaApp'), board = document.getElementById('vardiyaBoard');
        const session = fdPortalVeriOturumu(), user = String(activeUser?.id || activeUser?.username || '');
        const version = app.__fdLoadVersion = (app.__fdLoadVersion || 0) + 1;
        const current = () => session === fdPortalVeriOturumu() && user === String(activeUser?.id || activeUser?.username || '') && app.__fdLoadVersion === version && app.style.display === 'block';
        const status = document.getElementById('fdVardiyaKayitDurumu'); if (status) status.hidden = true;
        app.inert = true;
        try {
            if (SUPABASE_MODE) {
                board.textContent = 'Vardiya listesi yükleniyor…';
                await fdVardiyaHizliListeYukle();
            } else if (!fdModulVerisiTazeMi('vardiya')) {
                board.textContent = 'Vardiya listesi yükleniyor…';
                await driveVerileriniYukleBaslangicta('vardiya');
            }
            if (!current()) return false;
            if (SUPABASE_MODE && !yuklenenVeriler.has('vardiya') && !vardiyaKayitlari.some(aktifSirketeAit) && !window.fdVardiyaHaftalikListeHazirMi?.()) throw Error('Vardiya listesi sunucudan alınamadı.');
            vardiyaFiltreleriniHazirla();
            vardiyaCiz();
            return true;
        } catch (error) {
            if (!current()) return false;
            board.innerHTML = '<div role="alert" style="padding:20px">Vardiya listesi yüklenemedi. <button type="button" onclick="openVardiyaApp()">Tekrar dene</button></div>';
            showToast('Vardiya listesi yüklenemedi. Bağlantınızı kontrol edip tekrar deneyin.', 'error');
            return false;
        } finally { if (app.__fdLoadVersion === version) app.inert = false; }
    }

    async function openMagicpassApp() {
        anaMenuDonusButonunuGoster();
        ['appHub','personelDashboardApp','personelApp','izinTakipApp','puantajApp','avansApp','sirketApp','icraApp','ekOdemeApp','kkdApp','aracTakipApp','ayarlarApp','vardiyaApp','irsaliyeTakipApp','kiraTakipApp','ihracatApp'].forEach(id => {
            const el = document.getElementById(id);
            if (el) el.style.display = 'none';
        });
        document.getElementById('magicpassApp').style.display = 'block';
        workspaceSekmesiniAktifEt('giriscikis');
        if (isPersonelUser()) {
            const listeButonu = document.querySelector('#magicpassAltSekmeler button[onclick*="magicpass-tab-liste"]');
            magicpassSekmeAc('magicpass-tab-liste', listeButonu);
        }
        const magicpassSube=document.getElementById('magicpassSubeFiltre');if(magicpassSube)magicpassSube.dataset.fabrikaVarsayilan='1';
        magicpassArayuzunuHazirla();
        if (!fdModulVerisiTazeMi('vardiya')) {
            driveVerileriniYukleBaslangicta('vardiya').then(() => {
                if (document.getElementById('magicpassApp')?.style.display !== 'block') return;
                magicpassArayuzunuHazirla();
            }).catch(error => {
                console.error('Giriş-çıkış verileri yenilenemedi:', error);
                showToast('Giriş-çıkış verileri arka planda yenilenemedi.', 'warning');
            });
        }
        if (!isPersonelUser()) magicpassDosyaDurumunuGuncelle().catch(error => console.warn('Giriş-çıkış dosya durumu alınamadı:', error));
    }

    function toggleSidebar() {
        const pSide = document.getElementById('pSidebar');
        const iSide = document.getElementById('iSidebar');
        const puanSide = document.getElementById('puantajSidebar');
        if(pSide) pSide.classList.toggle('collapsed');
        if(iSide) iSide.classList.toggle('collapsed');
        if(puanSide) puanSide.classList.toggle('collapsed');
    }

    function fdSelectDegerleriniSakla(seciciler) {
        return Object.fromEntries(seciciler.map(id => [id, document.getElementById(id)?.value ?? '']));
    }

    function fdSelectDegerleriniGeriYukle(degerler) {
        Object.entries(degerler || {}).forEach(([id, deger]) => {
            const alan = document.getElementById(id);
            if (alan && [...alan.options].some(option => option.value === deger)) alan.value = deger;
        });
    }

    function fdPersonelArayuzunuYenile(filtreleriYenile = false) {
        if (filtreleriYenile) {
            const secimler = fdSelectDegerleriniSakla(['fAktifSube','fAktifYil','fAktifEngelli','fAktifEmekli','fAktifSiralama','fAyrilanSube','fAyrilanCikisYili','fAyrilanEngelli','fAyrilanEmekli']);
            filtreDropdownlariDoldur();
            fdSelectDegerleriniGeriYukle(secimler);
            syncSubeDatalist();
        }
        renderPersonelTables();
        yillikPersonelBelgeButonunuGuncelle();
    }

    function fdIzinArayuzunuYenile(filtreleriYenile = false) {
        if (filtreleriYenile) {
            const secimler = fdSelectDegerleriniSakla(['fBakiyeSube','fBakiyeDonem']);
            filtreDropdownlariDoldur();
            fdSelectDegerleriniGeriYukle(secimler);
        }
        renderIzinDashAndTables();
        renderBakiyeTable();
        personelSelectDoldur();
    }

