    function ekOdemeSekmeleriniKur() {
        const kaynak = document.querySelector('#personelApp .workspace-nav');
        if (!kaynak) return;
        ['#ekOdemeApp .workspace-nav', '#kkdApp .workspace-nav', '#vardiyaApp .workspace-nav', '#magicpassApp .workspace-nav'].forEach(secici => {
            const hedef = document.querySelector(secici);
            if (hedef && !hedef.children.length) hedef.innerHTML = kaynak.innerHTML;
        });
        const ekle = nav => {
            if (!nav.querySelector('[data-workspace="ekodeme"]')) {
                const ekOdemeButon = document.createElement('button');
                ekOdemeButon.type = 'button'; ekOdemeButon.textContent = 'Ek Ödeme'; ekOdemeButon.dataset.workspace = 'ekodeme'; ekOdemeButon.onclick = openEkOdemeApp;
                nav.appendChild(ekOdemeButon);
            }
            if (!nav.querySelector('[data-workspace="kkd"]')) {
                const kkdButon = document.createElement('button');
                kkdButon.type = 'button'; kkdButon.textContent = 'KKD Takip'; kkdButon.dataset.workspace = 'kkd'; kkdButon.onclick = openKkdApp;
                nav.appendChild(kkdButon);
            }
            if (!nav.querySelector('[data-workspace="vardiya"]')) {
                const vardiyaButon = document.createElement('button');
                vardiyaButon.type = 'button'; vardiyaButon.textContent = 'Vardiya'; vardiyaButon.dataset.workspace = 'vardiya'; vardiyaButon.onclick = openVardiyaApp;
                nav.appendChild(vardiyaButon);
            }
            if (!nav.querySelector('[data-workspace="giriscikis"]')) {
                const girisCikisButon = document.createElement('button');
                girisCikisButon.type = 'button'; girisCikisButon.textContent = 'Giriş–Çıkış'; girisCikisButon.dataset.workspace = 'giriscikis'; girisCikisButon.onclick = openMagicpassApp;
                nav.appendChild(girisCikisButon);
            }
        };
        document.querySelectorAll('#personelDashboardApp .workspace-nav, #personelApp .workspace-nav, #izinTakipApp .workspace-nav, #puantajApp .workspace-nav, #avansApp .workspace-nav, #icraApp .workspace-nav, #ekOdemeApp .workspace-nav, #kkdApp .workspace-nav, #vardiyaApp .workspace-nav, #magicpassApp .workspace-nav').forEach(ekle);
        document.querySelectorAll('.workspace-nav button[onclick="openPersonelDashboard()"]')
            .forEach(button => { button.textContent = 'Özet'; });
    }

