    let avansIslemSuruyor = false;
    let avansDuzenlemeKopyasi = null;
    let avansYeniTaslakId = '';
    function avansJsonAyniMi(a, b) {
        const sirala = v => Array.isArray(v) ? v.map(sirala) : v && typeof v === 'object' ? Object.fromEntries(Object.keys(v).sort().map(k => [k, sirala(v[k])])) : v;
        return JSON.stringify(sirala(a)) === JSON.stringify(sirala(b));
    }
    function avansIslemYetkisiVar() { return isManagerUser() && !isPersonelUser() && !['IsgUzmani','IsyeriHekimi'].includes(activeUser?.rol); }
    function avansSunucuKaydiniUygula(kayit, onceki, goruntuGuncelle = true) {
        const id = String(kayit.legacy_id), dogrulanan = { ...kayit.data, id:String(kayit.data.id || id) };
        const index = avanslar.findIndex(a => String(a.id) === id);
        if (index < 0 ? onceki === null : avansJsonAyniMi(avanslar[index], onceki)) {
            if (index < 0) avanslar.push(dogrulanan); else avanslar[index] = dogrulanan;
        }
        if (goruntuGuncelle) {
            const goruntu = JSON.parse(veriSonKayitGoruntuleri.get('avanslar') || '[]'), sira = goruntu.findIndex(a => String(a.id) === id);
            if (sira < 0) goruntu.push(dogrulanan); else goruntu[sira] = dogrulanan;
            veriSonKayitGoruntuleri.set('avanslar', JSON.stringify(goruntu));
            veriOnbelleginiKaydet();
        }
        return dogrulanan;
    }
    async function avansGuvenliSunucuKaydi(sirketId, kayit, onceki) {
        const { data, error } = await supabaseClient.rpc('fd_advance_save', { p_company_id:sirketId, p_id:String(kayit.id), p_expected:onceki, p_data:kayit });
        if (error) throw error;
        if (!data?.data || String(data.legacy_id) !== String(kayit.id)) throw new Error('Avans kaydı sunucuda doğrulanamadı. Listeyi yenileyip kontrol edin.');
        return data;
    }
    async function avansGuvenliSunucuSil(sirketId, id, onceki) {
        const { data, error } = await supabaseClient.rpc('fd_advance_delete', { p_company_id:sirketId, p_id:String(id), p_expected:onceki });
        if (error) throw error;
        if (!data?.deleted || String(data.legacy_id) !== String(id)) throw new Error('Avans silme işlemi doğrulanamadı. Listeyi yenileyip kontrol edin.');
        return data;
    }
    function avansAnahtariniTemizle(deger) {
        return String(deger || '')
            .toLocaleLowerCase('tr-TR')
            .replace(/ı/g, 'i').replace(/ş/g, 's').replace(/ğ/g, 'g')
            .replace(/ü/g, 'u').replace(/ö/g, 'o').replace(/ç/g, 'c')
            .replace(/[^a-z0-9]/g, '');
    }

    function avansSatiriniDonustur(satir) {
        if (!satir || typeof satir !== 'object' || Array.isArray(satir)) return null;
        const alanlar = {};
        Object.keys(satir).forEach(anahtar => {
            alanlar[avansAnahtariniTemizle(anahtar)] = satir[anahtar];
        });
        const al = (...adlar) => {
            for (const ad of adlar) {
                const deger = alanlar[avansAnahtariniTemizle(ad)];
                if (deger !== undefined && deger !== null && deger !== '') return deger;
            }
            return '';
        };
        const personelId = al('pId', 'personelId', 'personel id', 'tcNo', 'tc');
        const personel = personeller.find(p => String(p.id) === String(personelId));
        const tarih = tarihInputDegeri(al('kayitTarihi', 'yatirmaTarihi', 'avansYatirmaTarihi', 'kayıt tarihi', 'yatırma tarihi'));
        const baslangicHam = al('baslangicAy', 'kesintiBaslangicAy', 'başlangıç ayı', 'kesinti başlangıç ayı');
        const baslangicEslesme = String(baslangicHam).match(/(\d{4})-(\d{1,2})/);
        return {
            ...satir,
            id: String(al('id', 'avansId') || `avans_${Date.now()}_${Math.random().toString(36).slice(2)}`),
            avansNo: String(al('avansNo', 'avans no', 'referansNo') || ''),
            sirketId: String(al('sirketId', 'şirket id', 'firmaId') || personel?.sirketId || ''),
            pId: String(personelId || ''),
            personelAd: String(al('personelAd', 'personel adı', 'adSoyad', 'ad soyad') || personel?.ad || ''),
            sube: String(al('sube', 'şube') || personel?.sube || ''),
            tutar: typeof al('tutar', 'avansTutari', 'avans tutarı', 'toplam avans') === 'number' ? al('tutar', 'avansTutari', 'avans tutarı', 'toplam avans') : paraMetniniSayiyaCevir(al('tutar', 'avansTutari', 'avans tutarı', 'toplam avans')),
            taksitSayisi: Math.max(1, Number(al('taksitSayisi', 'taksit sayısı', 'kacAy', 'kaç ay') || 1)),
            baslangicAy: baslangicEslesme ? `${baslangicEslesme[1]}-${String(baslangicEslesme[2]).padStart(2, '0')}` : '',
            kayitTarihi: tarih,
            aciklama: String(al('aciklama', 'açıklama', 'avansAciklama') || ''),
            durum: String(al('durum', 'status') || 'Aktif')
        };
    }

    function avansDizisiniBul(data) {
        if (Array.isArray(data)) return data;
        if (!data || typeof data !== 'object') return [];
        for (const anahtar of Object.keys(data)) {
            if (['avans', 'avanslar', 'avanskayitlari'].includes(avansAnahtariniTemizle(anahtar)) && Array.isArray(data[anahtar])) {
                return data[anahtar];
            }
        }
        return [];
    }

    async function avansVerileriniYukle() {
        if (SUPABASE_MODE) {
            // The shared loader acknowledges only actual server replies. Never
            // normalize/re-acknowledge unsaved local changes after a skipped load.
            return supabaseVerileriniYukle('avans', '', { yerelDegisiklikleriKoru:true });
        }
        const response = await fetch(`${GOOGLE_SCRIPT_URL}?modul=avans&_=${Date.now()}`, { cache: 'no-store' });
        if (!response.ok) throw new Error(`Avans verisi alınamadı (${response.status})`);
        const data = await response.json();
        avanslar = avansDizisiniBul(data).map(avansSatiriniDonustur).filter(Boolean);
        yuklenenVeriler.add('avanslar');
        veriOnbelleginiKaydet();
    }

    async function avansListeyiYenile() {
        if (avansIslemSuruyor || !SUPABASE_MODE || !supabaseClient) return;
        if (supabaseKaydetmeBekleyen > 0) return showToast('Kayıt işlemi devam ediyor. Tamamlanınca listeyi yenileyin.','warning');
        const oturum=fdPortalVeriOturumu(), yerel=JSON.stringify(avanslar), btn=document.getElementById('avansListeYenileBtn');
        avansIslemSuruyor=true;if(btn)btn.disabled=true;
        try {
            if(veriSonKayitGoruntuleri.has('avanslar')&&veriSonKayitGoruntuleri.get('avanslar')!==yerel) {
                if(!await fdYuzerOnaySor('Bu cihazda kaydedilmemiş avans değişiklikleri var. Sunucudaki kayıtlar değişmeden, yalnızca bu cihazdaki kaydedilmemiş değişiklikler bırakılıp güncel liste yüklensin mi?','Avans Listesini Yenile','Güncel Listeyi Yükle'))return;
            }
            if(!fdPortalVeriOturumuGecerli(oturum))return;
            const yil=Number(aktifKayitYili||new Date().getFullYear()),rows=await supabasePortalModulKayitlariniTumunuGetir('avanslar',yil);
            if(!fdPortalVeriOturumuGecerli(oturum))return;
            if(JSON.stringify(avanslar)!==yerel)throw Error('Avans bilgileri bu sırada değişti; yenileme iptal edildi.');
            supabaseDiziAta('avanslar',rows.map(r=>({...r.data,id:r.data?.id??r.legacy_id})));
            fdUzakImzayiSatirlardanKaydet('avanslar',yil,rows);fdUzakAnahtarSonYukleme.set(fdUzakImzaAnahtari('avanslar',yil),Date.now());
            veriOnbelleginiKaydet();renderAvansKayitListesi();renderAvansKesintiListesi();renderAvansGelecekKesintileri();showToast('Avans listesi sunucudan yenilendi.');
        }catch(error){if(fdPortalVeriOturumuGecerli(oturum))showToast('Liste yenilenemedi: '+(error.message||error),'warning');}
        finally{avansIslemSuruyor=false;if(btn)btn.disabled=false;}
    }

    function avansSekmeDegistir(sekme, button) {
        if (sekme === 'yeni' && activeUser?.rol === 'Personel') return;
        const kartlar = {
            yeni: document.getElementById('avansKayitCard'),
            kayitlar: document.getElementById('avansKayitlarCard'),
            aylik: document.getElementById('avansAylikCard'),
            gelecek: document.getElementById('avansGelecekCard')
        };
        Object.entries(kartlar).forEach(([ad, kart]) => {
            if (kart) kart.style.display = ad === sekme ? '' : 'none';
        });
        document.querySelectorAll('#avansApp .module-subnav button').forEach(el => el.classList.remove('active'));
        if (button) button.classList.add('active');
        if (sekme === 'kayitlar') renderAvansKayitListesi();
        if (sekme === 'aylik') renderAvansKesintiListesi();
        if (sekme === 'gelecek') renderAvansGelecekKesintileri();
    }
    let avansDuzenlemeId = '';

    function avansYeniKayitAc() {
        if (avansIslemSuruyor || !avansIslemYetkisiVar()) return;
        avansFormReset();
        avansSekmeDegistir('yeni', document.getElementById('btnAvansYeniSekme'));
    }

    function avansDuzenleVazgec() {
        if (avansIslemSuruyor) return;
        avansFormReset();
        avansSekmeDegistir('kayitlar', document.getElementById('btnAvansKayitlarSekme'));
    }

    function openAvansApp() {
        icraEkraniniKapat();
        if (!activeUser) return;
        anaMenuDonusButonunuGoster();
        document.getElementById('appHub').style.display = 'none';
        document.getElementById('personelApp').style.display = 'none';
        document.getElementById('izinTakipApp').style.display = 'none';
        document.getElementById('puantajApp').style.display = 'none';
        document.getElementById('sirketApp').style.display = 'none';
        document.getElementById('ekOdemeApp').style.display = 'none';
        document.getElementById('kkdApp').style.display = 'none';
        document.getElementById('avansApp').style.display = 'block';
        workspaceSekmesiniAktifEt('avans');
        document.getElementById('btnAvansYeniSekme').style.display = activeUser.rol === 'Personel' ? 'none' : '';
        avansSekmeDegistir('kayitlar', document.getElementById('btnAvansKayitlarSekme'));
        const ayInput = document.getElementById('avansListeAy');
        const baslangicInput = document.getElementById('avansBaslangicAy');
        const now = new Date();
        const currentMonth = now.toISOString().slice(0, 7);
        const currentDate = now.toISOString().slice(0, 10);
        if (!ayInput.value) ayInput.value = currentMonth;
        if (!baslangicInput.value) baslangicInput.value = currentMonth;
        if (!document.getElementById('avansYatirmaTarihi').value) document.getElementById('avansYatirmaTarihi').value = currentDate;
        avansTaksitButonlariniOlustur();
        avansTaksitAlaniniGuncelle();
        avansPersonelListesiniDoldur();
        renderAvansKayitListesi();
        renderAvansKesintiListesi();
        if (!fdModulVerisiTazeMi('avans')) {
            avansVerileriniYukle().then(() => {
                if (document.getElementById('avansApp')?.style.display !== 'block') return;
                avansPersonelListesiniDoldur();
                renderAvansKayitListesi();
                renderAvansKesintiListesi();
                renderAvansGelecekKesintileri();
            }).catch(error => {
                console.error('Avans ekranı yükleme hatası:', error);
                showToast('Avans verileri arka planda yenilenemedi.', 'warning');
            });
        }
    }

    function avansPersonelListesiniDoldur() {
        const liste = document.getElementById('avansPersonelListesi');
        if (!liste) return;
        liste.innerHTML = '';
        personeller.filter(p => aktifSirketeAit(p) && !p.cikisTarihi).sort((a, b) => String(a.ad || '').localeCompare(String(b.ad || ''), 'tr')).forEach(p => {
            const option = document.createElement('option');
            option.value = `${p.ad} — ${p.sube || 'Şube yok'}`;
            option.dataset.id = p.id;
            liste.appendChild(option);
        });
    }

    function avansPersonelSecimKontrol() {
        const input = document.getElementById('avansPersonelAra');
        const personel = personeller.find(p => aktifSirketeAit(p) && `${p.ad} — ${p.sube || 'Şube yok'}` === input.value);
        document.getElementById('avansPersonelId').value = personel ? personel.id : '';
        document.getElementById('avansSeciliPersonel').textContent = personel ? `✓ Seçilen personel: ${personel.ad}` : '';
    }

    function avansTaksitAlaniniGuncelle() {
        document.querySelectorAll('#avansTaksitButonlari button').forEach(button => {
            button.disabled = false;
            button.style.opacity = '1';
            button.style.cursor = 'pointer';
        });
        avansPlanOnizle();
    }

    function avansTaksitButonlariniOlustur() {
        const alan = document.getElementById('avansTaksitButonlari');
        if (!alan || alan.children.length) return;
        for (let sayi = 1; sayi <= 12; sayi++) {
            const button = document.createElement('button');
            button.type = 'button';
            button.textContent = String(sayi);
            button.className = 'btn-modern';
            button.style.minWidth = '38px';
            button.style.justifyContent = 'center';
            button.onclick = () => avansTaksitSec(sayi);
            alan.appendChild(button);
        }
        avansTaksitSec(1);
    }

    function avansTaksitSec(sayi) {
        const deger = Math.min(12, Math.max(1, Number(sayi || 1)));
        document.getElementById('avansTaksitSayisi').value = String(deger);
        document.querySelectorAll('#avansTaksitButonlari button').forEach((button, index) => {
            const secili = index + 1 === deger;
            button.style.background = secili ? '#0284c7' : '#e2e8f0';
            button.style.color = secili ? '#fff' : '#334155';
        });
        avansPlanOnizle();
    }

    function avansPlanOnizle() {
        const tutar = paraMetniniSayiyaCevir(document.getElementById('avansTutar').value);
        const taksit = Number(document.getElementById('avansTaksitSayisi').value || 1);
        const plan = document.getElementById('avansPlanOnizleme');
        if (!tutar || !taksit) { plan.style.display = 'none'; return; }
        plan.style.display = 'block';
        plan.textContent = `${taksit} ay boyunca aylık yaklaşık ${paraFormatla(tutar / taksit)} kesilir. Son taksit kuruş farkını tamamlar.`;
    }

    function aySirasi(ay) {
        const eslesme = String(ay || '').match(/(\d{4})-(\d{1,2})/);
        if (!eslesme) return NaN;
        const yil = Number(eslesme[1]);
        const ayNo = Number(eslesme[2]);
        return yil * 12 + ayNo - 1;
    }

    function paraFormatla(tutar) {
        return Number(tutar || 0).toLocaleString('tr-TR', { style: 'currency', currency: 'TRY', minimumFractionDigits: 2 });
    }

    function personelBildirimSablonunuDoldur(ayarAnahtari, alanlar = {}) {
        const sablon = String(uygulamaAyarlari?.[ayarAnahtari] || VARSAYILAN_UYGULAMA_AYARLARI?.[ayarAnahtari] || '');
        const mesaj = Object.entries(alanlar).reduce((metin, [anahtar, deger]) =>
            metin.replaceAll(`{${anahtar}}`, String(deger ?? '')), sablon
        );
        if (mesaj.length > 4096) throw new Error('Bildirim metni çok uzun; eksik mesaj oluşturulmadı.');
        return mesaj;
    }

    async function personelKayitBildirimiGonder(personelId, baslik, mesaj, secenekler = {}) {
        if (!SUPABASE_MODE || !supabaseClient || !activeUser?.sirketId) return { atlandi:true };
        if (typeof window.fdPersonelOtomatikBildirimGonder !== 'function') throw new Error('Bildirim sistemi hazır değil.');
        return window.fdPersonelOtomatikBildirimGonder(String(personelId || ''), baslik, mesaj, Boolean(secenekler.ayrilanPersonel), String(secenekler.messageCategory || 'manual'));
    }

    const PERSONEL_UYGULAMA_ADRESI = 'https:\x2f\x2fkanalmermer.tr';

    async function personelBildirimleriniTopluGonder(bildirimler, eszamanli = 4) {
        const kuyruk = (Array.isArray(bildirimler) ? bildirimler : []).filter(item => item?.personelId && item?.mesaj);
        if (!kuyruk.length) return { toplam:0, gonderilen:0, kuyrukta:0, atlanan:0, basarisiz:0, hatalar:[] };
        let sira = 0, gonderilen = 0, kuyrukta = 0, atlanan = 0;
        const hatalar = [];
        const isci = async () => {
            while (sira < kuyruk.length) {
                const item = kuyruk[sira++];
                try {
                    const sonuc = await personelKayitBildirimiGonder(item.personelId, item.baslik, item.mesaj, item);
                    if (sonuc?.success === false || Number(sonuc?.failed || 0) > 0) throw new Error(sonuc?.failureReasons?.[0]?.error_message || sonuc?.message || 'WhatsApp bildirimi kuyruğa alınamadı.');
                    if (sonuc?.atlandi) atlanan++;
                    else if (Number(sonuc?.sent || 0) > 0 || sonuc?.alreadySent === true) gonderilen++;
                    else if (Number(sonuc?.queued || 0) > 0 || Number(sonuc?.accepted || 0) > 0 || sonuc?.alreadyQueued === true) kuyrukta++;
                    else throw new Error(sonuc?.failureReasons?.[0]?.error_message || 'WhatsApp bildirimi kuyruğa alınamadı.');
                } catch (error) {
                    hatalar.push({ personelId:String(item.personelId), hata:String(error?.message || error) });
                }
            }
        };
        await Promise.all(Array.from({ length:Math.min(Math.max(1, Number(eszamanli) || 1), kuyruk.length) }, () => isci()));
        return { toplam:kuyruk.length, gonderilen, kuyrukta, atlanan, basarisiz:hatalar.length, hatalar };
    }

    function vardiyaBildirimGonderimZamani() {
        const saatParcala=(deger,yedek)=>{const eslesme=String(deger||yedek).match(/^(\d{1,2}):(\d{2})$/);return eslesme?[Math.min(23,Number(eslesme[1])),Math.min(59,Number(eslesme[2]))]:yedek.split(':').map(Number)};
        const simdi = new Date(), gonderim = new Date(simdi), [aksamSaat,aksamDakika]=saatParcala(uygulamaAyarlari?.whatsappVardiyaAksamSaati,'20:00'), [ertesiSaat,ertesiDakika]=saatParcala(uygulamaAyarlari?.whatsappVardiyaErtesiGunSaati,'10:00');
        const bugunkuSinir=new Date(simdi);bugunkuSinir.setHours(aksamSaat,aksamDakika,0,0);
        if (simdi < bugunkuSinir) gonderim.setHours(aksamSaat,aksamDakika,0,0);
        else { gonderim.setDate(gonderim.getDate() + 1); gonderim.setHours(ertesiSaat,ertesiDakika,0,0); }
        return gonderim;
    }

    async function personelVardiyaBildirimleriniPlanla(bildirimler, fdIsCurrent = () => true) {
        if (!fdIsCurrent()) return { toplam:0,planlanan:0,basarisiz:0,atlandi:true };
        if (uygulamaAyarlari?.whatsappVardiyaOtomatikAktif === false) return { toplam:Array.isArray(bildirimler)?bildirimler.length:0, planlanan:0, basarisiz:0, atlandi:true };
        const izinliSubeler=new Set(whatsappVardiyaSubeleriniDuzelt());
        if(!izinliSubeler.size)return { toplam:Array.isArray(bildirimler)?bildirimler.length:0, planlanan:0, basarisiz:0, atlandi:true, neden:'Vardiya mesajı gönderilecek şube seçilmedi.' };
        const benzersiz = new Map();
        (Array.isArray(bildirimler) ? bildirimler : []).forEach(item => {
            const personel=personeller.find(p=>String(p.id)===String(item?.personelId)&&aktifSirketeAit(p));
            if (item?.personelId && item?.mesaj && personel && izinliSubeler.has(String(personel.sube||'').trim())) benzersiz.set(String(item.personelId), item);
        });
        if (!benzersiz.size) return { toplam:0, planlanan:0, basarisiz:0, hatalar:[] };
        if (typeof window.fdxPlanliBildirimApi !== 'function') return { toplam:benzersiz.size, planlanan:0, basarisiz:benzersiz.size, hatalar:[{ hata:'Planlı bildirim bağlantısı hazır değil.' }] };
        const scheduledFor = vardiyaBildirimGonderimZamani().toISOString(), hatalar=[];
        let planlanan=0, atlanan=0;
        for (const item of benzersiz.values()) {
            if (!fdIsCurrent()) break;
            try {
                const cevap = await window.fdxPlanliBildirimApi({
                    action:'schedule-shift-upsert', employeeId:String(item.personelId),
                    title:item.baslik || 'Vardiya Planınız Güncellendi', message:item.mesaj, scheduledFor
                }, fdIsCurrent);
                if (!fdIsCurrent()) break;
                if (cevap?.success === false) throw new Error(cevap.message || 'WhatsApp mesajı planlanamadı.');
                if (cevap?.atlandi) atlanan++; else planlanan++;
            } catch (error) {
                if (!fdIsCurrent()) break;
                hatalar.push({ personelId:String(item.personelId), hata:String(error?.message || error) });
            }
        }
        return { toplam:benzersiz.size, planlanan, atlanan, basarisiz:hatalar.length, hatalar, scheduledFor };
    }

    function izinBildirimGonderimZamani() {
        const dakika=Math.min(120,Math.max(0,Number(uygulamaAyarlari?.whatsappIzinBeklemeDakika??3)));
        return new Date(Date.now() + dakika * 60 * 1000);
    }
    function izinBildirimBeklemeMetni(){const dakika=Math.min(120,Math.max(0,Number(uygulamaAyarlari?.whatsappIzinBeklemeDakika??3)));return dakika?dakika+' dakikalık düzeltme süresiyle':'bekletilmeden';}

    async function personelIzinBildirimleriniPlanla(bildirimler) {
        if (uygulamaAyarlari?.whatsappIzinOtomatikAktif === false) return { toplam:Array.isArray(bildirimler)?bildirimler.length:0, planlanan:0, basarisiz:0, atlandi:true };
        const benzersiz = new Map();
        (Array.isArray(bildirimler) ? bildirimler : []).forEach(item => {
            if (item?.personelId && item?.mesaj) benzersiz.set(String(item.personelId), item);
        });
        if (!benzersiz.size) return { toplam:0, planlanan:0, basarisiz:0, hatalar:[] };
        if (typeof window.fdxPlanliBildirimApi !== 'function') return { toplam:benzersiz.size, planlanan:0, basarisiz:benzersiz.size, hatalar:[{ hata:'WhatsApp gönderim kuyruğu hazır değil.' }] };
        const scheduledFor = izinBildirimGonderimZamani().toISOString(), hatalar=[];
        let planlanan=0, atlanan=0;
        for (const item of benzersiz.values()) {
            try {
                const cevap = await window.fdxPlanliBildirimApi({
                    action:'schedule-leave-upsert', employeeId:String(item.personelId),
                    title:item.baslik || 'İzin Kaydınız Güncellendi', message:item.mesaj, scheduledFor
                });
                if (cevap?.success === false) throw new Error(cevap.message || 'WhatsApp mesajı planlanamadı.');
                if (cevap?.atlandi) atlanan++; else planlanan++;
            } catch (error) {
                hatalar.push({ personelId:String(item.personelId), hata:String(error?.message || error) });
            }
        }
        return { toplam:benzersiz.size, planlanan, atlanan, basarisiz:hatalar.length, hatalar, scheduledFor };
    }

    async function personelIzinBildiriminiIptalEt(personelId) {
        if (!personelId || typeof window.fdxPlanliBildirimApi !== 'function') return { iptalEdilen:0 };
        try { return await window.fdxPlanliBildirimApi({ action:'schedule-leave-cancel', employeeId:String(personelId) }); }
        catch (error) { console.warn('Bekleyen izin WhatsApp mesajı iptal edilemedi:', error); return { iptalEdilen:0, hata:error }; }
    }

    function personelBildirimTarihleriniYaz(tarihler) {
        const liste = [...new Set((Array.isArray(tarihler) ? tarihler : [tarihler]).map(tarih => String(tarih || '').slice(0,10)).filter(Boolean))].sort();
        if (!liste.length) return '-';
        if (liste.length === 1) return tarihFormati(liste[0]) + ' tarihinde';
        const ardArda = liste.every((tarih, index) => !index || Math.round((new Date(tarih+'T12:00:00') - new Date(liste[index-1]+'T12:00:00')) / 86400000) === 1);
        return ardArda ? tarihFormati(liste[0]) + ' - ' + tarihFormati(liste[liste.length-1]) + ' tarihleri arasında' : liste.map(tarihFormati).join(', ') + ' tarihlerinde';
    }

