    async function zamanAsimliBekle(islem, sure = 15000, mesaj = 'Veritabanı zamanında yanıt vermedi.') {
        let timer;
        try{return await Promise.race([Promise.resolve(islem),new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(mesaj)),sure)})]);}
        finally{clearTimeout(timer);}
    }

