    function wordBelgesiKirmiziGruplari(xmlBelgesi) {
        const wordNs = 'http:\x2f\x2fschemas.openxmlformats.org/wordprocessingml/2006/main';
        const runlar = Array.from(xmlBelgesi.getElementsByTagNameNS(wordNs, 'r'));
        const gruplar = [];
        let grup = [];
        runlar.forEach(run => {
            const metinler = Array.from(run.getElementsByTagNameNS(wordNs, 't'));
            const metin = metinler.map(node => node.textContent || '').join('');
            const renkler = Array.from(run.getElementsByTagNameNS(wordNs, 'color'));
            const kirmizi = renkler.some(node => {
                const deger = String(node.getAttributeNS(wordNs, 'val') || node.getAttribute('w:val') || node.getAttribute('val') || '').toUpperCase();
                return ['FF0000','F00','RED'].includes(deger);
            });
            if (kirmizi && metinler.length) {
                grup.push({ run, metinler, renkler });
            } else if (metin.trim() && grup.length) {
                gruplar.push(grup);
                grup = [];
            }
        });
        if (grup.length) gruplar.push(grup);
        return gruplar;
    }

    async function wordBelgesiKirmiziGrupSayisi(arrayBuffer) {
        if (!window.JSZip) throw new Error('Word dosyası okuyucusu yüklenemedi.');
        const zip = await JSZip.loadAsync(arrayBuffer);
        const parca = zip.file('word/document.xml');
        if (!parca) throw new Error('Geçerli bir DOCX belgesi seçin.');
        const xml = await parca.async('string');
        const belge = new DOMParser().parseFromString(xml, 'application/xml');
        if (belge.querySelector('parsererror')) throw new Error('Word belgesinin içeriği okunamadı.');
        return wordBelgesiKirmiziGruplari(belge).length;
    }

    function wordXmlElemaniOlustur(belge, ad, ozellikler = {}) {
        const wordNs = 'http:\x2f\x2fschemas.openxmlformats.org/wordprocessingml/2006/main';
        const eleman = belge.createElementNS(wordNs, 'w:' + ad);
        Object.entries(ozellikler).forEach(([anahtar, deger]) => eleman.setAttributeNS(wordNs, 'w:' + anahtar, String(deger)));
        return eleman;
    }

    function wordImzaParagrafiOlustur(belge, metin, kalin = false, once = 0, sonra = 80) {
        const xmlNs = 'http:\x2f\x2fwww.w3.org/XML/1998/namespace';
        const paragraf = wordXmlElemaniOlustur(belge, 'p');
        const paragrafAyar = wordXmlElemaniOlustur(belge, 'pPr');
        paragrafAyar.appendChild(wordXmlElemaniOlustur(belge, 'spacing', { before:once, after:sonra, line:240, lineRule:'auto' }));
        paragraf.appendChild(paragrafAyar);
        const run = wordXmlElemaniOlustur(belge, 'r');
        const runAyar = wordXmlElemaniOlustur(belge, 'rPr');
        runAyar.appendChild(wordXmlElemaniOlustur(belge, 'rFonts', { ascii:'Arial', hAnsi:'Arial', cs:'Arial' }));
        runAyar.appendChild(wordXmlElemaniOlustur(belge, 'sz', { val:'22' }));
        runAyar.appendChild(wordXmlElemaniOlustur(belge, 'szCs', { val:'22' }));
        if (kalin) runAyar.appendChild(wordXmlElemaniOlustur(belge, 'b'));
        run.appendChild(runAyar);
        const yazi = wordXmlElemaniOlustur(belge, 't');
        yazi.setAttributeNS(xmlNs, 'xml:space', 'preserve');
        yazi.textContent = String(metin || ' ');
        run.appendChild(yazi);
        paragraf.appendChild(run);
        return paragraf;
    }

    function wordOnayBelgesiImzaAlaniniDuzenle(belge, personelAdi) {
        const wordNs = 'http:\x2f\x2fschemas.openxmlformats.org/wordprocessingml/2006/main';
        const body = belge.getElementsByTagNameNS(wordNs, 'body')[0];
        if (!body) return;
        const cocuklar = Array.from(body.children);
        const anaMetin = cocuklar.find(eleman => eleman.localName === 'p' && /kabul ve beyan ederim|muvafakatim olduğunu/i.test(eleman.textContent || ''));
        if (!anaMetin) return;
        const bolumAyari = cocuklar.find(eleman => eleman.localName === 'sectPr') || null;
        let sonraki = anaMetin.nextSibling;
        while (sonraki && sonraki !== bolumAyari) {
            const silinecek = sonraki;
            sonraki = sonraki.nextSibling;
            body.removeChild(silinecek);
        }

        const tablo = wordXmlElemaniOlustur(belge, 'tbl');
        const tabloAyar = wordXmlElemaniOlustur(belge, 'tblPr');
        tabloAyar.appendChild(wordXmlElemaniOlustur(belge, 'tblW', { w:'9000', type:'dxa' }));
        tabloAyar.appendChild(wordXmlElemaniOlustur(belge, 'tblLayout', { type:'fixed' }));
        const kenarlar = wordXmlElemaniOlustur(belge, 'tblBorders');
        ['top','left','bottom','right','insideH','insideV'].forEach(ad => kenarlar.appendChild(wordXmlElemaniOlustur(belge, ad, { val:'nil' })));
        tabloAyar.appendChild(kenarlar);
        const hucreBosluk = wordXmlElemaniOlustur(belge, 'tblCellMar');
        ['top','left','bottom','right'].forEach(ad => hucreBosluk.appendChild(wordXmlElemaniOlustur(belge, ad, { w:ad === 'top' ? '300' : '120', type:'dxa' })));
        tabloAyar.appendChild(hucreBosluk);
        tablo.appendChild(tabloAyar);
        const grid = wordXmlElemaniOlustur(belge, 'tblGrid');
        grid.appendChild(wordXmlElemaniOlustur(belge, 'gridCol', { w:'4500' }));
        grid.appendChild(wordXmlElemaniOlustur(belge, 'gridCol', { w:'4500' }));
        tablo.appendChild(grid);
        const satir = wordXmlElemaniOlustur(belge, 'tr');
        const satirAyar = wordXmlElemaniOlustur(belge, 'trPr');
        satirAyar.appendChild(wordXmlElemaniOlustur(belge, 'cantSplit'));
        satir.appendChild(satirAyar);
        [
            ['İŞÇİ', 'Adı Soyadı: ' + String(personelAdi || '').toLocaleUpperCase('tr-TR'), 'İmza:'],
            ['İŞVEREN', 'Yetkili Adı Soyadı:', 'İmza / Kaşe:']
        ].forEach((satirlar, hucreIndex) => {
            const hucre = wordXmlElemaniOlustur(belge, 'tc');
            const hucreAyar = wordXmlElemaniOlustur(belge, 'tcPr');
            hucreAyar.appendChild(wordXmlElemaniOlustur(belge, 'tcW', { w:'4500', type:'dxa' }));
            hucreAyar.appendChild(wordXmlElemaniOlustur(belge, 'vAlign', { val:'top' }));
            hucre.appendChild(hucreAyar);
            hucre.appendChild(wordImzaParagrafiOlustur(belge, satirlar[0], true, 0, 220));
            hucre.appendChild(wordImzaParagrafiOlustur(belge, satirlar[1], false, 0, 300));
            hucre.appendChild(wordImzaParagrafiOlustur(belge, satirlar[2], false, 0, 0));
            satir.appendChild(hucre);
        });
        tablo.appendChild(satir);
        body.insertBefore(tablo, bolumAyari);
    }

    async function personelWordBelgesiniHazirla(arrayBuffer, degerler, belgeKey = '') {
        if (!window.JSZip) throw new Error('Word dosyası okuyucusu yüklenemedi.');
        const zip = await JSZip.loadAsync(arrayBuffer);
        const parca = zip.file('word/document.xml');
        if (!parca) throw new Error('Geçerli bir DOCX belgesi bulunamadı.');
        const xml = await parca.async('string');
        const belge = new DOMParser().parseFromString(xml, 'application/xml');
        if (belge.querySelector('parsererror')) throw new Error('Word belgesinin içeriği okunamadı.');
        const gruplar = wordBelgesiKirmiziGruplari(belge);
        if (gruplar.length !== degerler.length) throw new Error('Belgedeki otomatik alan sayısı değişmiş. Beklenen: ' + degerler.length + ', bulunan: ' + gruplar.length + '. Kırmızı alanları kontrol edip şablonu yeniden yükleyin.');
        const wordNs = 'http:\x2f\x2fschemas.openxmlformats.org/wordprocessingml/2006/main';
        const xmlNs = 'http:\x2f\x2fwww.w3.org/XML/1998/namespace';
        gruplar.forEach((grup, index) => {
            let ilkMetin = null;
            grup.forEach(kayit => {
                kayit.renkler.forEach(renk => renk.setAttributeNS(wordNs, 'w:val', '000000'));
                kayit.metinler.forEach(metin => {
                    if (!ilkMetin) ilkMetin = metin;
                    metin.textContent = '';
                });
            });
            if (ilkMetin) {
                ilkMetin.textContent = String(degerler[index] || '');
                ilkMetin.setAttributeNS(xmlNs, 'xml:space', 'preserve');
            }
        });
        if (['fazlaMesaiOnayi','vardiyaliCalismaOnayi'].includes(belgeKey)) wordOnayBelgesiImzaAlaniniDuzenle(belge, degerler[4]);
        zip.file('word/document.xml', new XMLSerializer().serializeToString(belge));
        return zip.generateAsync({ type:'blob', mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document', compression:'DEFLATE' });
    }

    function personelSubesiniBul(personel) {
        return subeler.find(item => String(item.sirketId || '') === String(personel.sirketId || aktifSirketId() || '') && String(item.ad || '') === String(personel.sube || ''))
            || subeler.find(item => String(item.ad || '') === String(personel.sube || ''))
            || null;
    }

    function personelSubeBelgeleriHtml(personel) {
        const sube = personelSubesiniBul(personel);
        const belgeler = sube?.personelBelgeleri || {};
        const kartlar = SUBE_PERSONEL_BELGELERI.map(tanim => {
            const belge = belgeler[tanim.key];
            return '<article class="personel-document-card"><strong>' + sirketText(tanim.baslik) + '</strong><small>' +
                (belge ? sirketText((sube?.ad || personel.sube || 'Şube') + ' için kayıtlı belge: ' + (belge.ad || 'belge şablonu')) : 'Personelin şubesinde bu belge henüz tanımlanmadı.') +
                '</small><button type="button" class="btn-modern ' + (belge ? 'btn-detail-modern' : '') + '" data-personel-belge="' + tanim.key + '"' + (belge ? '' : ' disabled') + '>' +
                (belge ? '📄 PDF Aç / Yazdır' : 'Belge Yüklü Değil') + '</button></article>';
        }).join('');
        return '<section style="margin-top:12px;border:1px solid #dce8f1;border-radius:10px;background:#fbfdff;overflow:hidden;"><h5 style="margin:0;padding:10px 12px;color:#0f4c6e;background:#f0f8fc;font-size:.8rem;">Şube Personel Evrakları</h5><div class="personel-document-grid">' + kartlar + '</div></section>';
    }

    function personelBelgeButonlariniBagla(personelId, alan) {
        alan?.querySelectorAll('[data-personel-belge]').forEach(button => {
            button.onclick = () => personelBelgeHazirla(personelId, button.dataset.personelBelge);
        });
    }

    async function personelBelgeHazirla(personelId, belgeKey) {
        const personel = personeller.find(item => String(item.id) === String(personelId));
        const tanim = SUBE_PERSONEL_BELGELERI.find(item => item.key === belgeKey);
        const sube = personel ? personelSubesiniBul(personel) : null;
        const sirket = sirketler.find(item => String(item.id) === String(personel?.sirketId || aktifSirketId() || '')) || sirketler[0];
        const belge = sube?.personelBelgeleri?.[belgeKey];
        if (!personel || !tanim || !sube || !belge?.id) return alert('Personelin şubesine ait Word belgesi bulunamadı.');
        if (!personel.girisTarihi && tanim.otomatik) return alert('Belge tarihlerini hazırlamak için personelin işe giriş tarihi kayıtlı olmalıdır.');
        if (belgeKey === 'calisanElKitabi' && typeof window.fdPersonelDriveBelgesiOnizle === 'function') {
            window.fdPersonelDriveBelgesiOnizle(belge, tanim.baslik);
            return;
        }
        showGlobalOverlay('Personel belgesi hazırlanıyor', tanim.baslik + ' · ' + personel.ad);
        try {
            const sonuc = await fdYazilimDriveDosyaIndir(belge.id);
            const kaynak = base64DizisineCevir(sonuc.base64);
            let blob = new Blob([kaynak], { type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
            if (tanim.otomatik) {
                const yil = String(personel.girisTarihi).slice(0, 4);
                const degerler = [
                    String(personel.id || ''),
                    String(sube.adres || ''),
                    String(sirket?.unvan || sirket?.kisaAd || ''),
                    tarihFormati(personel.girisTarihi) + ' - 31.12.' + yil + ' ',
                    String(personel.ad || '').toLocaleUpperCase('tr-TR')
                ];
                blob = await personelWordBelgesiniHazirla(kaynak.buffer, degerler, belgeKey);
            }
            const dosyaAdi = subeBelgeDriveDosyaAdi(personel.ad, tanim.baslik).replace(/\.docx$/i, '.pdf');
            await personelBelgePdfOnizlemeAc(blob, dosyaAdi, tanim.baslik);
        } catch (error) {
            alert('Personel belgesi hazırlanamadı: ' + (error.message || error));
        } finally {
            hideGlobalOverlay();
        }
    }

    async function personelBelgeOnizlemeAc(blob, dosyaAdi, baslik, secenek = {}) {
        personelBelgeOnizlemeBlobu = blob;
        personelBelgeOnizlemeAdi = dosyaAdi;
        personelBelgeOnizlemeBasligi = baslik || 'Personel Belgesi';
        const pdfButonu = document.getElementById('personelBelgePdfIndirBtn');
        if (pdfButonu) pdfButonu.style.display = secenek.pdfIndir ? '' : 'none';
        document.getElementById('personelBelgeBaslik').textContent = '📄 ' + baslik;
        document.getElementById('personelBelgeDosyaAdi').textContent = dosyaAdi;
        const alan = document.getElementById('personelBelgeOnizleme');
        alan.innerHTML = '<div style="margin:24px auto;width:max-content;padding:16px 20px;background:#fff;border-radius:10px;font-weight:700;">Word önizlemesi hazırlanıyor...</div>';
        document.getElementById('modalPersonelBelge').style.display = 'flex';
        if (!window.docx?.renderAsync) {
            alan.innerHTML = '<div style="margin:24px auto;max-width:560px;padding:18px;background:#fff;border-radius:10px;">Word önizleme bileşeni yüklenemedi. Belgeyi Word İndir düğmesiyle açıp yazdırabilirsiniz.</div>';
            return;
        }
        alan.innerHTML = '';
        try {
            await window.docx.renderAsync(blob, alan, alan, { inWrapper:true, breakPages:true, ignoreLastRenderedPageBreak:false, renderHeaders:true, renderFooters:true, renderFootnotes:true, ignoreWidth:false, ignoreHeight:false, ignoreFonts:false, useBase64URL:true, experimental:true });
            alan.querySelectorAll('.docx-wrapper > section.docx').forEach((sayfa, index) => {
                sayfa.dataset.sayfa = String(index + 1);
                sayfa.style.position = 'relative';
                sayfa.style.overflow = 'hidden';
                sayfa.style.flex = '0 0 auto';
            });
        } catch (error) {
            console.error('Word önizleme:', error);
            alan.innerHTML = '<div style="margin:24px auto;max-width:560px;padding:18px;background:#fff;border-radius:10px;">Belge hazırlandı ancak tarayıcı önizlemesi açılamadı. Word İndir düğmesini kullanabilirsiniz.</div>';
        }
    }

    function personelBelgeOnizlemeKapat() {
        document.body.classList.remove('personel-word-yazdiriliyor');
        document.getElementById('modalPersonelBelge').style.display = 'none';
        document.getElementById('personelBelgeOnizleme').innerHTML = '';
        const indirButonu = document.querySelector('#modalPersonelBelge .personel-word-actions button[onclick="personelBelgeWordIndir()"]');
        if (indirButonu) indirButonu.style.display = '';
        const pdfButonu = document.getElementById('personelBelgePdfIndirBtn');
        if (pdfButonu) { pdfButonu.style.display = 'none'; pdfButonu.disabled = false; pdfButonu.textContent = '⬇️ PDF İndir'; }
        personelBelgeOnizlemeBlobu = null;
        personelBelgeOnizlemeAdi = '';
        personelBelgeOnizlemeBasligi = '';
        yillikPersonelBelgeTopluModu = false;
        yillikPersonelBelgeHazirlananCiftler = [];
    }

    function personelBelgeWordIndir() {
        if (!personelBelgeOnizlemeBlobu) return;
        fdCiktiDogrudanKaydet(personelBelgeOnizlemeBlobu, personelBelgeOnizlemeAdi || 'personel_belgesi.docx');
    }

    async function personelBelgeAktifPdfIndir() {
        if (!personelBelgeOnizlemeBlobu) return;
        const buton = document.getElementById('personelBelgePdfIndirBtn');
        const pdfAdi = String(personelBelgeOnizlemeAdi || 'personel_belgesi.docx').replace(/\.docx$/i, '.pdf');
        if (buton) { buton.disabled = true; buton.textContent = 'PDF hazırlanıyor...'; }
        try {
            const pdfBlob = await personelBelgePdfOnizlemeAc(personelBelgeOnizlemeBlobu, pdfAdi, personelBelgeOnizlemeBasligi, { onizle:false });
            if (!pdfBlob) throw new Error('PDF dosyası oluşturulamadı.');
            fdCiktiDogrudanKaydet(pdfBlob, pdfAdi);
        } catch (error) {
            console.error('Belge PDF indirme:', error);
            alert('PDF indirilemedi: ' + (error.message || error));
        } finally {
            if (buton) { buton.disabled = false; buton.textContent = '⬇️ PDF İndir'; }
        }
    }

    function personelBelgeYazdir() {
        if (yillikPersonelBelgeTopluModu) return yillikPersonelBelgeleriniTopluYazdir();
        if (!personelBelgeOnizlemeBlobu) return;
        document.body.classList.add('personel-word-yazdiriliyor');
        const temizle = () => document.body.classList.remove('personel-word-yazdiriliyor');
        window.addEventListener('afterprint', temizle, { once:true });
        window.print();
        setTimeout(temizle, 3000);
    }

    function yillikPersonelBelgeAktifPersonelleri() {
        return personeller.filter(personel => {
            const cikis = String(personel?.cikisTarihi ?? '').trim().toLocaleLowerCase('tr-TR');
            return aktifSirketeAit(personel) && (!cikis || ['null','undefined','-','0000-00-00'].includes(cikis));
        }).sort((a,b) => String(a.sube || '').localeCompare(String(b.sube || ''), 'tr') || String(a.ad || '').localeCompare(String(b.ad || ''), 'tr'));
    }

    function yillikPersonelBelgeDurumunuAl(yil, olustur = false) {
        const anahtar = String(yil);
        const harita = { ...(uygulamaAyarlari.yillikPersonelBelgeleri || {}) };
        let durum = harita[anahtar];
        let yeni = false;
        if (!durum && olustur) {
            durum = {
                yil:Number(yil),
                baslangic:`01.01.${yil}`,
                bitis:`01.01.${Number(yil) + 1}`,
                hedefPersonelIds:yillikPersonelBelgeAktifPersonelleri().map(personel => String(personel.id)),
                tamamlananlar:{},
                olusturmaZamani:new Date().toISOString(),
                sonGuncelleme:new Date().toISOString()
            };
            harita[anahtar] = durum;
            uygulamaAyarlari = { ...uygulamaAyarlari, yillikPersonelBelgeleri:harita };
            yeni = true;
        }
        return { durum, yeni };
    }

    async function yillikPersonelBelgeDurumunuKaydet() {
        const yerelHarita = { ...(uygulamaAyarlari.yillikPersonelBelgeleri || {}) };
        if (SUPABASE_MODE) {
            const { data:sirket, error:okumaHatasi } = await supabaseClient.from('companies').select('data').eq('id', aktifSirketId()).maybeSingle();
            if (okumaHatasi) throw okumaHatasi;
            const sunucuAyarlar = sirket?.data?.uygulamaAyarlari || {};
            const yeniAyarlar = {
                ...sunucuAyarlar,
                ...uygulamaAyarlari,
                yillikPersonelBelgeleri:{ ...(sunucuAyarlar.yillikPersonelBelgeleri || {}), ...yerelHarita }
            };
            const { error } = await supabaseClient.from('companies').update({ data:{ ...(sirket?.data || {}), uygulamaAyarlari:yeniAyarlar } }).eq('id', aktifSirketId());
            if (error) throw error;
            uygulamaAyarlari = { ...VARSAYILAN_UYGULAMA_AYARLARI, ...yeniAyarlar };
        } else {
            localStorage.setItem(`fdYazilimYillikPersonelBelgeleri:${aktifSirketId()}`, JSON.stringify(yerelHarita));
        }
    }

    function yillikPersonelBelgeHedefleri(durum) {
        const aktifHarita = new Map(yillikPersonelBelgeAktifPersonelleri().map(personel => [String(personel.id), personel]));
        return (durum?.hedefPersonelIds || []).map(id => aktifHarita.get(String(id))).filter(Boolean);
    }

    function yillikPersonelBelgeBekleyenSayisi(durum) {
        const belgeTurleri = ['fazlaMesaiOnayi','vardiyaliCalismaOnayi'];
        return yillikPersonelBelgeHedefleri(durum).reduce((toplam, personel) => {
            const tamamlanan = Array.isArray(durum?.tamamlananlar?.[String(personel.id)]) ? durum.tamamlananlar[String(personel.id)] : [];
            return toplam + belgeTurleri.filter(tur => !tamamlanan.includes(tur)).length;
        }, 0);
    }

    function yillikPersonelBelgeButonunuGuncelle() {
        const buton=document.getElementById('btnYillikPersonelBelgeleri');if(!buton)return;
        buton.style.display=isManagerUser()?'inline-flex':'none';
    }

    async function yillikPersonelBelgeHatirlatmaHtml(bugun) {
        const yil = Number(String(bugun || '').slice(0,4));
        if (!isManagerUser() || yil < YILLIK_PERSONEL_BELGE_ILK_YILI) return '';
        const sonuc = yillikPersonelBelgeDurumunuAl(yil, true);
        if (sonuc.yeni) await yillikPersonelBelgeDurumunuKaydet();
        const hedefSayisi = yillikPersonelBelgeHedefleri(sonuc.durum).length;
        const bekleyen = yillikPersonelBelgeBekleyenSayisi(sonuc.durum);
        if (!hedefSayisi || !bekleyen) return '';
        return `<section style="border:1px solid #d8b4fe;border-radius:12px;overflow:hidden;margin-bottom:12px;background:#faf5ff;">
            <div style="padding:11px 13px;font-weight:850;color:#7e22ce;">📄 ${yil} Yılı Personel Onay Belgeleri</div>
            <div style="padding:0 13px 12px;color:#581c87;line-height:1.5;">${hedefSayisi} aktif çalışan için ${bekleyen} belge henüz toplu yazdırılmadı. Tarih aralığı: <strong>01.01.${yil} - 01.01.${yil + 1}</strong>.</div>
            <div style="padding:0 13px 13px;"><button type="button" class="btn-modern" style="background:#7e22ce;color:#fff;border-color:#7e22ce;" onclick="gunlukHatirlatmalariKapat();yillikPersonelBelgePaneliniAc(${yil})">Şube ve Belge Seç →</button></div>
        </section>`;
    }

    async function yillikPersonelBelgePaneliniAc(yil = new Date().getFullYear()) {
        if (!isManagerUser()) return showToast('Bu belgeler için admin veya kullanıcı yetkisi gerekir.','error');
        yillikPersonelBelgeAktifYili = Number(yil) || new Date().getFullYear();
        const sonuc = yillikPersonelBelgeDurumunuAl(yillikPersonelBelgeAktifYili, true);
        if (sonuc.yeni) {
            try { await yillikPersonelBelgeDurumunuKaydet(); }
            catch (error) { return showToast('Yıllık belge listesi kaydedilemedi: ' + (error.message || error), 'error'); }
        }
        const durum = sonuc.durum;
        const hedefler = yillikPersonelBelgeHedefleri(durum);
        const gruplar = new Map();
        hedefler.forEach(personel => {
            const subeAdi = String(personel.sube || 'Şube belirtilmemiş');
            if (!gruplar.has(subeAdi)) gruplar.set(subeAdi, []);
            gruplar.get(subeAdi).push(personel);
        });
        const toplamBelge = hedefler.length * 2;
        const bekleyen = yillikPersonelBelgeBekleyenSayisi(durum);
        document.getElementById('yillikBelgeTarihAraligi').textContent = `${durum.baslangic} - ${durum.bitis} · Her çalışan için iki belge`;
        document.getElementById('yillikBelgeDurumOzeti').innerHTML = bekleyen
            ? `<strong>${hedefler.length} aktif çalışan</strong> için toplam ${toplamBelge} belge kapsamda. <strong>${bekleyen} belge bekliyor.</strong> Yazdırılan şube ve belge türleri kaydedilir; kalanlar için hatırlatma devam eder.`
            : `<strong>${yillikPersonelBelgeAktifYili} yılı tamamlandı.</strong> Kapsamdaki ${hedefler.length} aktif çalışanın iki onay belgesi de yazdırıldı. İsterseniz aşağıdan yeniden hazırlayabilirsiniz.`;
        document.getElementById('yillikBelgeSubeSecimleri').innerHTML = [...gruplar.entries()].map(([subeAdi,liste]) => `<label><input type="checkbox" name="yillikBelgeSube" value="${escapeDashboardText(subeAdi)}" checked onchange="yillikBelgeSubeSeciminiGuncelle()"> <span><strong>${escapeDashboardText(subeAdi)}</strong><small>${liste.length} aktif çalışan</small></span></label>`).join('') || '<div style="padding:8px;color:#64748b;">Aktif çalışan bulunmuyor.</div>';
        document.getElementById('yillikBelgeTumSubeler').checked = true;
        document.querySelectorAll('input[name="yillikBelgeTuru"]').forEach(input => input.checked = true);
        document.getElementById('yillikBelgeHataOzeti').style.display = 'none';
        document.getElementById('modalYillikPersonelBelge').style.display = 'flex';
    }

    function yillikPersonelBelgePaneliniKapat() {
        document.getElementById('modalYillikPersonelBelge').style.display = 'none';
    }

    function yillikBelgeTumSubeleriSec(secili) {
        document.querySelectorAll('input[name="yillikBelgeSube"]').forEach(input => input.checked = Boolean(secili));
    }

    function yillikBelgeSubeSeciminiGuncelle() {
        const liste = [...document.querySelectorAll('input[name="yillikBelgeSube"]')];
        document.getElementById('yillikBelgeTumSubeler').checked = Boolean(liste.length && liste.every(input => input.checked));
    }

    async function yillikPersonelBelgeleriniTopluHazirla() {
        const yil = yillikPersonelBelgeAktifYili || new Date().getFullYear();
        const durum = yillikPersonelBelgeDurumunuAl(yil, true).durum;
        const seciliSubeler = new Set([...document.querySelectorAll('input[name="yillikBelgeSube"]:checked')].map(input => input.value));
        const seciliBelgeler = [...document.querySelectorAll('input[name="yillikBelgeTuru"]:checked')].map(input => input.value);
        if (!seciliSubeler.size) return showToast('En az bir şube seçin.', 'error');
        if (!seciliBelgeler.length) return showToast('En az bir belge seçin.', 'error');
        const hedefler = yillikPersonelBelgeHedefleri(durum).filter(personel => seciliSubeler.has(String(personel.sube || 'Şube belirtilmemiş')));
        if (!hedefler.length) return showToast('Seçilen şubelerde hazırlanacak aktif çalışan bulunmuyor.', 'error');
        if (!window.docx?.renderAsync) return showToast('Toplu Word önizleme bileşeni yüklenemedi.', 'error');

        const alan = document.getElementById('personelBelgeOnizleme');
        const hatalar = [];
        const sablonOnbellegi = new Map();
        const hazirlananlar = [];
        yillikPersonelBelgePaneliniKapat();
        document.getElementById('personelBelgeBaslik').textContent = `📄 ${yil} Yıllık Personel Belgeleri`;
        document.getElementById('personelBelgeDosyaAdi').textContent = `${hedefler.length} çalışan · ${seciliBelgeler.length} belge türü · ${durum.baslangic} - ${durum.bitis}`;
        const indirButonu = document.querySelector('#modalPersonelBelge .personel-word-actions button[onclick="personelBelgeWordIndir()"]');
        if (indirButonu) indirButonu.style.display = 'none';
        alan.innerHTML = '<div style="margin:24px auto;width:max-content;padding:16px 20px;background:#fff;border-radius:10px;font-weight:700;">Toplu belgeler hazırlanıyor...</div>';
        document.getElementById('modalPersonelBelge').style.display = 'flex';
        showGlobalOverlay('Yıllık belgeler hazırlanıyor', `${hedefler.length} aktif çalışan için Word belgeleri düzenleniyor...`);
        try {
            alan.innerHTML = '';
            let sira = 0;
            for (const personel of hedefler) {
                const sube = personelSubesiniBul(personel);
                const sirket = sirketler.find(item => String(item.id) === String(personel.sirketId || aktifSirketId() || '')) || sirketler[0];
                for (const belgeKey of seciliBelgeler) {
                    sira++;
                    const tanim = SUBE_PERSONEL_BELGELERI.find(item => item.key === belgeKey);
                    const belge = sube?.personelBelgeleri?.[belgeKey];
                    showGlobalOverlay('Yıllık belgeler hazırlanıyor', `${sira}/${hedefler.length * seciliBelgeler.length} · ${personel.ad} · ${tanim?.baslik || belgeKey}`);
                    if (!sube || !belge?.id || !tanim) {
                        hatalar.push(`${personel.ad} · ${personel.sube || 'Şube yok'} · ${tanim?.baslik || belgeKey}: Şablon yüklü değil.`);
                        continue;
                    }
                    try {
                        let kaynak = sablonOnbellegi.get(String(belge.id));
                        if (!kaynak) {
                            const sonuc = await fdYazilimDriveDosyaIndir(belge.id);
                            kaynak = base64DizisineCevir(sonuc.base64);
                            sablonOnbellegi.set(String(belge.id), kaynak);
                        }
                        const degerler = [
                            String(personel.id || ''),
                            String(sube.adres || ''),
                            String(sirket?.unvan || sirket?.kisaAd || ''),
                            `${durum.baslangic} - ${durum.bitis} `,
                            String(personel.ad || '').toLocaleUpperCase('tr-TR')
                        ];
                        const blob = await personelWordBelgesiniHazirla(kaynak.buffer, degerler, belgeKey);
                        const kabuk = document.createElement('section');
                        kabuk.className = 'yillik-belge-render';
                        const ekranBasligi = document.createElement('div');
                        ekranBasligi.className = 'yillik-belge-ekran-basligi';
                        ekranBasligi.style.cssText = 'max-width:900px;margin:0 auto 7px;padding:8px 12px;border-radius:8px;background:#334155;color:#fff;font-weight:800;font-size:.76rem;';
                        ekranBasligi.textContent = `${personel.ad} · ${sube.ad} · ${tanim.baslik}`;
                        const renderAlani = document.createElement('div');
                        kabuk.append(ekranBasligi, renderAlani);
                        alan.appendChild(kabuk);
                        await window.docx.renderAsync(blob, renderAlani, renderAlani, { inWrapper:true, breakPages:true, ignoreLastRenderedPageBreak:false, renderHeaders:true, renderFooters:true, renderFootnotes:true, ignoreWidth:false, ignoreHeight:false, ignoreFonts:false, useBase64URL:true, experimental:true });
                        hazirlananlar.push({ personelId:String(personel.id), belgeKey });
                    } catch (error) {
                        hatalar.push(`${personel.ad} · ${tanim.baslik}: ${error.message || error}`);
                    }
                }
            }
            if (!hazirlananlar.length) throw new Error('Hiçbir belge hazırlanamadı. Şubelerdeki Word şablonlarını kontrol edin.');
            yillikPersonelBelgeTopluModu = true;
            yillikPersonelBelgeHazirlananCiftler = hazirlananlar;
            personelBelgeOnizlemeBlobu = null;
            personelBelgeOnizlemeAdi = '';
            if (hatalar.length) {
                const hataOzeti = document.createElement('div');
                hataOzeti.className = 'yillik-belge-ekran-basligi';
                hataOzeti.style.cssText = 'max-width:900px;margin:0 auto 12px;padding:12px;border-radius:9px;background:#fff7ed;color:#9a3412;border:1px solid #fed7aa;';
                hataOzeti.innerHTML = `<strong>${hatalar.length} belge hazırlanamadı:</strong><br>${hatalar.map(escapeDashboardText).join('<br>')}`;
                alan.prepend(hataOzeti);
            }
            showToast(`${hazirlananlar.length} belge hazırlandı. Önizlemeyi kontrol edip Toplu Yazdır düğmesine basın.`);
        } catch (error) {
            personelBelgeOnizlemeKapat();
            showToast('Toplu belgeler hazırlanamadı: ' + (error.message || error), 'error');
        } finally {
            hideGlobalOverlay();
        }
    }

    async function yillikPersonelBelgeleriniTopluYazdir() {
        if (!yillikPersonelBelgeHazirlananCiftler.length) return;
        document.body.classList.add('personel-word-yazdiriliyor');
        try {
            window.print();
            const yazdirildi = await fdYuzerOnaySor('Yazdırma işlemi tamamlandı mı? Onaylarsanız hazırlanan belgeler tamamlandı olarak kaydedilecek.');
            if (!yazdirildi) {
                showToast('Belgeler tamamlandı olarak işaretlenmedi; günlük hatırlatma devam edecek.');
                return;
            }
            const yil = yillikPersonelBelgeAktifYili;
            const sonuc = yillikPersonelBelgeDurumunuAl(yil, true);
            const durum = sonuc.durum;
            const tamamlananlar = { ...(durum.tamamlananlar || {}) };
            yillikPersonelBelgeHazirlananCiftler.forEach(kayit => {
                const mevcut = Array.isArray(tamamlananlar[kayit.personelId]) ? tamamlananlar[kayit.personelId] : [];
                tamamlananlar[kayit.personelId] = [...new Set([...mevcut, kayit.belgeKey])];
            });
            const harita = { ...(uygulamaAyarlari.yillikPersonelBelgeleri || {}) };
            harita[String(yil)] = { ...durum, tamamlananlar, sonGuncelleme:new Date().toISOString(), sonYazdiran:String(activeUser?.username || ''), sonYazdirmaZamani:new Date().toISOString() };
            uygulamaAyarlari = { ...uygulamaAyarlari, yillikPersonelBelgeleri:harita };
            await yillikPersonelBelgeDurumunuKaydet();
            const kalan = yillikPersonelBelgeBekleyenSayisi(harita[String(yil)]);
            showToast(kalan ? `Yazdırılan belgeler kaydedildi. ${kalan} belge için günlük hatırlatma devam edecek.` : `${yil} yılı için tüm onay belgeleri tamamlandı; hatırlatma kapatıldı.`);
        } catch (error) {
            showToast('Yazdırma durumu kaydedilemedi: ' + (error.message || error), 'error');
        } finally {
            document.body.classList.remove('personel-word-yazdiriliyor');
        }
    }
