    function getPuantajCellClass(val) {
        if (val === '-') return 'p-cell p-eksi';
        if (val === 'Y') return 'p-cell p-y';
        if (val === 'Z') return 'p-cell p-z';
        if (val === 'M') return 'p-cell p-m';
        if (val === 'R') return 'p-cell p-r';
        if (val === 'Ü') return 'p-cell p-u';
        if (val === 'HS') return 'p-cell p-hs';
        if (val === 'RT') return 'p-cell p-rt';
        if (val === 'YT') return 'p-cell p-yt';
        if (val === 'RC') return 'p-cell p-rc';
        if (val === 'PZ') return 'p-cell p-pz';
        return 'p-cell p-x';
    }

    function primGunTatilGosterimi(personel, tarihKey, hesapKodu) {
        if (!['X', ''].includes(hesapKodu) || typeof magicpassYarimGunResmiTatilMi !== 'function' || !magicpassYarimGunResmiTatilMi(tarihKey)) return { kod:hesapKodu, aciklama:'' };
        const gecmisVeyaBugun = String(tarihKey) <= magicpassTarihAnahtari(new Date());
        const gun = gecmisVeyaBugun ? magicpassGunHesapla(personel, tarihKey) : null;
        const tatildeCalisti = !gun?.izin && Number(gun?.resmiTatilMesaiDakika || 0) > 0;
        return tatildeCalisti
            ? { kod:'RC', aciklama:'Resmî Tatilde Çalışma — Öğleden sonraki çalışma süresi giriş–çıkış saatlerinden hesaplanır.' }
            : { kod:'YT', aciklama:'Yarım Gün Resmî Tatil — Öğleden Sonra Resmî Tatil. Ücret ve prim hakkı korunur.' };
    }

    function primGunuTamamlandiMi(personel, tarihKey, simdi = new Date()) {
        const bugunKey = magicpassTarihAnahtari(simdi);
        if (String(tarihKey) < bugunKey) return true;
        if (String(tarihKey) > bugunKey) return false;

        const vardiya = magicpassGunVardiyasi(personel, tarihKey);
        if (vardiya === 'izin') return true;
        const saatler = magicpassVardiyaSaatleri(vardiya, tarihKey);
        return saatler?.bit instanceof Date && !Number.isNaN(saatler.bit.getTime()) && simdi >= saatler.bit;
    }

    function personelPrimCalisilmayanGunSayisi(personel, ay, yil) {
        const onbellekAnahtari = `${String(personel?.id || '')}|${Number(yil)}-${String(Number(ay) + 1).padStart(2, '0')}`;
        if (fdPuantajPrimCalisilmayanCache?.has(onbellekAnahtari)) return fdPuantajPrimCalisilmayanCache.get(onbellekAnahtari);
        const daysInMonth = new Date(yil, ay + 1, 0).getDate();
        const ayBaslangic = `${yil}-${String(ay + 1).padStart(2, '0')}-01`;
        const ayBitis = `${yil}-${String(ay + 1).padStart(2, '0')}-${String(daysInMonth).padStart(2, '0')}`;
        const girisTarihi = tarihInputDegeri(personel?.girisTarihi);
        const cikisTarihi = tarihInputDegeri(personel?.cikisTarihi);
        if (girisTarihi && girisTarihi > ayBaslangic) {
            fdPuantajPrimCalisilmayanCache?.set(onbellekAnahtari, 0);
            return 0;
        }
        if (cikisTarihi && cikisTarihi < ayBitis) {
            fdPuantajPrimCalisilmayanCache?.set(onbellekAnahtari, 0);
            return 0;
        }
        let calisilmayanGun = 0;
        const bugunKey = magicpassTarihAnahtari(new Date());
        const personelId = String(personel?.id || '');
        const personelIzinleri = fdPuantajIzinlerByPersonelCache?.get(personelId) || null;

        for (let d = 1; d <= daysInMonth; d++) {
            const dateKey = `${yil}-${String(ay + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
            const gunTamamlandi = primGunuTamamlandiMi(personel, dateKey);
            let durum = '';
            let cihazGunu = null;
            const izin = personelIzinleri
                ? personelIzinleri.find(item => dateKey >= item.baslangic && dateKey <= item.bitis)
                : izinler.find(item => aktifSirketeAit(item) && String(item.pId) === personelId && dateKey >= item.baslangic && dateKey <= item.bitis);
            if (izin) {
                if (izin.tur === 'Sağlık / Rapor') durum = 'R';
                if (izin.tur === 'Ücretsiz İzin') durum = 'Z';
            }
            if (!izin && gunTamamlandi) {
                cihazGunu = magicpassGunHesapla(personel, dateKey);
                if (!durum && cihazGunu.durum === 'Gelmedi') durum = 'M';
            }
            const puantaj = fdPuantajManuelByGunCache?.get(`${personelId}|${dateKey}`)
                || puantajVerileri.find(item => aktifSirketeAit(item) && !item.kayitTipi && String(item.pId) === personelId && String(item.tarih) === dateKey);
            if (!izin && puantaj?.durum) durum = puantaj.durum;
            if (!izin && dateKey === bugunKey && !gunTamamlandi) durum = '';
            if (durum === 'R' || durum === 'Z' || durum === 'M') {
                calisilmayanGun += 1;
            } else if (gunTamamlandi && !izin) {
                const eksikCalismaDakikasi = Math.max(0, Number(cihazGunu?.gec ?? puantaj?.gec ?? 0)) + Math.max(0, Number(cihazGunu?.erken ?? puantaj?.erken ?? 0));
                if (eksikCalismaDakikasi >= ayarSayisi('primYarimGunEksikMesaiDakika', 210)) calisilmayanGun += 0.5;
            }
        }
        const sonuc = Math.round(calisilmayanGun * 2) / 2;
        fdPuantajPrimCalisilmayanCache?.set(onbellekAnahtari, sonuc);
        return sonuc;
    }

    function personelPrimHakkiVarMi(personel, ay, yil) {
        const gunSayisi = new Date(yil, ay + 1, 0).getDate();
        const ayBaslangic = `${yil}-${String(ay + 1).padStart(2, '0')}-01`;
        const ayBitis = `${yil}-${String(ay + 1).padStart(2, '0')}-${String(gunSayisi).padStart(2, '0')}`;
        const girisTarihi = tarihInputDegeri(personel?.girisTarihi);
        const cikisTarihi = tarihInputDegeri(personel?.cikisTarihi);
        if (girisTarihi && girisTarihi > ayBaslangic) return false;
        if (cikisTarihi && cikisTarihi < ayBitis) return false;
        return personelPrimCalisilmayanGunSayisi(personel, ay, yil) <= ayarSayisi('primDevamsizlikSiniri', 1.5);
    }

    function puantajAyAnahtari(ay, yil) {
        return `${yil}-${String(Number(ay) + 1).padStart(2, '0')}`;
    }

    function maasOzetKaydiBul(pId, ay, yil) {
        const tarih = `${puantajAyAnahtari(ay, yil)}-00`;
        return puantajVerileri.find(item => item.kayitTipi === 'maasOzet' && String(item.pId) === String(pId) && String(item.tarih) === tarih && String(item.sirketId || '') === aktifSirketId());
    }

    function personelGunlukUcretiniGetir(personel) {
        const alanlar = ['ucret', 'gunlukUcret', 'gunlukYevmiye', 'ucretTutari', 'maas', 'maasTutari'];
        for (const alan of alanlar) {
            const ham = personel?.[alan];
            if (ham === undefined || ham === null || String(ham).trim() === '') continue;
            const tutar = paraMetniniSayiyaCevir(ham);
            if (Number.isFinite(tutar)) return tutar;
        }
        const uygunAlan = Object.entries(personel || {}).find(([anahtar, deger]) => {
            const temiz = String(anahtar).toLocaleLowerCase('tr-TR').replace(/ı/g, 'i').replace(/ş/g, 's').replace(/ğ/g, 'g').replace(/ü/g, 'u').replace(/ö/g, 'o').replace(/ç/g, 'c').replace(/[^a-z0-9]/g, '');
            return ['ucret', 'ucrettutari', 'gunlukucret', 'gunlukyevmiye', 'maas', 'maastutari'].includes(temiz) && String(deger ?? '').trim() !== '';
        });
        if (uygunAlan) return paraMetniniSayiyaCevir(uygunAlan[1]);
        return 0;
    }

    function primAyarKaydiBul() {
        return puantajVerileri.find(item => item.kayitTipi === 'primAyar' && String(item.sirketId || '') === aktifSirketId());
    }

    function primSabitTutariniGetir() {
        return ayarSayisi('primTutari', 2000);
    }

    async function primSabitTutariniKaydet(input) {
        const tutar = Math.max(0, paraMetniniSayiyaCevir(input.value));
        input.value = tutar.toLocaleString('tr-TR', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
        const mevcut = primAyarKaydiBul();
        const yeni = { pId: '__AYAR__', tarih: '0000-00-00', durum: 'PRIM_AYAR', kayitTipi: 'primAyar', tutar, sirketId: aktifSirketId() };
        if (mevcut) puantajVerileri[puantajVerileri.indexOf(mevcut)] = { ...mevcut, ...yeni };
        else puantajVerileri.push(yeni);
        await verileriKaydet();
        renderPuantajMatrisi();
    }

    function personelAylikAvansKesintisi(pId, ay, yil) {
        const hedefAy = puantajAyAnahtari(ay, yil);
        return avanslar.filter(a => String(a.pId) === String(pId) && avansAktifSirketinMi(a) && String(a.durum || '') !== 'Tamamlandı')
            .reduce((toplam, avans) => toplam + Number(avansAylikKesinti(avans, hedefAy)?.kesinti || 0), 0);
    }

    function aktifIcraBul(pId) {
        return icralar.find(i => aktifSirketeAit(i) && String(i.pId) === String(pId) && String(i.durum) === 'Aktif' && icraKalanBorc(i) > 0);
    }

    function personelIcraKayitlari(pId) {
        return icralar.filter(i => aktifSirketeAit(i) && String(i.pId) === String(pId));
    }

    function personelAylikIcraKesintisi(pId, ay, yil) {
        const hedefAy = puantajAyAnahtari(ay, yil);
        return personelIcraKayitlari(pId).reduce((toplam, icra) => {
            const aylikToplam = (Array.isArray(icra.kesintiler) ? icra.kesintiler : [])
                .filter(kesinti => String(kesinti.ay || '').slice(0, 7) === hedefAy)
                .reduce((araToplam, kesinti) => araToplam + Number(kesinti.tutar || 0), 0);
            return toplam + aylikToplam;
        }, 0);
    }

    async function maasOzetAlaniniKaydet(pId, alan, input) {
        if (isPersonelUser()) return;
        const ay = Number(document.getElementById('puanAySec').value);
        const yil = Number(document.getElementById('puanYilSec').value);
        const mevcut = maasOzetKaydiBul(pId, ay, yil);
        const sayi = Math.max(0, paraMetniniSayiyaCevir(input.value));
        const yeni = {
            ...(mevcut || {}), pId: String(pId), tarih: `${puantajAyAnahtari(ay, yil)}-00`, durum: 'MAAS_OZET', kayitTipi: 'maasOzet', sirketId: aktifSirketId(),
            [alan]: sayi, [`${alan}Manuel`]: 'true'
        };
        if (mevcut) puantajVerileri[puantajVerileri.indexOf(mevcut)] = yeni;
        else puantajVerileri.push(yeni);
        if (alan === 'icraKesintisi') await puantajIcraKesintisiniGuncelle(pId, ay, yil, sayi);
        await verileriKaydet();
        renderPuantajMatrisi();
    }

    async function puantajIcraKesintisiniGuncelle(pId, ay, yil, tutar, kaynakTuru = 'puantaj') {
        const ayAnahtari = puantajAyAnahtari(ay, yil);
        const kaynak = `puantaj_${pId}_${ayAnahtari}`;
        const personelIcralari=icralar.filter(i => String(i.pId) === String(pId) && aktifSirketeAit(i));let kaynakVardi=false;
        personelIcralari.forEach(icra => {
            const oncekiKesintiler = Array.isArray(icra.kesintiler) ? icra.kesintiler : [];
            if(oncekiKesintiler.some(k => String(k.id) === kaynak))kaynakVardi=true;
            icra.kesintiler = oncekiKesintiler.filter(k => String(k.id) !== kaynak);
        });
        if(kaynakVardi){
            const aciklar=personelIcralari.filter(icra=>icraKalanBorc(icra)>0).sort((a,b)=>Number(a.siraTarihi||0)-Number(b.siraTarihi||0));
            personelIcralari.filter(icra=>icraKalanBorc(icra)<=0).forEach(icra=>icra.durum='Kapandı');
            aciklar.forEach((icra,index)=>icra.durum=index===0?'Aktif':'Bekleyen Sıra');
        }
        let kalanTutar=Math.max(0,Number(tutar)||0),islenenTutar=0,guvenlik=0;
        if (tutar > 0) {
            icraSiradakiniAktifEt(pId);
            while(kalanTutar>0.009&&guvenlik++<100){
                const icra = aktifIcraBul(pId);if(!icra)break;
                if(!Array.isArray(icra.kesintiler))icra.kesintiler=[];
                const pay=Math.min(kalanTutar,icraKalanBorc(icra));if(pay<=0)break;
                icra.kesintiler.push({ id: kaynak, ay: ayAnahtari, tutar: Number(pay.toFixed(2)), kaynak: kaynakTuru });
                islenenTutar+=pay;kalanTutar-=pay;
                if (icraKalanBorc(icra) <= 0) {
                    icra.durum = 'Kapandı';
                    icraSiradakiniAktifEt(pId);
                }
            }
        }
        yuklenenVeriler.add('icralar');
        return{islenenTutar:Number(islenenTutar.toFixed(2)),artanTutar:Number(Math.max(0,kalanTutar).toFixed(2))};
    }

    function maasSatiriniOnizle(input) {
        const satir = input.closest('tr');
        if (!satir) return;
        const gunluk = Number(satir.dataset.gunluk || 0);
        const ucretGunu = Number(satir.dataset.ucretGunu || 0);
        const avans = Number(satir.dataset.avans || 0);
        const deger = alan => paraMetniniSayiyaCevir(satir.querySelector(`[data-maas-alan="${alan}"]`)?.value || 0);
        const fazla = deger('fazlaMesaiSaati'), pazar = deger('pazarMesaiSaati'), resmi = deger('resmiTatilMesaiSaati');
        const prim = deger('primTutari'), icra = deger('icraKesintisi'), bes = deger('besKesintisi');
        const temel = ucretGunu * gunluk;
        const saatlikMesai = gunluk / ayarSayisi('gunlukCalismaSaati', 7.5) * ayarSayisi('mesaiKatsayisi', 1.5);
        const yaz = (alan, tutar) => { const hedef = satir.querySelector(`[data-maas-sonuc="${alan}"]`); if (hedef) hedef.textContent = paraFormatla(tutar); };
        yaz('toplamUcret', temel); yaz('fazlaMesaiUcreti', saatlikMesai * fazla); yaz('pazarMesaiUcreti', saatlikMesai * pazar); yaz('resmiTatilMesaiUcreti', saatlikMesai * resmi);
        yaz('toplamMaas', temel + saatlikMesai * (fazla + pazar + resmi) + prim - avans - icra - bes);
    }

    function primOzetKaydiBul(pId, ay, yil) {
        const ozetTarihi = `${yil}-${String(ay + 1).padStart(2, '0')}-00`;
        return puantajVerileri.find(item =>
            item.kayitTipi === 'primOzet' &&
            String(item.pId) === String(pId) &&
            String(item.tarih) === ozetTarihi &&
            String(item.sirketId || '') === aktifSirketId()
        );
    }

    function personelPrimDurumu(personel, ay, yil) {
        const otomatikVar = personelPrimHakkiVarMi(personel, ay, yil);
        const ozet = primOzetKaydiBul(personel.id, ay, yil);
        const manuel = ozet && String(ozet.primHakkiManuel) === 'true';
        return {
            hakkiVar: manuel ? ozet.primHakki === 'Var' : otomatikVar,
            manuel: manuel
        };
    }

    function fdFabrikaSubeDegeri(select){
        if(!select)return '';
        const secenek=[...select.options].find(option=>String((option.value||'')+' '+(option.textContent||'')).toLocaleLowerCase('tr-TR').replace(/ı/g,'i').includes('fabrika'));
        return secenek?.value||'';
    }
    function puantajSubeFiltresiniDoldur() {
        const select = document.getElementById('puanSubeFiltre');
        if (!select) return;
        const selected = select.value;
        const subeAdlari = [...new Set(personeller.filter(aktifSirketeAit).map(item => item.sube).filter(Boolean))]
            .sort((a, b) => String(a).localeCompare(String(b), 'tr'));
        select.innerHTML = '<option value="">Tüm Şubeler</option>' + subeAdlari.map(sube => `<option value="${sirketText(sube)}">${sirketText(sube)}</option>`).join('');
        if (subeAdlari.includes(selected)) select.value = selected;
        if(select.dataset.fabrikaVarsayilan==='1'||!select.dataset.varsayilanSubeHazirlandi){const fabrika=fdFabrikaSubeDegeri(select);if(fabrika)select.value=fabrika;select.dataset.varsayilanSubeHazirlandi='1';delete select.dataset.fabrikaVarsayilan;}
    }

    function puantajGunleriniGosterGizle() {
        puantajGunlerGizli = !puantajGunlerGizli;
        renderPuantajMatrisi();
    }

    function puantajMobilEtiketleriniUygula() {
        const tablo = document.getElementById('puantajTablosu');
        if (!tablo) return;
        if (!window.matchMedia('(max-width:760px)').matches) return;
        const ay = Number(document.getElementById('puanAySec')?.value || 0);
        const yil = Number(document.getElementById('puanYilSec')?.value || new Date().getFullYear());
        const etiketler = [...tablo.querySelectorAll('thead th')].map((baslik, index) => {
            let metin = String(baslik.innerText || baslik.textContent || '').replace(/\s+/g, ' ').trim();
            if (baslik.classList.contains('p-gun-baslik')) {
                const gun = Number(metin || String(index - 1));
                const tarih = new Date(yil, ay, gun, 12, 0, 0);
                const gunAdiHam = tarih.toLocaleDateString('tr-TR', { weekday:'long' });
                const gunAdi = gunAdiHam.charAt(0).toLocaleUpperCase('tr-TR') + gunAdiHam.slice(1);
                metin = `${String(gun).padStart(2, '0')}.${String(ay + 1).padStart(2, '0')}.${yil} · ${gunAdi}`;
            }
            return metin || (index === 0 ? 'Sıra' : 'Bilgi');
        });
        tablo.querySelectorAll('tbody tr').forEach(satir => [...satir.cells].forEach((hucre, index) => {
            hucre.dataset.label = etiketler[index] || 'Bilgi';
        }));
    }

    let fdPuantajHizliHesapCache = null;
    let fdPuantajHizliGunTuruCache = null;
    let fdPuantajPrimCalisilmayanCache = null;
    let fdPuantajIzinlerByPersonelCache = null;
    let fdPuantajManuelByGunCache = null;
    let fdMagicpassKayitTurCache = null;
    let fdMagicpassPersonelIdCache = null;
    let fdMagicpassPersonelCihazCache = null;
    let fdMagicpassHareketlerByPersonelCache = null;
    let fdMagicpassHaftalikVardiyaCache = null;

    function fdPuantajHesapOnbelleginiBaslat() {
        const onceki = {
            hesap:fdPuantajHizliHesapCache, gunTuru:fdPuantajHizliGunTuruCache, prim:fdPuantajPrimCalisilmayanCache,
            izin:fdPuantajIzinlerByPersonelCache, manuel:fdPuantajManuelByGunCache, tur:fdMagicpassKayitTurCache,
            personelId:fdMagicpassPersonelIdCache, cihaz:fdMagicpassPersonelCihazCache,
            hareket:fdMagicpassHareketlerByPersonelCache, haftalik:fdMagicpassHaftalikVardiyaCache
        };
        fdPuantajHizliHesapCache = new Map();
        fdPuantajHizliGunTuruCache = new Map();
        fdPuantajPrimCalisilmayanCache = new Map();
        fdPuantajIzinlerByPersonelCache = new Map();
        fdPuantajManuelByGunCache = new Map();
        fdMagicpassKayitTurCache = new Map();
        fdMagicpassPersonelIdCache = new Map();
        fdMagicpassPersonelCihazCache = new Map();
        fdMagicpassHareketlerByPersonelCache = new Map();
        fdMagicpassHaftalikVardiyaCache = new Map();
        personeller.filter(aktifSirketeAit).forEach(personel => {
            const personelId = String(personel.id || '');
            if (personelId && !fdMagicpassPersonelIdCache.has(personelId)) fdMagicpassPersonelIdCache.set(personelId, personel);
            const cihazNo = String(personel.cihazPersonelNo || '').trim();
            if (cihazNo && !fdMagicpassPersonelCihazCache.has(cihazNo)) fdMagicpassPersonelCihazCache.set(cihazNo, personel);
        });
        vardiyaKayitlari.forEach(kayit => {
            if (!aktifSirketeAit(kayit)) return;
            const tur = String(kayit.kayitTipi || '');
            if (tur) {
                if (!fdMagicpassKayitTurCache.has(tur)) fdMagicpassKayitTurCache.set(tur, []);
                fdMagicpassKayitTurCache.get(tur).push(kayit);
            } else if (kayit.haftaBaslangic) {
                const sube = String(kayit.sube || '').trim().toLocaleLowerCase('tr-TR');
                const anahtar = `${String(kayit.haftaBaslangic)}|${sube}`;
                const onceki = fdMagicpassHaftalikVardiyaCache.get(anahtar);
                if (!onceki || Number(kayit.guncellemeZamani || kayit.zaman || 0) >= Number(onceki.guncellemeZamani || onceki.zaman || 0)) fdMagicpassHaftalikVardiyaCache.set(anahtar, kayit);
            }
        });
        izinler.forEach(izin => {
            if (!aktifSirketeAit(izin)) return;
            const personelId = String(izin.pId || '');
            if (!fdPuantajIzinlerByPersonelCache.has(personelId)) fdPuantajIzinlerByPersonelCache.set(personelId, []);
            fdPuantajIzinlerByPersonelCache.get(personelId).push(izin);
        });
        puantajVerileri.forEach(kayit => {
            if (!aktifSirketeAit(kayit) || kayit.kayitTipi) return;
            const anahtar = `${String(kayit.pId || '')}|${String(kayit.tarih || '')}`;
            if (!fdPuantajManuelByGunCache.has(anahtar)) fdPuantajManuelByGunCache.set(anahtar, kayit);
        });
        (fdMagicpassKayitTurCache.get('magicpassHareket') || []).forEach(hareket => {
            const personel = magicpassPersonelBul(hareket);
            const personelId = String(personel?.id || '');
            if (!personelId) return;
            if (!fdMagicpassHareketlerByPersonelCache.has(personelId)) fdMagicpassHareketlerByPersonelCache.set(personelId, []);
            fdMagicpassHareketlerByPersonelCache.get(personelId).push(hareket);
        });
        return onceki;
    }

    function fdPuantajHesapOnbelleginiGeriYukle(onceki = {}) {
        fdPuantajHizliHesapCache = onceki.hesap || null;
        fdPuantajHizliGunTuruCache = onceki.gunTuru || null;
        fdPuantajPrimCalisilmayanCache = onceki.prim || null;
        fdPuantajIzinlerByPersonelCache = onceki.izin || null;
        fdPuantajManuelByGunCache = onceki.manuel || null;
        fdMagicpassKayitTurCache = onceki.tur || null;
        fdMagicpassPersonelIdCache = onceki.personelId || null;
        fdMagicpassPersonelCihazCache = onceki.cihaz || null;
        fdMagicpassHareketlerByPersonelCache = onceki.hareket || null;
        fdMagicpassHaftalikVardiyaCache = onceki.haftalik || null;
    }

    function renderPuantajMatrisi(secenekler = {}) {
        const oncekiOnbellek = fdPuantajHesapOnbelleginiBaslat();
        try {
        const ay = parseInt(document.getElementById('puanAySec').value);
        const yil = parseInt(document.getElementById('puanYilSec').value);
        const primFiltre = document.getElementById('puanPrimFiltre')?.value || 'tum';
        const primGorunumu = puantajGorunumu === 'prim';
        const primSabitTutar = primSabitTutariniGetir();
        const primTutarInput = document.getElementById('puanPrimSabitTutar');
        if (primTutarInput) primTutarInput.value = primSabitTutar.toLocaleString('tr-TR', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
        const gunToggle = document.getElementById('puanGunToggle');
        if (gunToggle) gunToggle.textContent = puantajGunlerGizli ? '📅 Günleri Göster' : '📅 Günleri Gizle';
        puantajSubeFiltresiniDoldur();
        const seciliSube = document.getElementById('puanSubeFiltre')?.value || '';
        const personelArama = String(document.getElementById('puanPersonelAra')?.value || '').trim().toLocaleLowerCase('tr-TR');
        const daysInMonth = new Date(yil, ay + 1, 0).getDate();
        const bugun = new Date();
        bugun.setHours(0, 0, 0, 0);
        const izinlerByPersonel = fdPuantajIzinlerByPersonelCache;
        const manuelPuantajByGun = fdPuantajManuelByGunCache;

        const thead = document.querySelector('#puantajTablosu thead');
        const tbody = document.querySelector('#puantajTablosu tbody');
        const puantajTablosu = document.getElementById('puantajTablosu');
        puantajTablosu.classList.toggle('prim-cizelgesi', primGorunumu);
        puantajTablosu.style.setProperty('--prim-gun-sayisi', daysInMonth);
        thead.innerHTML = ''; tbody.innerHTML = '';

        let headHtml = '<tr><th style="width:40px;">#</th><th style="min-width:140px;">Personel Adı</th>';
        if (primGorunumu || !puantajGunlerGizli) {
            for (let d = 1; d <= daysInMonth; d++) headHtml += `<th class="p-gun-baslik">${d}</th>`;
        }
        const ozetBasliklari = primGorunumu
            ? ['Ücretsiz<br>İzin', 'Rapor', 'Gelmedi /<br>Mazeretsiz', 'Toplam<br>Gelmediği', 'Prim Hakkı']
            : ['Çalışma', 'Pazar', 'Resmi<br>Tatil', 'Yıllık<br>İzin', 'Ücretsiz<br>İzin', 'Ücretli<br>İzin', 'Gelmedi /<br>Mazeretsiz', 'Sıhhi<br>İzin', 'Ücret<br>Günü', 'Günlük<br>Ücret', 'Toplam<br>Ücret', 'Fazla Mesai<br>Saati', 'Fazla Mesai<br>Ücreti', 'Pazar Mesai<br>Saati', 'Pazar Mesai<br>Ücreti', 'Resmi Tatil<br>Mesai Saati', 'Resmi Tatil<br>Mesai Ücreti', 'Prim', 'Avans<br>Kesintisi', 'İcra<br>Kesintisi', 'BES<br>Kesintisi', 'Toplam<br>Maaş'];
        headHtml += ozetBasliklari
            .map((baslik, index) => `<th class="p-ozet ${index >= 9 ? 'p-finans' : ''}">${baslik}</th>`).join('') + '</tr>';
        thead.innerHTML = headHtml;


        const primDurumlari = new Map();
        const primDurumuAl = p => {
            const anahtar = String(p.id);
            if (!primDurumlari.has(anahtar)) primDurumlari.set(anahtar, personelPrimDurumu(p, ay, yil));
            return primDurumlari.get(anahtar);
        };
        let aktifPersoneller = personeller.filter(p => {
            if (!aktifSirketeAit(p)) return false;
            const ayBaslangic = `${yil}-${String(ay + 1).padStart(2, '0')}-01`;
            const ayBitis = `${yil}-${String(ay + 1).padStart(2, '0')}-${String(daysInMonth).padStart(2, '0')}`;
            const girisTarihi = tarihInputDegeri(p.girisTarihi);
            const cikisTarihi = tarihInputDegeri(p.cikisTarihi);
            if (girisTarihi && girisTarihi > ayBitis) return false;
            if (cikisTarihi && cikisTarihi < ayBaslangic) return false;
            if (isPersonelUser() && String(p.id) !== String(activeUser.tcNo)) return false;
            if (personelArama && !String(p.ad || '').toLocaleLowerCase('tr-TR').includes(personelArama)) return false;
            if (!primGorunumu && !personelArama && seciliSube && String(p.sube) !== seciliSube) return false;
            if (primGorunumu && p.primVar !== 'Evet') return false;
            if (primGorunumu) {
                const primDurumu = primDurumuAl(p);
                if (primFiltre === 'hak-eden' && !primDurumu.hakkiVar) return false;
                if (primFiltre === 'hak-etmeyen' && primDurumu.hakkiVar) return false;
            }
            return true;
        }).sort((a, b) => {
            const subeSirasi = String(a.sube || '').localeCompare(String(b.sube || ''), 'tr', { sensitivity:'base' });
            return subeSirasi || String(a.ad || '').localeCompare(String(b.ad || ''), 'tr', { sensitivity:'base' });
        });

        const mobilPersonelSecimi = document.getElementById('puanMobilPersonel');
        const mobilTekPersonel = !secenekler.tumPersoneller && !isPersonelUser() && window.matchMedia('(max-width:760px)').matches;
        if (mobilPersonelSecimi && mobilTekPersonel) {
            const oncekiSecim = String(mobilPersonelSecimi.value || '');
            mobilPersonelSecimi.innerHTML = aktifPersoneller.map(p => `<option value="${escapeHtml(String(p.id))}">${escapeHtml(p.ad || 'Personel')} · ${escapeHtml(p.sube || 'Merkez')}</option>`).join('');
            const seciliId = aktifPersoneller.some(p => String(p.id) === oncekiSecim) ? oncekiSecim : String(aktifPersoneller[0]?.id || '');
            mobilPersonelSecimi.value = seciliId;
            aktifPersoneller = seciliId ? aktifPersoneller.filter(p => String(p.id) === seciliId) : [];
        }

        if (aktifPersoneller.length === 0) {
            tbody.innerHTML = '<tr><td colspan="36" style="text-align:center; color:#64748b;">Kayıtlı aktif personel bulunmuyor.</td></tr>';
            return;
        }

        const bodyRows = [];

        aktifPersoneller.forEach((p, index) => {
            const personelAdiHtml = primGorunumu
                ? `<strong>${escapeHtml(p.ad || '')}</strong>`
                : `<button type="button" class="bordro-puantaj-personel-btn" title="${escapeHtml(p.ad || '')} - bu ayın ücret pusulasını aç" onclick="bordroPersonelPusulasiGoruntule('${String(p.id).replace(/'/g, "\\'")}')">${escapeHtml(p.ad || '')}</button>`;
            let rowHtml = `<tr><td>${index + 1}</td><td>${personelAdiHtml}</td>`;
            
            let toplamX = 0, toplamPazar = 0, toplamResmiTatil = 0, toplamY = 0, toplamR = 0, toplamU = 0, toplamZ = 0, toplamM = 0, pazarCalisma = 0, resmiTatilCalisma = 0;
            const iseGirisTarihi = tarihInputDegeri(p.girisTarihi);
            const isCikisTarihi = tarihInputDegeri(p.cikisTarihi);
            const pIzinleri = izinlerByPersonel.get(String(p.id)) || [];
            const izinKoduBul = tarih => {
                const izin = pIzinleri.find(i => tarih >= i.baslangic && tarih <= i.bitis);
                if (!izin) return '';
                if (izin.tur === 'Yıllık İzin') return 'Y';
                if (izin.tur === 'Sağlık / Rapor') return 'R';
                if (['Ücretli İzin', 'Düğün İzni', 'Ölüm İzni', 'Doğum İzni', 'Evlenme İzni'].includes(izin.tur)) return 'Ü';
                if (izin.tur === 'Ücretsiz İzin') return 'Z';
                if (izin.tur === 'Mazeretsiz İzin') return 'M';
                return '';
            };

            for (let d = 1; d <= daysInMonth; d++) {
                let currDate = new Date(yil, ay, d);
                let m = String(ay + 1).padStart(2, '0');
                let dayStr = String(d).padStart(2, '0');
                let dateKey = `${yil}-${m}-${dayStr}`;
                const primBugunTamamlanmadi = primGorunumu && dateKey === magicpassTarihAnahtari(new Date()) && !primGunuTamamlandiMi(p, dateKey);

                const calismaDisiTarih = (iseGirisTarihi && dateKey < iseGirisTarihi) || (isCikisTarihi && dateKey > isCikisTarihi);
                let harf = calismaDisiTarih ? '-' : '';

                if (!calismaDisiTarih) {
                    if (currDate.getDay() === 0) harf = 'HS';
                    const mm_dd = `${m}-${dayStr}`;
                    if (sabitResmiTatiller.includes(mm_dd)) harf = 'RT';

                    const izinKodu = izinKoduBul(dateKey);
                    const pazarVeyaResmiTatil = harf === 'HS' || harf === 'RT';
                    if (izinKodu === 'Y' || izinKodu === 'Ü') {
                        if (!pazarVeyaResmiTatil) harf = izinKodu;
                    } else if (['R', 'Z', 'M'].includes(izinKodu)) {
                        harf = izinKodu;
                    } else if (harf === 'HS' || harf === 'RT') {
                        const oncekiGun = new Date(yil, ay, d - 1);
                        const oncekiTarih = `${oncekiGun.getFullYear()}-${String(oncekiGun.getMonth() + 1).padStart(2, '0')}-${String(oncekiGun.getDate()).padStart(2, '0')}`;
                        const oncekiGunIzinKodu = izinKoduBul(oncekiTarih);
                        if (['R', 'Z', 'M'].includes(oncekiGunIzinKodu)) harf = oncekiGunIzinKodu;
                    }

                    const cihazGunTuru = typeof magicpassGunTuruBul === 'function' ? magicpassGunTuruBul(p, dateKey) : '';
                    if (!izinKodu && cihazGunTuru === 'pazar') harf = 'HS';
                    else if (!izinKodu && cihazGunTuru === 'resmiTatil') harf = 'RT';
                    else if (!izinKodu && cihazGunTuru === 'yarimResmiTatil') harf = 'X';
                    if (!izinKodu && currDate <= bugun && !primBugunTamamlanmadi) {
                        const cihazGunu = magicpassGunHesapla(p, dateKey);
                        const cihazdaHareketVar = Boolean(cihazGunu.giris || cihazGunu.cikis);
                        if (cihazGunTuru === 'yarimResmiTatil') {
                            harf = 'X';
                        } else if (cihazdaHareketVar) {
                            harf = harf === 'HS' ? 'PZ' : (harf === 'RT' ? 'RC' : 'X');
                        } else if (cihazGunu.pazarHakkiYok) {
                            harf = 'M';
                        } else if (cihazGunu.durum === 'Gelmedi' && harf !== 'HS' && harf !== 'RT') {
                            harf = 'M';
                        } else if (harf !== 'HS' && harf !== 'RT') {
                            harf = '';
                        }
                    }

                    const foundObj = manuelPuantajByGun.get(`${String(p.id)}|${dateKey}`);
                    if (foundObj && foundObj.durum && !(primGorunumu && izinKodu)) harf = String(foundObj.durum).toUpperCase();
                    if (primGorunumu && izinKodu && currDate > bugun && (['R', 'Z', 'M'].includes(izinKodu) || !pazarVeyaResmiTatil)) harf = izinKodu;
                    if (primBugunTamamlanmadi && !izinKodu && harf !== 'HS' && harf !== 'RT') harf = '';
                }

                if (harf === 'X') toplamX++;
                else if (harf === 'HS' || harf === 'PZ') { if(currDate <= bugun){ toplamPazar++; if (harf === 'PZ') pazarCalisma++; } }
                else if (harf === 'RT' || harf === 'RC') { if(currDate <= bugun){ toplamResmiTatil++; if (harf === 'RC') resmiTatilCalisma++; } }
                else if (harf === 'Y') toplamY++;
                else if (harf === 'R') toplamR++;
                else if (harf === 'Ü') toplamU++;
                else if (harf === 'Z') toplamZ++;
                else if (harf === 'M') toplamM++;

                if (primGorunumu) {
                    const gosterim = primGunTatilGosterimi(p, dateKey, harf);
                    const cellClass = getPuantajCellClass(gosterim.kod);
                    rowHtml += `<td class="p-gun-hucresi" title="${escapeHtml(gosterim.aciklama)}"><input type="text" maxlength="2" class="${cellClass}" value="${gosterim.kod}" title="${escapeHtml(gosterim.aciklama)}" disabled></td>`;
                } else if (!puantajGunlerGizli) {
                    const cellClass = getPuantajCellClass(harf);
                    rowHtml += `<td class="p-gun-hucresi"><input type="text" maxlength="2" class="${cellClass}" value="${harf}" ${calismaDisiTarih || isPersonelUser() ? 'disabled' : `oninput="puantajHucreDegisti('${p.id}', '${dateKey}', this)" oncontextmenu="openContextMenu(event, this, '${p.id}', '${dateKey}')"`}></td>`;
                }
            }

            const toplamCalisilmayan = personelPrimCalisilmayanGunSayisi(p, ay, yil);
            const toplamCalisilmayanMetni = toplamCalisilmayan.toLocaleString('tr-TR', { minimumFractionDigits:0, maximumFractionDigits:1 });
            const yarimGunEksikligi = Math.max(0, toplamCalisilmayan - toplamZ - toplamR - toplamM);
            const mazeretsizToplam = Math.round((toplamM + yarimGunEksikligi) * 2) / 2;
            const mazeretsizToplamMetni = mazeretsizToplam.toLocaleString('tr-TR', { minimumFractionDigits:0, maximumFractionDigits:1 });
            const primDurumu = primDurumuAl(p);
            const primHakkiYok = !primDurumu.hakkiVar;
            if (primGorunumu) {
                rowHtml = rowHtml.replace('<tr>', `<tr class="${primHakkiYok ? 'puantaj-no-prime' : ''}">`);
                rowHtml += `<td class="p-ozet">${toplamZ}</td><td class="p-ozet">${toplamR}</td><td class="p-ozet">${mazeretsizToplamMetni}</td><td class="p-ozet">${toplamCalisilmayanMetni}</td><td class="p-ozet p-prim-sonuc ${primHakkiYok ? 'p-prim-yok' : 'p-prim-var'}" title="Prim hakkını manuel değiştirmek için sağ tıklayın" oncontextmenu="openPrimHakkiDuzenleme(event, '${p.id}')">${primHakkiYok ? 'Prim Yok' : 'Prim Var'}${primDurumu.manuel ? ' ✦' : ''}</td></tr>`;
                bodyRows.push(rowHtml);
                return;
            }
            const ozet = maasOzetKaydiBul(p.id, ay, yil) || {};
            const gunlukYevmiye = personelGunlukUcretiniGetir(p);
            const toplamUcretGunu = toplamX + toplamPazar + toplamResmiTatil + toplamY + toplamU;
            const fazlaMesaiSaati = String(ozet.fazlaMesaiSaatiManuel) === 'true' ? Number(ozet.fazlaMesaiSaati || 0) : magicpassAylikMesaiSaati(p, ay, yil);
            const gunlukCalismaSaati = ayarSayisi('gunlukCalismaSaati', 7.5);
            const birlesikMesai = magicpassBirlesikMesaiDonemiMi(p, ay, yil);
            const pazarMesaiSaati = String(ozet.pazarMesaiSaatiManuel) === 'true' ? Number(ozet.pazarMesaiSaati || 0) : birlesikMesai ? 0 : pazarCalisma * gunlukCalismaSaati;
            const resmiTatilMesaiSaati = String(ozet.resmiTatilMesaiSaatiManuel) === 'true' ? Number(ozet.resmiTatilMesaiSaati || 0) : birlesikMesai ? 0 : resmiTatilCalisma * gunlukCalismaSaati + magicpassAylikYarimResmiTatilMesaiSaati(p, ay, yil);
            const primVar = p.primVar === 'Evet' && primDurumu.hakkiVar;
            const primTutari = String(ozet.primTutariManuel) === 'true' ? Number(ozet.primTutari || 0) : (primVar ? primSabitTutar : 0);
            const avansKesintisi = personelAylikAvansKesintisi(p.id, ay, yil);
            const aktifIcra = aktifIcraBul(p.id);
            const icraKesintisi = personelIcraKayitlari(p.id).length
                ? personelAylikIcraKesintisi(p.id, ay, yil)
                : Number(ozet.icraKesintisi || 0);
            const besKesintisi = Math.max(0, Number(ozet.besKesintisi || 0));
            const saatlikMesai = gunlukYevmiye / gunlukCalismaSaati * ayarSayisi('mesaiKatsayisi', 1.5);
            const toplamUcret = toplamUcretGunu * gunlukYevmiye;
            const fazlaMesaiUcreti = fazlaMesaiSaati * saatlikMesai;
            const pazarMesaiUcreti = pazarMesaiSaati * saatlikMesai;
            const resmiTatilMesaiUcreti = resmiTatilMesaiSaati * saatlikMesai;
            const toplamMaas = toplamUcret + fazlaMesaiUcreti + pazarMesaiUcreti + resmiTatilMesaiUcreti + primTutari - avansKesintisi - icraKesintisi - besKesintisi;
            const sayisalInput = (alan, deger, bosBirak = false, sinif = '') => `<input class="${sinif}" data-maas-alan="${alan}" type="text" inputmode="decimal" value="${bosBirak ? '' : Number(deger || 0).toLocaleString('tr-TR', { minimumFractionDigits: 0, maximumFractionDigits: 2 })}" ${isPersonelUser() ? 'disabled' : `oninput="paraGirisiFormatla(this); maasSatiriniOnizle(this)" onchange="maasOzetAlaniniKaydet('${p.id}', '${alan}', this)"`}>`;
            rowHtml = rowHtml.replace('<tr>', `<tr class="${primGorunumu && primHakkiYok ? 'puantaj-no-prime' : ''}" data-gunluk="${gunlukYevmiye}" data-ucret-gunu="${toplamUcretGunu}" data-avans="${avansKesintisi}">`);
            rowHtml += `
                <td class="p-ozet">${toplamX}</td><td class="p-ozet">${toplamPazar}</td><td class="p-ozet">${toplamResmiTatil}</td><td class="p-ozet">${toplamY}</td><td class="p-ozet">${toplamZ}</td><td class="p-ozet">${toplamU}</td><td class="p-ozet">${toplamM}</td><td class="p-ozet">${toplamR}</td><td class="p-ozet">${toplamUcretGunu}</td>
                <td class="p-ozet p-finans">${paraFormatla(gunlukYevmiye)}</td><td class="p-ozet p-finans" data-maas-sonuc="toplamUcret">${paraFormatla(toplamUcret)}</td>
                <td class="p-ozet p-finans">${sayisalInput('fazlaMesaiSaati', fazlaMesaiSaati)}</td><td class="p-ozet p-finans" data-maas-sonuc="fazlaMesaiUcreti">${paraFormatla(fazlaMesaiUcreti)}</td>
                <td class="p-ozet p-finans">${sayisalInput('pazarMesaiSaati', pazarMesaiSaati)}</td><td class="p-ozet p-finans" data-maas-sonuc="pazarMesaiUcreti">${paraFormatla(pazarMesaiUcreti)}</td>
                <td class="p-ozet p-finans">${sayisalInput('resmiTatilMesaiSaati', resmiTatilMesaiSaati)}</td><td class="p-ozet p-finans" data-maas-sonuc="resmiTatilMesaiUcreti">${paraFormatla(resmiTatilMesaiUcreti)}</td>
                <td class="p-ozet p-finans">${sayisalInput('primTutari', primTutari)}</td><td class="p-ozet p-finans">${paraFormatla(avansKesintisi)}</td>
                <td class="p-ozet p-finans">${sayisalInput('icraKesintisi', icraKesintisi, !!aktifIcra && String(ozet.icraKesintisiManuel) !== 'true' && !icraKesintisi, aktifIcra && String(ozet.icraKesintisiManuel) !== 'true' && !icraKesintisi ? 'icra-eksik' : '')}</td>
                <td class="p-ozet p-finans">${sayisalInput('besKesintisi', besKesintisi)}</td>
                <td class="p-ozet p-finans" data-maas-sonuc="toplamMaas">${paraFormatla(toplamMaas)}</td>
            </tr>`;

            bodyRows.push(rowHtml);
        });
        tbody.innerHTML = bodyRows.join('');
        puantajMobilEtiketleriniUygula();
        } finally {
            fdPuantajHesapOnbelleginiGeriYukle(oncekiOnbellek);
        }
    }

    let manuelPrimHakkiTarget = null;

    function openPrimHakkiDuzenleme(event, pId) {
        event.preventDefault();
        if (!isManagerUser()) {
            alert('Prim hakkı manuel değişikliği yalnızca Admin veya Yönetici tarafından yapılabilir.');
            return;
        }

        const ay = Number(document.getElementById('puanAySec').value);
        const yil = Number(document.getElementById('puanYilSec').value);
        const personel = personeller.find(item => String(item.id) === String(pId));
        if (!personel) return;

        const durum = personelPrimDurumu(personel, ay, yil);
        manuelPrimHakkiTarget = { pId: String(pId), ay, yil };
        document.getElementById('manuelPrimPersonel').textContent = `${personel.ad} — ${yil} / ${String(ay + 1).padStart(2, '0')}`;
        document.getElementById('manuelPrimHakki').value = durum.hakkiVar ? 'Var' : 'Yok';
        document.getElementById('modalPrimHakki').style.display = 'flex';
    }

    function closePrimHakkiModal() {
        manuelPrimHakkiTarget = null;
        document.getElementById('modalPrimHakki').style.display = 'none';
    }

    async function manuelPrimHakkiniKaydet() {
        if (!manuelPrimHakkiTarget) return;
        const { pId, ay, yil } = manuelPrimHakkiTarget;
        const primHakki = document.getElementById('manuelPrimHakki').value;
        const personel = personeller.find(item => String(item.id) === String(pId));
        if (!personel) return;

        const ozetTarihi = `${yil}-${String(ay + 1).padStart(2, '0')}-00`;
        const mevcut = primOzetKaydiBul(pId, ay, yil);
        const calisilmayanGun = personelPrimCalisilmayanGunSayisi(personel, ay, yil);
        const yeniKayit = {
            pId,
            tarih: ozetTarihi,
            durum: 'PRIM_OZET',
            kayitTipi: 'primOzet',
            primHakki,
            primHakkiManuel: 'true',
            calisilmayanGun,
            sirketId: aktifSirketId()
        };

        if (mevcut) puantajVerileri[puantajVerileri.indexOf(mevcut)] = yeniKayit;
        else puantajVerileri.push(yeniKayit);

        await verileriKaydet();
        closePrimHakkiModal();
        renderPuantajMatrisi();
    }

    function openContextMenu(event, inputEl, pId, dateKey) {
        event.preventDefault();
        if (isPersonelUser()) return;
        contextMenuTargetInput = { inputEl, pId, dateKey };
        const menu = document.getElementById('customContextMenu');
        menu.style.display = 'block';
        menu.style.left = `${event.pageX}px`;
        menu.style.top = `${event.pageY}px`;
    }

    async function selectContextMenuValue(val) {
        if (isPersonelUser()) return;
        if (!contextMenuTargetInput) return;
        const { inputEl, pId, dateKey } = contextMenuTargetInput;

        inputEl.value = val;
        inputEl.className = getPuantajCellClass(val);

        document.getElementById('customContextMenu').style.display = 'none';
        try {
            await kaydetVeyaGuncellePuantaj(pId, dateKey, val);
        } finally {
            contextMenuTargetInput = null;
            renderPuantajMatrisi();
        }
    }

    async function puantajHucreDegisti(pId, dateKey, inputEl) {
        if (isPersonelUser()) return;
        let val = inputEl.value.trim().toUpperCase();
        if (!['X', 'Y', 'R', 'Ü', 'Z', 'M', 'HS', 'RT', 'RC', 'PZ'].includes(val)) {
            val = 'X';
            inputEl.value = 'X';
        }
        
        inputEl.className = getPuantajCellClass(val);
        try {
            await kaydetVeyaGuncellePuantaj(pId, dateKey, val);
        } finally {
            renderPuantajMatrisi();
        }
    }

    async function kaydetVeyaGuncellePuantaj(pId, dateKey, val) {
        const oncekiPuantajVerileri = puantajVerileri;
        puantajVerileri = puantajVerileri.filter(item => !(!item.kayitTipi && aktifSirketeAit(item) && String(item.pId) === String(pId) && String(item.tarih) === String(dateKey)));
        puantajVerileri.push({ id:`puantaj_gun_${String(pId)}_${String(dateKey)}`, pId: String(pId), tarih: String(dateKey), durum: String(val).toUpperCase(), sirketId: aktifSirketId() });
        try {
            await verileriKaydet();
        } catch (error) {
            puantajVerileri = oncekiPuantajVerileri;
            throw error;
        }
    }

    async function manuelPuantajKayitlariniTemizle() {
        if (!isManagerUser()) {
            alert('Manuel puantaj ve prim müdahalelerini yalnızca Admin veya Yönetici temizleyebilir.');
            return;
        }

        const mesaj = puantajGorunumu === 'prim'
            ? 'Prim uyarısı: Bu işlem yalnızca manuel prim kararlarını ve elle girilmiş puantaj günlerini kaldırır. İzinlerden gelen kayıtlar ile otomatik hesaplamalar korunur. Devam edilsin mi?'
            : 'Bu işlem yalnızca elle girilmiş puantaj günlerini ve manuel prim kararlarını kaldırır. İzin bölümündeki kayıtlar ile otomatik günler korunur. Devam edilsin mi?';
        if (!await fdYuzerOnaySor(mesaj)) return;

        const sirketId = aktifSirketId();
        puantajVerileri = puantajVerileri.filter(item => {
            if (sirketId && item.sirketId && String(item.sirketId) !== sirketId) return true;
            if (item.kayitTipi === 'primOzet') return String(item.primHakkiManuel) !== 'true';
            return Boolean(item.kayitTipi);
        });

        await verileriKaydet();
        renderPuantajMatrisi();
        alert('Manuel puantaj ve prim müdahaleleri temizlendi. İzin ve otomatik kayıtlar korunuyor.');
    }

    function exportPuantajToExcel() {
        const wb = XLSX.utils.book_new();
        // Türkçe sayı biçimlerini (7,5 ve 2.000 gibi) Excel'in 75 / 2 olarak yorumlamaması için metin olarak aktar.
        XLSX.utils.book_append_sheet(wb, XLSX.utils.table_to_sheet(puantajTablosunuExcelIcinHazirla(), { raw: true }), "Aylik_Puantaj");
        XLSX.writeFile(wb, "Personel_Puantaj_Cizelgesi.xlsx");
    }

    function puantajTablosunuExcelIcinHazirla() {
        const clone = document.getElementById('puantajTablosu').cloneNode(true);
        clone.querySelectorAll('input').forEach(input => {
            const cell = input.closest('td');
            if (cell) cell.textContent = input.value;
        });
        return clone;
    }

    function mesaiExcelDosyasiSec() {
        document.getElementById('mesaiExcelDosyasi').click();
    }

    function mesaiMetniniEslestirmeIcinDuzenle(deger) {
        return String(deger || '').trim().toLocaleUpperCase('tr-TR')
            .replace(/Ç/g, 'C').replace(/Ğ/g, 'G').replace(/İ/g, 'I').replace(/İ/g, 'I')
            .replace(/Ö/g, 'O').replace(/Ş/g, 'S').replace(/Ü/g, 'U')
            .replace(/[^A-Z0-9]/g, '');
    }

    function excelMesaiSaatiniSayiyaCevir(deger) {
        if (typeof deger === 'number') return Number.isFinite(deger) ? Math.max(0, deger) : 0;
        let metin = String(deger || '').trim().replace(/\s/g, '');
        if (!metin) return 0;
        if (metin.includes(',') && metin.includes('.')) metin = metin.replace(/\./g, '').replace(',', '.');
        else if (metin.includes(',')) metin = metin.replace(',', '.');
        const sayi = Number(metin);
        return Number.isFinite(sayi) ? Math.max(0, sayi) : 0;
    }

    function mesaiSaatiniYukariYarimaYuvarla(saat) {
        const adim = ayarSayisi('mesaiYuvarlamaAdimi', 0.5);
        return Math.ceil(Math.max(0, Number(saat) || 0) / adim) * adim;
    }

    async function mesaiExcelDosyasiniOku(event) {
        const dosya = event.target.files?.[0];
        event.target.value = '';
        if (!dosya) return;
        if (typeof XLSX === 'undefined') { alert('Excel okuma kütüphanesi yüklenemedi. Sayfayı yenileyip tekrar deneyin.'); return; }

        try {
            showGlobalOverlay('Excel okunuyor', 'Personel adları ve mesai saatleri eşleştiriliyor...');
            const veri = await dosya.arrayBuffer();
            const kitap = XLSX.read(veri, { type:'array' });
            const sayfa = kitap.Sheets[kitap.SheetNames[0]];
            const satirlar = XLSX.utils.sheet_to_json(sayfa, { header:1, defval:'', raw:true });
            if (!satirlar.length) throw new Error('Excel dosyasında okunabilir satır bulunamadı.');

            const baslikSatirNo = satirlar.findIndex(satir => satir.some(h => /ad\s*soyad|personel|mesai|saat/i.test(String(h))));
            const baslik = satirlar[baslikSatirNo > -1 ? baslikSatirNo : 0].map(mesaiMetniniEslestirmeIcinDuzenle);
            let adSutunu = baslik.findIndex(h => /ADSOYAD|PERSONELADI|PERSONEL|ISIMSOYISIM|AD/.test(h));
            let mesaiSutunu = baslik.findIndex(h => /FAZLAMESAI|MESAI|MESAISAA?TI|SAA?T/.test(h));
            if (adSutunu < 0) adSutunu = 0;
            if (mesaiSutunu < 0) mesaiSutunu = 1;
            const veriBaslangici = baslikSatirNo > -1 ? baslikSatirNo + 1 : 1;

            const excelMesaileri = new Map();
            satirlar.slice(veriBaslangici).forEach(satir => {
                const ad = mesaiMetniniEslestirmeIcinDuzenle(satir[adSutunu]);
                const saat = excelMesaiSaatiniSayiyaCevir(satir[mesaiSutunu]);
                if (ad && saat > 0) excelMesaileri.set(ad, (excelMesaileri.get(ad) || 0) + saat);
            });
            if (!excelMesaileri.size) throw new Error('Ad soyad ve mesai saati sütunları bulunamadı. İlk sayfada bu iki sütunun olduğundan emin olun.');

            const ay = Number(document.getElementById('puanAySec').value);
            const yil = Number(document.getElementById('puanYilSec').value);
            const tarih = `${puantajAyAnahtari(ay, yil)}-00`;
            const personelIndeksi = new Map(personeller.filter(p => aktifSirketeAit(p)).map(p => [mesaiMetniniEslestirmeIcinDuzenle(p.ad), p]));
            const eslesmeyenler = [];
            let aktarilan = 0;

            excelMesaileri.forEach((saat, ad) => {
                const personel = personelIndeksi.get(ad);
                if (!personel) { eslesmeyenler.push(ad); return; }
                const yuvarlanmisSaat = mesaiSaatiniYukariYarimaYuvarla(saat);
                const mevcut = puantajVerileri.find(k => k.kayitTipi === 'maasOzet' && String(k.pId) === String(personel.id) && String(k.tarih) === tarih && String(k.sirketId || '') === aktifSirketId());
                const yeni = { ...(mevcut || {}), pId:String(personel.id), tarih, durum:'MAAS_OZET', kayitTipi:'maasOzet', sirketId:aktifSirketId(), fazlaMesaiSaati:yuvarlanmisSaat, fazlaMesaiSaatiManuel:'true' };
                if (mevcut) puantajVerileri[puantajVerileri.indexOf(mevcut)] = yeni;
                else puantajVerileri.push(yeni);
                aktarilan++;
            });

            if (!aktarilan) throw new Error('Exceldeki personel adları kayıtlı personellerle eşleşmedi.');
            yuklenenVeriler.add('puantaj');
            await verileriKaydet();
            renderPuantajMatrisi();
            const ekBilgi = eslesmeyenler.length ? ` Eşleşmeyen ${eslesmeyenler.length} isim aktarılmadı.` : '';
            alert(`${aktarilan} personelin fazla mesai saati seçili aya aktarıldı.${ekBilgi}`);
        } catch (error) {
            console.error(error);
            alert(error.message || 'Excel dosyası okunamadı.');
        } finally {
            hideGlobalOverlay();
        }
    }

    async function puantajCanvasOlustur(table, scale = 2, baslik = '') {
        try {
            if (typeof html2canvas === 'function') {
                const sabitler=[...table.querySelectorAll('thead,thead tr,thead th')],oncekiStiller=sabitler.map(el=>el.getAttribute('style'));
                sabitler.forEach(el=>{el.style.setProperty('position','static','important');el.style.setProperty('top','auto','important');el.style.setProperty('transform','none','important');el.style.setProperty('inset','auto','important');});
                try {
                    await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
                    return await html2canvas(table, { backgroundColor:'#ffffff', scale, useCORS:true, width:table.scrollWidth, height:table.scrollHeight, windowWidth:table.scrollWidth, scrollY:0, onclone:doc=>{const kopya=doc.getElementById('puantajTablosu');kopya?.querySelectorAll('thead,thead tr,thead th').forEach(el=>{el.style.setProperty('position','static','important');el.style.setProperty('top','auto','important');el.style.setProperty('transform','none','important');el.style.setProperty('inset','auto','important');});} });
                } finally {
                    sabitler.forEach((el,index)=>{const stil=oncekiStiller[index];if(stil===null)el.removeAttribute('style');else el.setAttribute('style',stil);});
                }
            }
        } catch (error) {
            console.warn('Standart görüntü alma denemesi başarısız oldu, yedek yöntem kullanılıyor.', error);
        }

        const rows = Array.from(table.rows);
        const widths = Array.from(rows[0].cells).map(cell => Math.max(cell.getBoundingClientRect().width, 34));
        const rowHeight = 31;
        const width = Math.ceil(widths.reduce((sum, value) => sum + value, 0));
        const baslikYuksekligi = baslik ? 48 : 0;
        const height = Math.max(rows.length * rowHeight, rowHeight) + baslikYuksekligi;
        const canvas = document.createElement('canvas');
        canvas.width = width * scale;
        canvas.height = height * scale;
        const ctx = canvas.getContext('2d');
        ctx.scale(scale, scale);
        ctx.font = '600 11px Arial';
        ctx.textBaseline = 'middle';

        if (baslik) {
            const [cizelgeBasligi, donemBilgisi] = String(baslik).split(' — ');
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, width, baslikYuksekligi);
            ctx.fillStyle = '#06b6d4';
            ctx.fillRect(0, baslikYuksekligi - 3, width, 3);
            ctx.fillStyle = '#0f172a';
            ctx.font = '800 16px Arial';
            ctx.textAlign = 'left';
            ctx.fillText(cizelgeBasligi, 18, 25, Math.max(width * .68, 10));
            ctx.fillStyle = '#475569';
            ctx.font = '700 12px Arial';
            ctx.textAlign = 'right';
            ctx.fillText(donemBilgisi || '', width - 18, 25, Math.max(width * .30, 10));
            ctx.font = '600 11px Arial';
        }

        rows.forEach((row, rowIndex) => {
            const y = baslikYuksekligi + (rowIndex * rowHeight);
            let x = 0;
            Array.from(row.cells).forEach((cell, cellIndex) => {
                const cellWidth = widths[cellIndex];
                const isHeader = row.parentElement.tagName === 'THEAD';
                const style = getComputedStyle(cell), rowStyle = getComputedStyle(row);
                const hucreArka = style.backgroundColor === 'rgba(0, 0, 0, 0)' ? rowStyle.backgroundColor : style.backgroundColor;
                ctx.fillStyle = isHeader ? '#0f172a' : (!hucreArka || hucreArka === 'rgba(0, 0, 0, 0)' ? '#ffffff' : hucreArka);
                ctx.fillRect(x, y, cellWidth, rowHeight);
                ctx.strokeStyle = '#cbd5e1';
                ctx.strokeRect(x, y, cellWidth, rowHeight);
                const input = cell.querySelector('input');
                const text = String(input ? input.value : cell.innerText).replace(/\s+/g, ' ').trim();
                ctx.fillStyle = isHeader ? '#ffffff' : (style.color && style.color !== 'rgba(0, 0, 0, 0)' ? style.color : '#0f172a');
                ctx.textAlign = cellIndex === 1 ? 'left' : 'center';
                const textX = cellIndex === 1 ? x + 7 : x + (cellWidth / 2);
                ctx.fillText(text, textX, y + (rowHeight / 2), Math.max(cellWidth - 8, 10));
                x += cellWidth;
            });
        });
        return canvas;
    }

    async function exportPuantajToPDF() {
        const ay = document.getElementById('puanAySec').options[document.getElementById('puanAySec').selectedIndex].text;
        const yil = document.getElementById('puanYilSec').value;
        const table = document.getElementById('puantajTablosu');
        if(!table||table.rows.length<2)return alert('PDF için gösterilecek puantaj kaydı bulunmuyor.');
        showGlobalOverlay('PDF hazırlanıyor', 'Çizelge tek sayfaya sığdırılıyor...');
        try {
            const cizelgeAdi = puantajGorunumu === 'prim' ? 'AYLIK PRİM HAKEDİŞ ÇİZELGESİ' : 'AYLIK PERSONEL PUANTAJ ÇİZELGESİ';
            const tabloCanvas = await puantajCanvasOlustur(table, 1.5, '');
            if(!tabloCanvas||tabloCanvas.width<2||tabloCanvas.height<2)throw new Error('Puantaj görüntüsü boş oluştu.');
            const baslikYuksekligi=72,canvas=document.createElement('canvas');canvas.width=tabloCanvas.width;canvas.height=tabloCanvas.height+baslikYuksekligi;const baslikCtx=canvas.getContext('2d');baslikCtx.fillStyle='#fff';baslikCtx.fillRect(0,0,canvas.width,canvas.height);baslikCtx.fillStyle='#0f172a';baslikCtx.font='800 28px Arial';baslikCtx.textBaseline='middle';baslikCtx.textAlign='left';baslikCtx.fillText(cizelgeAdi,24,31,Math.max(100,canvas.width*.68));baslikCtx.fillStyle='#475569';baslikCtx.font='700 21px Arial';baslikCtx.textAlign='right';baslikCtx.fillText(`${String(ay).toLocaleUpperCase('tr-TR')} ${yil}`,canvas.width-24,31,Math.max(100,canvas.width*.28));baslikCtx.fillStyle='#0f766e';baslikCtx.fillRect(0,baslikYuksekligi-5,canvas.width,5);baslikCtx.drawImage(tabloCanvas,0,baslikYuksekligi);
            const JsPDF = window.jspdf?.jsPDF || window.jsPDF;
            if (!JsPDF) throw new Error('PDF kütüphanesi yüklenemedi.');

            // Görseli doğrudan A2 yatay sayfa genişliğine ölçekle: sağ tarafın kesilmesini önler.
            const pdf = new JsPDF({ orientation:'landscape', unit:'mm', format:'a2' });
            const kenar = 8;
            const sayfaGenisligi = pdf.internal.pageSize.getWidth();
            const sayfaYuksekligi = pdf.internal.pageSize.getHeight();
            const yazdirmaGenisligi = sayfaGenisligi - (kenar * 2);
            const yazdirmaYuksekligi = sayfaYuksekligi - (kenar * 2);
            const kaynakParcaYuksekligi = Math.max(1, Math.floor(canvas.width * yazdirmaYuksekligi / yazdirmaGenisligi));
            let baslangicY = 0;
            let sayfa = 0;

            while (baslangicY < canvas.height) {
                const parcaYuksekligi = Math.min(kaynakParcaYuksekligi, canvas.height - baslangicY);
                const parca = document.createElement('canvas');
                parca.width = canvas.width;
                parca.height = parcaYuksekligi;
                parca.getContext('2d').drawImage(canvas, 0, baslangicY, canvas.width, parcaYuksekligi, 0, 0, canvas.width, parcaYuksekligi);
                if (sayfa > 0) pdf.addPage('a2', 'landscape');
                pdf.addImage(parca.toDataURL('image/jpeg',.91), 'JPEG', kenar, kenar, yazdirmaGenisligi, parcaYuksekligi * yazdirmaGenisligi / canvas.width, undefined, 'FAST');
                baslangicY += parcaYuksekligi;
                sayfa++;
            }
            fdCiktiPdfOnizle(pdf.output('blob'),`${yil}_${ay}_${puantajGorunumu === 'prim' ? 'Prim' : 'Puantaj'}.pdf`);
        } catch (error) {
            console.error('Puantaj PDF oluşturma hatası:', error);
            alert('Puantaj PDF oluşturulamadı: ' + (error?.message || error));
        } finally {
            hideGlobalOverlay();
        }
    }

    async function puantajGoruntusuAlVePaylas() {
        const table = document.getElementById('puantajTablosu');
        if (!table || !table.rows.length) return;

        showGlobalOverlay('Ekran görüntüsü alınıyor', 'Puantaj çizelgesi hazırlanıyor...');

        try {
            const ay = document.getElementById('puanAySec').options[document.getElementById('puanAySec').selectedIndex].text;
            const yil = document.getElementById('puanYilSec').value;
            const cizelgeAdi = puantajGorunumu === 'prim' ? 'AYLIK PRİM HAKEDİŞ ÇİZELGESİ' : 'AYLIK PERSONEL PUANTAJ ÇİZELGESİ';
            const canvas = await puantajCanvasOlustur(table, 2, `${cizelgeAdi} — ${String(ay).toLocaleUpperCase('tr-TR')} ${yil}`);
            const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
            if (!blob) throw new Error('Görüntü oluşturulamadı.');

            if (!(navigator.clipboard && window.ClipboardItem)) {
                throw new Error('Tarayıcı görüntüyü panoya kopyalamayı desteklemiyor.');
            }
            await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
            showGlobalOverlay('Ekran görüntüsü kopyalandı', 'Görüntü panoya kopyalandı. İstediğiniz yere yapıştırabilirsiniz.');
            setTimeout(hideGlobalOverlay, 1300);
        } catch (error) {
            hideGlobalOverlay();
            alert('Ekran görüntüsü alınamadı. Lütfen tekrar deneyin.');
            console.error(error);
        }
    }

    /* driveVerileriniYukle → core/data-access.js */

    async function verileriKaydet() {
        if (SUPABASE_MODE) {
            try { await supabaseVerileriKaydet(); }
            catch (e) {
                console.error('Supabase kaydetme hatası:', e);
                showToast('Kayıt buluta yazılamadı: ' + (e.message || 'Bağlantıyı kontrol edin.'), 'error');
                throw e;
            }
            return;
        }
        try {
            veriOnbelleginiKaydet();
            const payload = { kayitYili: aktifKayitYili };
            const anahtarlar = ['personeller', 'izinler', 'kullanicilar', 'puantaj', 'sirketler', 'subeler', 'avanslar', 'ekOdemeler', 'kkd', 'vardiya', 'irsaliyeler', 'icralar', 'araclar', 'akaryakit'];
            anahtarlar.forEach(anahtar => {
                if (yuklenenVeriler.has(anahtar) && veriDegistiMi(anahtar)) payload[anahtar] = veriDizisiniGetir(anahtar);
            });
            if (Object.keys(payload).length === 1) return;
            await fetch(GOOGLE_SCRIPT_URL, {
                method: 'POST', mode: 'no-cors',
                headers: { 'Content-Type': 'text/plain;charset=utf-8' },
                body: JSON.stringify(payload)
            });
            Object.keys(payload).filter(anahtar => anahtar !== 'kayitYili').forEach(veriKayitGoruntusunuYenile);
        } catch (e) { console.error("Kaydetme hatası:", e); }
    }

    function kullaniciMesajiniSadlestir(metin) {
        return String(metin ?? '')
            .replace(/Supabase\s+veritabanına/gi,'sisteme').replace(/Supabase/gi,'sistem')
            .replace(/bulut\s+veritabanına/gi,'sisteme').replace(/veritabanına/gi,'sisteme')
            .replace(/Drive['’]?a/gi,'dosya alanına').replace(/Drive\s+belgeleri/gi,'belgeler')
            .replace(/bilgiler\s+geçmişe\s+işleniyor/gi,'bilgiler güncelleniyor')
            .replace(/kayıt\s+ve\s+bağlı\s+dosya\s+alanına\s+belgeleri/gi,'kayıt ve bağlı belgeler');
    }
