    /* supabaseKullaniciOlustur → modules/kullanici/kullanici.js */

    async function personelKullaniciHesabiOlustur(personel) {
        const tcNo = String(personel?.id || '');
        const exists = kullanicilar.some(user => String(user.username) === tcNo || String(user.tcNo) === tcNo);
        if (exists) return false;
        if (SUPABASE_MODE) {
            await supabaseKullaniciOlustur({
                username: tcNo, password: tcNo.slice(0, 6), rol: 'Personel', tcNo, ad: personel.ad
            });
        }
        const yeniKullanici = { username: tcNo, rol: 'Personel', tcNo, sirketId: aktifSirketId() };
        if (!SUPABASE_MODE) yeniKullanici.password = tcNo.slice(0, 6);
        kullanicilar.push(yeniKullanici);
        yuklenenVeriler.add('kullanicilar');
        return true;
    }
    async function ayrilanPersonelKullaniciHesabiniSil(personelId) {
        const tcNo = String(personelId || '').trim();
        if (!tcNo) return false;
        if (SUPABASE_MODE) {
            const { data, error } = await supabaseClient.functions.invoke('manage-user', {
                body: { action:'delete', username:tcNo, companyId:aktifSirketId() }
            });
            if (error) throw error;
            if (!data?.success) throw new Error(data?.message || 'Personel giriş hesabı silinemedi.');
        }
        kullanicilar = kullanicilar.filter(user => String(user.username) !== tcNo && String(user.tcNo) !== tcNo);
        yuklenenVeriler.add('kullanicilar');
        return true;
    }

    let cikisUyariCozumle = null;

    function cikisUyariyiGoster(uyarilar) {
        const alan = document.getElementById('cikisUyariIcerik');
        alan.innerHTML = uyarilar.map(uyari => `<div class="cikis-uyari-kart"><strong>${uyari.baslik}</strong><span>${uyari.aciklama}</span></div>`).join('');
        document.getElementById('modalCikisUyari').style.display = 'flex';
        return new Promise(resolve => { cikisUyariCozumle = resolve; });
    }

    function cikisUyariyiKapat(onaylandi) {
        document.getElementById('modalCikisUyari').style.display = 'none';
        if (cikisUyariCozumle) cikisUyariCozumle(onaylandi);
        cikisUyariCozumle = null;
    }

    function cikisIcinKalanAvansTutariniBul(avans, cikisTarihi) {
        const durum = String(avans.durum || 'Aktif').toLocaleLowerCase('tr-TR');
        if (durum === 'kapandı' || durum === 'kapandi') return 0;
        const baslangic = String(avans.baslangicAy || '').slice(0, 7);
        const cikisAy = String(cikisTarihi || '').slice(0, 7);
        if (!baslangic || !cikisAy) return Number(avans.tutar || 0);
        const [basYil, basAy] = baslangic.split('-').map(Number);
        const [cikisYil, cikisAyNo] = cikisAy.split('-').map(Number);
        const gecenAy = (cikisYil - basYil) * 12 + (cikisAyNo - basAy);
        const taksit = Math.max(1, Number(avans.taksitSayisi || 1));
        if (gecenAy >= taksit) return 0;
        const tamamlananTaksit = Math.max(0, gecenAy);
        return Math.max(0, Number(avans.tutar || 0) * (taksit - tamamlananTaksit) / taksit);
    }

    const PERSONEL_TOPLU_AKTAR_BASLIKLARI = [
        'T.C. Kimlik No', 'Ad Soyad', 'SGK Sicil No', 'Adres', 'Telefon', 'Cinsiyet',
        'Şube', 'Görev', 'İşe Giriş Tarihi', 'Doğum Tarihi', 'Ücret (TL)',
        'Banka Adı', 'IBAN', 'Askerlik Durumu', 'Terhis Tarihi', 'Tecil Bitiş Tarihi',
        'Eğitim Seviyesi', 'Mezuniyet Yılı'
    ];
    let personelTopluAktarSatirlari = [];

    function personelExcelSablonuIndir() {
        if (typeof XLSX === 'undefined') {
            alert('Excel aracı yüklenemedi. İnternet bağlantısını kontrol edip sayfayı yenileyin.');
            return;
        }
        const ornekSube = subeler.find(s => aktifSirketeAit(s) && String(s.durum || 'Aktif') !== 'Pasif')?.ad
            || personeller.find(p => aktifSirketeAit(p) && p.sube)?.sube || 'MERKEZ';
        const veri = [
            PERSONEL_TOPLU_AKTAR_BASLIKLARI,
            [
                '12345678901', 'AHMET YILMAZ', '1234567890', 'ÖRNEK MAHALLESİ NO:1 BURDUR',
                '0 532 123 45 67', 'ERKEK', String(ornekSube).toLocaleUpperCase('tr-TR'), 'MUHASEBE ELEMANI',
                new Date(2026, 0, 2), new Date(1995, 4, 15), 1500, 'ZİRAAT BANKASI',
                'TR120001000000001234567890', 'YAPILDI', new Date(2015, 5, 1), '',
                'LİSANS', 2018
            ]
        ];
        const ws = XLSX.utils.aoa_to_sheet(veri);
        ws['!cols'] = [
            { wch:18 }, { wch:26 }, { wch:18 }, { wch:38 }, { wch:17 }, { wch:13 },
            { wch:24 }, { wch:25 }, { wch:18 }, { wch:18 }, { wch:16 }, { wch:22 },
            { wch:30 }, { wch:18 }, { wch:16 }, { wch:18 }, { wch:18 }, { wch:18 }
        ];
        ws['!autofilter'] = { ref:'A1:R2' };
        ws['A2'].t = 's';
        ws['A2'].z = '@';
        ws['C2'].t = 's';
        ws['E2'].t = 's';
        ws['I2'].z = 'dd.mm.yyyy';
        ws['J2'].z = 'dd.mm.yyyy';
        ws['K2'].z = '#,##0.00';
        ws['M2'].t = 's';
        ws['O2'].z = 'dd.mm.yyyy';
        ws['P2'].z = 'dd.mm.yyyy';
        ws['R2'].t = 'n';
        ws['R2'].z = '0';
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, 'Personeller');
        const aktifSubeler = [...new Set(subeler.filter(s => aktifSirketeAit(s) && String(s.durum || 'Aktif') !== 'Pasif').map(s => String(s.ad || '').trim()).filter(Boolean))];
        const bilgi = [
            ['PERSONEL TOPLU AKTARIM AÇIKLAMASI'],
            ['1', 'Personeller sayfasındaki örnek satırı silip kendi personellerinizi alt alta yazın.'],
            ['2', 'Sütun adlarını değiştirmeyin ve yeni sütun eklemeyin.'],
            ['3', 'T.C. Kimlik No 11 haneli olmalı; Excel bu alanı metin olarak tutmalıdır.'],
            ['4', 'Tarihleri gg.aa.yyyy biçiminde; Mezuniyet Yılını yalnızca 4 haneli yıl olarak yazın.'],
            ['5', 'Şube adını aşağıdaki kayıtlı şubelerden biriyle aynı yazın.'],
            ['6', 'Cinsiyet alanına KADIN veya ERKEK yazın.'],
            ['7', 'Askerlik Durumu: YAPILDI, TECİLLİ veya MUAF. YAPILDI için Terhis Tarihi; TECİLLİ için Tecil Bitiş Tarihi zorunludur.'],
            ['8', 'Eğitim Seviyesi: İLKOKUL, ORTAOKUL, LİSE, ÖN LİSANS, LİSANS, YÜKSEK LİSANS veya DOKTORA.'],
            [],
            ['KAYITLI ŞUBELER'],
            ...(aktifSubeler.length ? aktifSubeler.map(ad => [ad]) : [['Henüz kayıtlı aktif şube bulunmuyor.']])
        ];
        const bilgiWs = XLSX.utils.aoa_to_sheet(bilgi);
        bilgiWs['!cols'] = [{ wch:18 }, { wch:90 }];
        XLSX.utils.book_append_sheet(wb, bilgiWs, 'Açıklama');
        XLSX.writeFile(wb, 'PERSONEL_TOPLU_AKTARIM_SABLONU.xlsx');
    }

    function personelExcelDosyasiSec() {
        if (!isManagerUser()) {
            alert('Toplu personel aktarımını yalnızca Admin veya Yönetici yapabilir.');
            return;
        }
        const input = document.getElementById('personelTopluExcelInput');
        input.value = '';
        input.click();
    }

    function personelExcelBasliginiNormallestir(deger) {
        return String(deger || '').trim().toLocaleLowerCase('tr-TR')
            .replace(/[çÇ]/g, 'c').replace(/[ğĞ]/g, 'g').replace(/[ıİ]/g, 'i')
            .replace(/[öÖ]/g, 'o').replace(/[şŞ]/g, 's').replace(/[üÜ]/g, 'u')
            .replace(/[^a-z0-9]/g, '');
    }

    function personelExcelTarihiniCoz(deger) {
        if (!deger) return '';
        if (deger instanceof Date && !Number.isNaN(deger.getTime())) {
            return `${deger.getFullYear()}-${String(deger.getMonth() + 1).padStart(2, '0')}-${String(deger.getDate()).padStart(2, '0')}`;
        }
        if (typeof deger === 'number' && XLSX?.SSF?.parse_date_code) {
            const tarih = XLSX.SSF.parse_date_code(deger);
            if (tarih) return `${tarih.y}-${String(tarih.m).padStart(2, '0')}-${String(tarih.d).padStart(2, '0')}`;
        }
        const metin = String(deger).trim();
        let eslesme = metin.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/);
        if (eslesme) return `${eslesme[1]}-${String(eslesme[2]).padStart(2, '0')}-${String(eslesme[3]).padStart(2, '0')}`;
        eslesme = metin.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$/);
        if (eslesme) return `${eslesme[3]}-${String(eslesme[2]).padStart(2, '0')}-${String(eslesme[1]).padStart(2, '0')}`;
        return '';
    }

    function mezuniyetYiliniDuzelt(deger) {
        if (deger instanceof Date && !Number.isNaN(deger.getTime())) return String(deger.getFullYear());
        const metin = String(deger ?? '').trim();
        const eslesme = metin.match(/(?:^|\D)((?:19|20)\d{2})(?:\D|$)/);
        const yil = Number(eslesme?.[1] || (/^\d{4}$/.test(metin) ? metin : 0));
        return Number.isInteger(yil) && yil >= 1900 && yil <= new Date().getFullYear() ? String(yil) : '';
    }

    function personelExcelYiliniCoz(deger) {
        if (deger instanceof Date && !Number.isNaN(deger.getTime())) return mezuniyetYiliniDuzelt(deger);
        if (typeof deger === 'number' && deger >= 1900 && deger <= new Date().getFullYear()) return String(Math.trunc(deger));
        if (typeof deger === 'number' && XLSX?.SSF?.parse_date_code) {
            const tarih = XLSX.SSF.parse_date_code(deger);
            if (tarih?.y) return mezuniyetYiliniDuzelt(tarih.y);
        }
        return mezuniyetYiliniDuzelt(deger);
    }
    function personelExcelHucreDegeri(satir, baslikHaritasi, adlar) {
        const anahtar = adlar.map(personelExcelBasliginiNormallestir).find(ad => baslikHaritasi.has(ad));
        return anahtar ? satir[baslikHaritasi.get(anahtar)] : '';
    }

    async function personelExcelDosyasiniOku(input) {
        const dosya = input.files?.[0];
        if (!dosya) return;
        try {
            const veri = await dosya.arrayBuffer();
            const wb = XLSX.read(veri, { type:'array', cellDates:true });
            const ws = wb.Sheets['Personeller'] || wb.Sheets[wb.SheetNames[0]];
            const satirlar = XLSX.utils.sheet_to_json(ws, { header:1, raw:true, defval:'' });
            if (satirlar.length < 2) throw new Error('Excel dosyasında aktarılacak personel satırı bulunamadı.');
            const baslikHaritasi = new Map(satirlar[0].map((baslik, index) => [personelExcelBasliginiNormallestir(baslik), index]));
            const eksikBasliklar = PERSONEL_TOPLU_AKTAR_BASLIKLARI.filter(b => !baslikHaritasi.has(personelExcelBasliginiNormallestir(b)));
            if (eksikBasliklar.length) throw new Error(`Şablonda şu sütunlar bulunamadı: ${eksikBasliklar.join(', ')}`);
            const hamKayitlar = satirlar.slice(1).map((satir, index) => {
                const tcNo = String(personelExcelHucreDegeri(satir, baslikHaritasi, ['T.C. Kimlik No', 'TC Kimlik No', 'TC No'])).replace(/\D/g, '');
                return {
                    excelSatiri:index + 2,
                    id:tcNo,
                    ad:String(personelExcelHucreDegeri(satir, baslikHaritasi, ['Ad Soyad', 'Adı Soyadı'])).trim().toLocaleUpperCase('tr-TR'),
                    sgkNo:String(personelExcelHucreDegeri(satir, baslikHaritasi, ['SGK Sicil No', 'SGK No'])).trim(),
                    adres:String(personelExcelHucreDegeri(satir, baslikHaritasi, ['Adres'])).trim().toLocaleUpperCase('tr-TR'),
                    telefon:String(personelExcelHucreDegeri(satir, baslikHaritasi, ['Telefon', 'Telefon Numarası'])).trim(),
                    cinsiyet:String(personelExcelHucreDegeri(satir, baslikHaritasi, ['Cinsiyet'])).trim().toLocaleUpperCase('tr-TR'),
                    sube:String(personelExcelHucreDegeri(satir, baslikHaritasi, ['Şube'])).trim().toLocaleUpperCase('tr-TR'),
                    gorev:String(personelExcelHucreDegeri(satir, baslikHaritasi, ['Görev', 'Görevi'])).trim().toLocaleUpperCase('tr-TR'),
                    girisTarihi:personelExcelTarihiniCoz(personelExcelHucreDegeri(satir, baslikHaritasi, ['İşe Giriş Tarihi'])),
                    dogumTarihi:personelExcelTarihiniCoz(personelExcelHucreDegeri(satir, baslikHaritasi, ['Doğum Tarihi'])),
                    ucret:paraMetniniSayiyaCevir(personelExcelHucreDegeri(satir, baslikHaritasi, ['Ücret (TL)', 'Ücret', 'Ücret Tutarı'])),
                    bankaAdi:String(personelExcelHucreDegeri(satir, baslikHaritasi, ['Banka Adı', 'Banka'])).trim().toLocaleUpperCase('tr-TR'),
                    iban:String(personelExcelHucreDegeri(satir, baslikHaritasi, ['IBAN'])).replace(/\s/g, '').toLocaleUpperCase('tr-TR'),
                    askerlikDurumu:String(personelExcelHucreDegeri(satir, baslikHaritasi, ['Askerlik Durumu'])).trim().toLocaleUpperCase('tr-TR'),
                    terhisTarihi:personelExcelTarihiniCoz(personelExcelHucreDegeri(satir, baslikHaritasi, ['Terhis Tarihi'])),
                    tecilBitis:personelExcelTarihiniCoz(personelExcelHucreDegeri(satir, baslikHaritasi, ['Tecil Bitiş Tarihi', 'Tecil Bitişi'])),
                    egitimSeviyesi:String(personelExcelHucreDegeri(satir, baslikHaritasi, ['Eğitim Seviyesi'])).trim().toLocaleUpperCase('tr-TR'),
                    mezuniyetYili:personelExcelYiliniCoz(personelExcelHucreDegeri(satir, baslikHaritasi, ['Mezuniyet Yılı', 'Mezuniyet Yili', 'Mezuniyet Tarihi']))
                };
            }).filter(k => k.id || k.ad || k.sgkNo || k.adres || k.telefon || k.sube || k.gorev || k.girisTarihi || k.dogumTarihi || k.ucret);
            if (!hamKayitlar.length) throw new Error('Excel dosyasında dolu personel satırı bulunamadı.');
            const tcSayilari = hamKayitlar.reduce((harita, k) => harita.set(k.id, (harita.get(k.id) || 0) + 1), new Map());
            const mevcutTc = new Set(personeller.filter(aktifSirketeAit).map(p => String(p.id)));
            const subeHaritasi = new Map();
            subeler.filter(s => aktifSirketeAit(s) && String(s.durum || 'Aktif') !== 'Pasif').forEach(s => subeHaritasi.set(String(s.ad || '').trim().toLocaleUpperCase('tr-TR'), String(s.ad || '').trim()));
            personeller.filter(aktifSirketeAit).forEach(p => { if (p.sube) subeHaritasi.set(String(p.sube).trim().toLocaleUpperCase('tr-TR'), String(p.sube).trim()); });
            personelTopluAktarSatirlari = hamKayitlar.map(k => {
                const hatalar = [];
                if (!/^\d{11}$/.test(k.id)) hatalar.push('T.C. No 11 haneli değil');
                if (!k.ad) hatalar.push('Ad Soyad boş');
                if (!k.sgkNo) hatalar.push('SGK Sicil No boş');
                if (!k.adres) hatalar.push('Adres boş');
                if (!k.telefon) hatalar.push('Telefon boş');
                if (!['KADIN', 'ERKEK'].includes(k.cinsiyet)) hatalar.push('Cinsiyet KADIN veya ERKEK olmalı');
                if (!k.sube) hatalar.push('Şube boş');
                else if (!subeHaritasi.has(k.sube)) hatalar.push('Şube sistemde kayıtlı değil');
                if (!k.gorev) hatalar.push('Görev boş');
                if (!k.girisTarihi) hatalar.push('İşe giriş tarihi geçersiz');
                if (!k.dogumTarihi) hatalar.push('Doğum tarihi geçersiz');
                if (!(Number(k.ucret) > 0)) hatalar.push('Ücret boş veya geçersiz');
                if (!k.bankaAdi) hatalar.push('Banka adı boş');
                if (!/^TR\d{24}$/.test(k.iban)) hatalar.push('IBAN TR ile başlayan 26 karakter olmalı');
                if (!['YAPILDI', 'TECİLLİ', 'TECILLI', 'MUAF'].includes(k.askerlikDurumu)) hatalar.push('Askerlik durumu geçersiz');
                if (k.askerlikDurumu === 'YAPILDI' && !k.terhisTarihi) hatalar.push('Terhis tarihi gerekli');
                if (['TECİLLİ', 'TECILLI'].includes(k.askerlikDurumu) && !k.tecilBitis) hatalar.push('Tecil bitiş tarihi gerekli');
                if (!['İLKOKUL', 'ILKOKUL', 'ORTAOKUL', 'LİSE', 'LISE', 'ÖN LİSANS', 'ON LISANS', 'LİSANS', 'LISANS', 'YÜKSEK LİSANS', 'YUKSEK LISANS', 'DOKTORA'].includes(k.egitimSeviyesi)) hatalar.push('Eğitim seviyesi geçersiz');
                if (!k.mezuniyetYili) hatalar.push('Mezuniyet yılı 1900 ile günümüz arasında 4 haneli olmalı');
                if (k.id && tcSayilari.get(k.id) > 1) hatalar.push('Excel içinde T.C. tekrarlı');
                if (mevcutTc.has(k.id)) hatalar.push('Bu T.C. sistemde zaten kayıtlı');
                return { ...k, sube:subeHaritasi.get(k.sube) || k.sube, hatalar, gecerli:hatalar.length === 0 };
            });
            personelTopluAktarOnizlemesiniGoster();
        } catch (error) {
            alert('Excel okunamadı: ' + (error.message || 'Bilinmeyen hata'));
        } finally {
            input.value = '';
        }
    }

    function personelTopluAktarOnizlemesiniGoster() {
        const gecerli = personelTopluAktarSatirlari.filter(k => k.gecerli).length;
        const hatali = personelTopluAktarSatirlari.length - gecerli;
        document.getElementById('personelTopluAktarOzet').innerHTML = `<div style="display:flex;gap:10px;flex-wrap:wrap;"><span class="badge" style="background:#dcfce7;color:#166534;">${gecerli} geçerli kayıt</span><span class="badge" style="background:#fee2e2;color:#991b1b;">${hatali} hatalı kayıt</span></div><p style="margin:10px 0 0;color:#64748b;">Hatalı satırlar kaydedilmez. Kırmızı satırları Excel'de düzeltip dosyayı yeniden yükleyebilirsiniz.</p>`;
        document.getElementById('personelTopluAktarBody').innerHTML = personelTopluAktarSatirlari.map(k => `<tr style="${k.gecerli ? '' : 'background:#fff1f2;'}"><td>${k.excelSatiri}</td><td>${escapeDashboardText(k.id || '-')}</td><td>${escapeDashboardText(k.ad || '-')}</td><td>${escapeDashboardText(k.sube || '-')}</td><td>${escapeDashboardText(k.gorev || '-')}</td><td>${Number(k.ucret) > 0 ? paraFormatla(k.ucret) : '-'}</td><td>${k.gecerli ? '<span style="color:#047857;font-weight:800;">✓ Hazır</span>' : `<span style="color:#b91c1c;font-weight:750;">${escapeDashboardText(k.hatalar.join(' · '))}</span>`}</td></tr>`).join('');
        const buton = document.getElementById('btnPersonelTopluAktarOnay');
        buton.disabled = !gecerli;
        buton.textContent = gecerli ? `${gecerli} Personeli Kaydet` : 'Kaydedilecek Geçerli Kayıt Yok';
        document.getElementById('modalPersonelTopluAktar').style.display = 'flex';
    }

    function personelTopluAktarModaliniKapat() {
        document.getElementById('modalPersonelTopluAktar').style.display = 'none';
        personelTopluAktarSatirlari = [];
    }

    async function personelTopluAktarimiKaydet() {
        const kayitlar = personelTopluAktarSatirlari.filter(k => k.gecerli);
        if (!kayitlar.length || !await fdYuzerOnaySor(`${kayitlar.length} personel ve bunlara ait giriş hesapları kaydedilecek. Devam edilsin mi?`)) return;
        const yeniPersoneller = kayitlar.map(k => ({
            id:String(k.id), sirketId:aktifSirketId(), ad:k.ad, sube:k.sube, gorev:k.gorev,
            girisTarihi:k.girisTarihi, dogumTarihi:k.dogumTarihi, cikisTarihi:null,
            engelli:'Hayır', emekli:'Hayır', cocukSayisi:'0', primVar:'Hayır',
            sgkNo:k.sgkNo, adres:k.adres, telefon:k.telefon,
            cinsiyet:k.cinsiyet === 'KADIN' ? 'Kadın' : 'Erkek',
            bankaAdi:k.bankaAdi, iban:k.iban,
            askerlikDurumu:k.askerlikDurumu === 'YAPILDI' ? 'Yapıldı' : (k.askerlikDurumu === 'MUAF' ? 'Muaf' : 'Tecilli'),
            terhisTarihi:k.terhisTarihi || '', tecilBitis:k.tecilBitis || '',
            egitimSeviyesi:({
                'İLKOKUL':'İlkokul', 'ILKOKUL':'İlkokul', 'ORTAOKUL':'Ortaokul', 'LİSE':'Lise', 'LISE':'Lise', 'ÖN LİSANS':'Ön Lisans', 'ON LISANS':'Ön Lisans',
                'LİSANS':'Lisans', 'LISANS':'Lisans', 'YÜKSEK LİSANS':'Yüksek Lisans',
                'YUKSEK LISANS':'Yüksek Lisans', 'DOKTORA':'Doktora'
            })[k.egitimSeviyesi] || k.egitimSeviyesi,
            mezuniyetYili:k.mezuniyetYili,
            ucret:Number(k.ucret).toLocaleString('tr-TR', { minimumFractionDigits:0, maximumFractionDigits:2 })
        }));
        showGlobalOverlay('Personeller topluca kaydediliyor', `${yeniPersoneller.length} kayıt ve giriş hesabı hazırlanıyor...`);
        const eklenenTcNoListesi = yeniPersoneller.map(p => p.id);
        const hesapHatalari = [];
        const hesapOlusturulanIdler = new Set();
        try {
            personeller.push(...yeniPersoneller);
            for (let i = 0; i < yeniPersoneller.length; i += 4) {
                const grup = yeniPersoneller.slice(i, i + 4);
                const sonuclar = await Promise.allSettled(grup.map(p => personelKullaniciHesabiOlustur(p)));
                sonuclar.forEach((sonuc, index) => {
                    if (sonuc.status === 'rejected') hesapHatalari.push(`${grup[index].ad}: ${sonuc.reason?.message || 'hesap oluşturulamadı'}`);
                    else if (sonuc.value) hesapOlusturulanIdler.add(String(grup[index].id));
                });
            }
            await verileriKaydet();
            const bildirimSonucu = await personelBildirimleriniTopluGonder(yeniPersoneller.filter(p => hesapOlusturulanIdler.has(String(p.id))).map(personelIseGirisBildirimiHazirla));
            if (bildirimSonucu.basarisiz) hesapHatalari.push(`${bildirimSonucu.basarisiz} personele işe giriş WhatsApp bildirimi gönderilemedi.`);
            personelTopluAktarModaliniKapat();
            initUI();
            alert(`${yeniPersoneller.length} personel başarıyla kaydedildi.${hesapHatalari.length ? `\n\n${hesapHatalari.length} giriş hesabı oluşturulamadı; personel kayıtları kaydedildi:\n${hesapHatalari.join('\n')}` : `\n\nKullanıcı adları T.C. numarası, ilk şifreleri T.C. numarasının ilk 6 hanesidir.`}`);
        } catch (error) {
            personeller = personeller.filter(p => !eklenenTcNoListesi.includes(String(p.id)));
            alert('Toplu personel kaydı tamamlanamadı: ' + (error.message || 'Bilinmeyen hata'));
        } finally {
            hideGlobalOverlay();
        }
    }

    document.getElementById('personelForm').addEventListener('submit', async (e) => {
        e.preventDefault();
        const origId = document.getElementById('pEditOriginalId').value;
        const tcNo = document.getElementById('pTcNo').value.trim();
        const yeniCikisTarihi = document.getElementById('pCikisTarihi').value;

        if (tcNo.length !== 11 || isNaN(tcNo)) { alert("Geçerli 11 haneli T.C. giriniz."); return; }
        const cihazPersonelNo = magicpassCihazNoAnahtari(document.getElementById('pCihazPersonelNo').value);
        document.getElementById('pCihazPersonelNo').value = cihazPersonelNo;
        if (cihazPersonelNo && personeller.some(p => magicpassCihazNoAnahtari(p.cihazPersonelNo) === cihazPersonelNo && String(p.id) !== String(origId))) { alert('Bu cihaz personel numaras? ba?ka bir personele tan?ml?.'); return; }

        const mevcutPersonel = personeller.find(p => String(p.id) === String(origId) && aktifSirketeAit(p));
        if (origId && !mevcutPersonel) { alert('Düzenlenecek personel bu şirkette bulunamadı.'); return; }
        const cikisTarihiYeniEklendi = yeniCikisTarihi && origId && String(mevcutPersonel?.cikisTarihi || '') !== String(yeniCikisTarihi);
        const kullaniciHesabiKapatilacak = Boolean(yeniCikisTarihi && origId && !String(mevcutPersonel?.cikisTarihi || '').trim());
        if (cikisTarihiYeniEklendi) {
            const pTemp = {
                id: String(tcNo),
                girisTarihi: document.getElementById('pGirisTarihi').value,
                dogumTarihi: document.getElementById('pDogumTarihi').value,
                cikisTarihi: yeniCikisTarihi
            };
            const donemler = personelDonemleriniGetir(pTemp);
            let toplamKalan = 0;
            donemler.forEach(d => {
                let kullanilan = izinler.filter(i => String(i.pId) === String(tcNo) && i.donem === d.donem && i.tur === 'Yıllık İzin').reduce((s, x) => s + x.gun, 0);
                let kalan = d.hak - kullanilan;
                if (kalan > 0) toplamKalan += kalan;
            });

            const personelIdleri = [String(tcNo), String(origId)];
            const acikIcralar = icralar.filter(icra =>
                personelIdleri.includes(String(icra.pId)) &&
                (!icra.sirketId || String(icra.sirketId) === String(aktifSirketId() || mevcutPersonel?.sirketId || '')) &&
                icraKalanBorc(icra) > 0
            );
            const devamEdenAvanslar = avanslar.map(avans => ({ avans, kalan: cikisIcinKalanAvansTutariniBul(avans, yeniCikisTarihi) }))
                .filter(({ avans, kalan }) => personelIdleri.includes(String(avans.pId)) && (!avans.sirketId || String(avans.sirketId) === String(aktifSirketId() || mevcutPersonel?.sirketId || '')) && kalan > 0);
            const kalanEkOdemeler = ekOdemeler.filter(kayit =>
                personelIdleri.includes(String(kayit.pId)) &&
                (!kayit.sirketId || String(kayit.sirketId) === String(aktifSirketId() || mevcutPersonel?.sirketId || '')) &&
                paraMetniniSayiyaCevir(kayit.kalanTutar) > 0
            );
            const uyarilar = [];
            if (acikIcralar.length) uyarilar.push({ baslik: `Açık icra kaydı (${acikIcralar.length})`, aciklama: acikIcralar.map(icra => `${escapeDashboardText(icra.dosyaNo || 'Dosya no yok')} · Kalan borç: ${paraFormatla(icraKalanBorc(icra))}`).join('<br>') });
            if (devamEdenAvanslar.length) uyarilar.push({ baslik: `Devam eden avans kesintisi (${devamEdenAvanslar.length})`, aciklama: devamEdenAvanslar.map(({ avans, kalan }) => `${escapeDashboardText(avans.avansNo || 'Avans')} · Planlanan kalan: ${paraFormatla(kalan)}`).join('<br>') });
            if (kalanEkOdemeler.length) uyarilar.push({ baslik: `Ödenmemiş ek ödeme / yol ücreti (${kalanEkOdemeler.length})`, aciklama: kalanEkOdemeler.map(kayit => `${escapeDashboardText(String(kayit.ay || 'Ay bilgisi yok'))} · ${escapeDashboardText(kayit.ekOdemeTuru || 'Ek ödeme')} · Kalan: ${paraFormatla(paraMetniniSayiyaCevir(kayit.kalanTutar))}`).join('<br>') });
            if (toplamKalan > 0) uyarilar.push({ baslik: 'Kullanılmamış yıllık izin', aciklama: `Bu personelin toplam <strong>${toplamKalan} gün</strong> kullanılmamış yıllık izin hakkı bulunuyor.` });
            if (uyarilar.length && !(await cikisUyariyiGoster(uyarilar))) return;
        }

        const mezuniyetYiliGirdisi = document.getElementById('pMezuniyetYili').value.trim();
        const mezuniyetYili = mezuniyetYiliniDuzelt(mezuniyetYiliGirdisi);
        if (mezuniyetYiliGirdisi && !mezuniyetYili) {
            alert('Mezuniyet yılı 1900 ile ' + new Date().getFullYear() + ' arasında olmalıdır.');
            return;
        }

        if (!origId && personeller.some(p => String(p.id) === String(tcNo))) { alert("Bu T.C. numarasına sahip personel zaten var!"); return; }

        const fotoDosyasi = document.getElementById('pFotoDosya')?.files?.[0] || null;
        const eskiFotograf = mevcutPersonel?.fotografDosya || null;
        let yeniFotograf = null;
        if (fotoDosyasi) {
            if (!['image/jpeg','image/png','image/webp'].includes(String(fotoDosyasi.type || '').toLowerCase())) {
                alert('Personel fotoğrafı JPG, PNG veya WEBP biçiminde olmalıdır.');
                return;
            }
            if (fotoDosyasi.size > 8 * 1024 * 1024) {
                alert('Personel fotoğrafı en fazla 8 MB olabilir.');
                return;
            }
            showGlobalOverlay('Personel fotoğrafı yükleniyor', 'Fotoğraf Drive klasörüne kaydediliyor...');
            try {
                const uzanti = (fotoDosyasi.name.split('.').pop() || 'jpg').replace(/[^a-z0-9]/gi, '').toLowerCase() || 'jpg';
                const fotoAdi = `PERSONEL_${tcNo}_${Date.now()}.${uzanti}`;
                const yuklenen = await fdYazilimDriveDosyaYukle(await dosyayiBase64Oku(fotoDosyasi), fotoAdi, fotoDosyasi.type, '', 'PERSONEL FOTOĞRAFLARI');
                yeniFotograf = { id:yuklenen.id, url:yuklenen.url || '', ad:yuklenen.ad || fotoAdi, mimeType:fotoDosyasi.type, boyut:fotoDosyasi.size };
            } catch (hata) {
                hideGlobalOverlay();
                alert('Personel fotoğrafı yüklenemedi: ' + (hata.message || 'Bilinmeyen hata'));
                return;
            }
        }
        const kullanilanFotograf = yeniFotograf || eskiFotograf || null;
        const pObj = {
            ...(mevcutPersonel || {}),
            whatsappMesajTercihleri: window.fdPersonelWhatsappTercihleri?.read(mevcutPersonel) ?? mevcutPersonel?.whatsappMesajTercihleri ?? {},
            cihazPersonelNo,
            id: String(tcNo),
            sirketId: aktifSirketId() || mevcutPersonel?.sirketId || '',
            ad: document.getElementById('pAd').value,
            sube: document.getElementById('pSube').value,
            gorev: document.getElementById('pGorev').value,
            telefon: document.getElementById('pTelefon').value,
            kanGrubu: document.getElementById('pKanGrubu').value,
            cinsiyet: document.getElementById('pCinsiyet').value,
            engelli: document.getElementById('pEngelli').value,
            emekli: document.getElementById('pEmekli').value,
            belgeler: document.getElementById('pBelgeler').value,
            aciklama: document.getElementById('pAciklama').value,
            girisTarihi: document.getElementById('pGirisTarihi').value,
            dogumTarihi: document.getElementById('pDogumTarihi').value,
            cikisTarihi: yeniCikisTarihi || null,
            kimlikSeriNo: document.getElementById('pKimlikSeri').value,
            fotografDosya: kullanilanFotograf,
            fotografUrl: personelFotografAdresi({ fotografDosya:kullanilanFotograf, fotografUrl:mevcutPersonel?.fotografUrl || '' }),
            adres: document.getElementById('pAdres').value,
            kurumsalTelefon: document.getElementById('pKurumsalTelefon').value,
            eposta: document.getElementById('pEposta').value,
            acilDurumAd: document.getElementById('pAcilDurumAd').value,
            acilDurumYakinlik: document.getElementById('pAcilDurumYakinlik').value,
            acilDurumTelefon: document.getElementById('pAcilDurumTelefon').value,
            medeniDurum: document.getElementById('pMedeniDurum').value,
            cocukSayisi: document.getElementById('pCocukSayisi').value,
            askerlikDurumu: document.getElementById('pAskerlikDurumu').value,
            tecilBitis: document.getElementById('pTecilBitis').value,
            terhisTarihi: document.getElementById('pTerhisTarihi').value,
            bankaAdi: document.getElementById('pBankaAdi').value,
            iban: document.getElementById('pIban').value,
            sgkNo: document.getElementById('pSgkNo').value,
            emeklilikTuru: document.getElementById('pEmeklilikTuru').value,
            vergiMuafiyet: document.getElementById('pVergiMuafiyet').value,
            departman: document.getElementById('pDepartman').value,
            kadro: document.getElementById('pKadro').value,
            yonetici: document.getElementById('pYonetici').value,
            egitimSeviyesi: document.getElementById('pEgitimSeviyesi').value,
            okulBolum: document.getElementById('pOkulBolum').value,
            sertifikalar: document.getElementById('pSertifikalar').value,
            sertifikaBitis: document.getElementById('pSertifikaBitis').value,
            ehliyetDil: document.getElementById('pEhliyetDil').value,
            zimmetNotu: document.getElementById('pZimmetNotu').value,
            terfiGecmisi: document.getElementById('pTerfiGecmisi').value,
            performansNotu: document.getElementById('pPerformansNotu').value,
            sonSaglikTaramasi: document.getElementById('pSonSaglikTaramasi').value,
            isyeriHekimi: document.getElementById('pIsyeriHekimi').value,
            kronikRahatsizlik: document.getElementById('pKronikRahatsizlik').value,
            alerjiler: document.getElementById('pAlerjiler').value,
            saglikNotu: document.getElementById('pSaglikNotu').value,
            mezuniyetYili,
            ucretTipi: document.getElementById('pUcretTipi').value,
            ucret: document.getElementById('pUcret').value,
            ekOdemeTuru: document.getElementById('pEkOdemeTuru').value,
            ekOdemeTutari: document.getElementById('pEkOdemeTutari').value,
            yolUcreti: document.getElementById('pYolUcreti').value,
            ekOdemeUcretGecmisi: ekOdemeUcretGecmisiniHazirla(mevcutPersonel, {
                ekOdemeTuru:document.getElementById('pEkOdemeTuru').value,
                ekOdemeTutari:document.getElementById('pEkOdemeTutari').value,
                yolUcreti:document.getElementById('pYolUcreti').value,
                girisTarihi:document.getElementById('pGirisTarihi').value
            }),
            primVar: document.getElementById('pPrimVar').value
        };

        if (origId) {
            const idx = personeller.findIndex(p => String(p.id) === String(origId) && aktifSirketeAit(p));
            if (idx !== -1) personeller[idx] = pObj;
        } else {
            if (personeller.some(p => String(p.id) === String(tcNo))) { alert("Bu T.C. numarasına sahip personel zaten var!"); return; }
            personeller.push(pObj);
        }

        showGlobalOverlay('Personel kaydediliyor', 'Bilgiler ve giriş hesabı hazırlanıyor, lütfen bekleyin...');
        let personelHesabiOlustu = false;
        let personelKaydiBasarili = false;
        let kullaniciHesabiOlusturmaHatasi = null;
        let kullaniciHesabiSilmeHatasi = null;
        try {
            await verileriKaydet();
            if (!origId) {
                try { personelHesabiOlustu = await personelKullaniciHesabiOlustur(pObj); }
                catch (hesapHatasi) { kullaniciHesabiOlusturmaHatasi = hesapHatasi; }
            }
            if (kullaniciHesabiKapatilacak) {
                try { await ayrilanPersonelKullaniciHesabiniSil(origId); }
                catch (hesapHatasi) { kullaniciHesabiSilmeHatasi = hesapHatasi; }
            }
            if (yeniFotograf?.id && eskiFotograf?.id && String(yeniFotograf.id) !== String(eskiFotograf.id)) {
                try { await fdYazilimDriveDosyaSil(eskiFotograf.id, 'PERSONEL FOTOĞRAFLARI'); } catch (silmeHatasi) { console.warn('Eski personel fotoğrafı silinemedi:', silmeHatasi); }
            }
            initUI();
            closePersonelModal();
            personelKaydiBasarili = true;
        } catch (error) {
            if (!origId) personeller = personeller.filter(personel => String(personel.id) !== String(tcNo));
            else if (mevcutPersonel) {
                const eskiIndex = personeller.findIndex(personel => String(personel.id) === String(origId) && aktifSirketeAit(personel));
                if (eskiIndex !== -1) personeller[eskiIndex] = mevcutPersonel;
            }
            if (yeniFotograf?.id) {
                try { await fdYazilimDriveDosyaSil(yeniFotograf.id, 'PERSONEL FOTOĞRAFLARI'); } catch (silmeHatasi) { console.warn('Yarım kalan personel fotoğrafı temizlenemedi:', silmeHatasi); }
            }
            alert('Personel kaydı tamamlanamadı: ' + (error.message || 'Bilinmeyen hata'));
        } finally {
            hideGlobalOverlay();
        }
        if (personelKaydiBasarili && !origId) personelKayitHatirlatmasiniGoster(tcNo, personelHesabiOlustu);
        if (personelKaydiBasarili && !origId && personelHesabiOlustu) {
            const bildirimSonucu = await personelBildirimleriniTopluGonder([personelIseGirisBildirimiHazirla(pObj)]);
            if (bildirimSonucu.basarisiz) showToast('Personel ve giriş hesabı kaydedildi; işe giriş WhatsApp bildirimi gönderilemedi.', 'warning');
        }
        if (personelKaydiBasarili && cikisTarihiYeniEklendi) {
            const bildirimSonucu = await personelBildirimleriniTopluGonder([personelIstenAyrilisBildirimiHazirla(pObj)]);
            if (bildirimSonucu.basarisiz) showToast('İşten ayrılış kaydedildi; WhatsApp bildirimi gönderilemedi.', 'warning');
        }
        if (personelKaydiBasarili && kullaniciHesabiOlusturmaHatasi) showToast('Personel kaydı oluşturuldu; ancak giriş hesabı açılamadı: ' + (kullaniciHesabiOlusturmaHatasi.message || kullaniciHesabiOlusturmaHatasi), 'warning');
        if (personelKaydiBasarili && kullaniciHesabiSilmeHatasi) showToast('Personel çıkışı kaydedildi ancak giriş hesabı kapatılamadı: ' + (kullaniciHesabiSilmeHatasi.message || kullaniciHesabiSilmeHatasi), 'warning');
        else if (personelKaydiBasarili && kullaniciHesabiKapatilacak) showToast('Personel çıkışı kaydedildi ve kullanıcı giriş hesabı kapatıldı.');
    });

    function personelKayitHatirlatmasiniGoster(tcNo, hesapOlustu) {
        const hesapAlani = document.getElementById('personelKayitHesapBilgisi');
        if (hesapOlustu) {
            hesapAlani.style.display = 'block';
            hesapAlani.innerHTML = `<strong>Personel giriş hesabı oluşturuldu.</strong><br>Kullanıcı adı: ${escapeDashboardText(tcNo)} · İlk şifre: ${escapeDashboardText(tcNo.slice(0,6))}<br><small>Personel ilk girişinde şifresini değiştirmelidir.</small>`;
        } else {
            hesapAlani.style.display = 'none';
            hesapAlani.innerHTML = '';
        }
        document.getElementById('modalPersonelKayitHatirlatma').style.display = 'flex';
    }

    function personelKayitHatirlatmasiniKapat() {
        document.getElementById('modalPersonelKayitHatirlatma').style.display = 'none';
    }

    async function personelSil(id) {
        if (!isManagerUser()) {
            alert("⚠️ Yetkisiz İşlem: Personel kayıtlarını yalnızca Admin veya Yönetici silebilir!");
            return;
        }

        if (await fdYuzerOnaySor("Bu personel kaydını kalıcı olarak silmek istediğinize emin misiniz?")) {
            personeller = personeller.filter(p => String(p.id) !== String(id));
            await verileriKaydet();
            initUI();
        }
    }

    function getSubeBadgeStyle(subeStr) {
        if (!subeStr) return 'background-color: #64748b; color: #ffffff;';
        
        const s = subeStr.toLowerCase().trim();
        if (s.includes('fabrika')) return 'background-color: #8b5cf6; color: #ffffff;';
        if (s.includes('nakliye')) return 'background-color: #0284c7; color: #ffffff;';
        if (s.includes('merkez')) return 'background-color: #0f172a; color: #ffffff;';
        if (s.includes('şantiye') || s.includes('santiye')) return 'background-color: #d97706; color: #ffffff;';
        if (s.includes('atık') || s.includes('atik')) return 'background-color: #059669; color: #ffffff;';

        let hash = 0;
        for (let i = 0; i < subeStr.length; i++) {
            hash = subeStr.charCodeAt(i) + ((hash << 5) - hash);
        }
        const colors = [
            '#e11d48', '#4f46e5', '#0891b2', '#ca8a04', '#7c3aed', 
            '#db2777', '#16a34a', '#c2410c', '#0d9488', '#475569'
        ];
        let color = colors[Math.abs(hash) % colors.length];
        return `background-color: ${color}; color: #ffffff;`;
    }

    function filtreDropdownlariDoldur() {
        const aktifSubeSel = document.getElementById('fAktifSube');
        const ayrilanSubeSel = document.getElementById('fAyrilanSube');
        const aktifYilSel = document.getElementById('fAktifYil');
        const ayrilanYilSel = document.getElementById('fAyrilanCikisYili');
        const bakiyeSubeSel = document.getElementById('fBakiyeSube');
        const bakiyeDonemSel = document.getElementById('fBakiyeDonem');

        const subeler = [...new Set(personeller.map(p => p.sube).filter(Boolean))];
        const yillar = [...new Set(personeller.map(p => p.girisTarihi ? p.girisTarihi.split('-')[0] : null).filter(Boolean))].sort().reverse();
        const cikisYillari = [...new Set(personeller.map(p => p.cikisTarihi && p.cikisTarihi !== "null" ? p.cikisTarihi.split('-')[0] : null).filter(Boolean))].sort().reverse();

        let tumDonemler = new Set();
        personeller.filter(p => {
                const cikis = String(p.cikisTarihi ?? '').trim().toLocaleLowerCase('tr-TR');
                const aktif = !cikis || ['null','undefined','-','0000-00-00'].includes(cikis);
                return aktifSirketeAit(p) && aktif && (!isPersonelUser() || String(p.id) === String(activeUser.tcNo));
            }).forEach(p => {
            personelDonemleriniGetir(p).forEach(d => {
                const kullanilan = izinler.filter(i => String(i.pId) === String(p.id) && i.donem === d.donem && i.tur === 'Yıllık İzin').reduce((toplam, izin) => toplam + Number(izin.gun || 0), 0);
                if (Number(d.hak || 0) - kullanilan > 0) tumDonemler.add(d.donem);
            });
        });
        const donemlerDizisi = [...tumDonemler].sort().reverse();

        let sOpt = '<option value="">Tüm Şubeler</option>';
        subeler.forEach(s => sOpt += `<option value="${s}">${s}</option>`);
        aktifSubeSel.innerHTML = sOpt;
        ayrilanSubeSel.innerHTML = sOpt;
        bakiyeSubeSel.innerHTML = sOpt;

        let yOpt = '<option value="">Tüm Giriş Yılları</option>';
        yillar.forEach(y => yOpt += `<option value="${y}">${y}</option>`);
        aktifYilSel.innerHTML = yOpt;

        let cOpt = '<option value="">Tüm Ayrılış Yılları</option>';
        cikisYillari.forEach(y => cOpt += `<option value="${y}">${y}</option>`);
        ayrilanYilSel.innerHTML = cOpt;

        let dOpt = '<option value="">Tüm Hakediş Dönemleri</option>';
        donemlerDizisi.forEach(d => dOpt += `<option value="${d}">${d}</option>`);
        bakiyeDonemSel.innerHTML = dOpt;
    }

    function renderPersonelOzetleri() {
        const generalTarget = document.getElementById('personelGenelOzet');
        const branchTarget = document.getElementById('personelSubeOzet');
        if (!generalTarget || !branchTarget) return;

        const active = personeller.filter(p => aktifSirketeAit(p) && (!p.cikisTarihi || String(p.cikisTarihi) === 'null'));
        const genderCount = (people, gender) => people.filter(p => String(p.cinsiyet || '').trim().toLocaleLowerCase('tr-TR') === gender).length;
        const categoryPeople = (people, field) => people.filter(p => personelEvetMi(p[field]));
        const summarize = people => ({
            toplam: people.length,
            kadin: people.filter(p => String(p.cinsiyet || '').toLocaleLowerCase('tr-TR') === 'kadın').length,
            erkek: people.filter(p => String(p.cinsiyet || '').toLocaleLowerCase('tr-TR') === 'erkek').length,
            engelli: categoryPeople(people, 'engelli').length,
            emekli: categoryPeople(people, 'emekli').length,
            engelliErkek: genderCount(categoryPeople(people, 'engelli'), 'erkek'),
            engelliKadin: genderCount(categoryPeople(people, 'engelli'), 'kadın'),
            emekliErkek: genderCount(categoryPeople(people, 'emekli'), 'erkek'),
            emekliKadin: genderCount(categoryPeople(people, 'emekli'), 'kadın')
        });
        const metrics = summary => [
            ['Toplam', summary.toplam], ['Kadın', summary.kadin], ['Erkek', summary.erkek], ['Engelli', summary.engelli], ['Emekli', summary.emekli]
        ];
        const renderTargets = (people, generalEl, branchEl, emptyText) => {
            if (!generalEl || !branchEl) return;
            generalEl.innerHTML = metrics(summarize(people)).map(([label, value]) => `<article class="personel-summary-card"><span>${label}</span><strong>${value}</strong></article>`).join('');
            const branches = people.reduce((map, person) => {
                const branch = String(person.sube || 'Merkez').trim() || 'Merkez';
                (map[branch] ||= []).push(person);
                return map;
            }, {});
            const branchNames = Object.keys(branches).sort((a, b) => a.localeCompare(b, 'tr'));
            branchEl.innerHTML = branchNames.length ? branchNames.map(branch => {
                const summary = summarize(branches[branch]);
                return `<article class="branch-summary-card"><h4>${escapeDashboardText(branch)}</h4><div class="branch-summary-metrics">${metrics(summary).map(([label, value]) => {
                    const field = label === 'Engelli' ? 'engelli' : label === 'Emekli' ? 'emekli' : '';
                    const breakdown = field ? `<small class="branch-summary-gender">Erkek: ${summary[field + 'Erkek']}<br>Bayan: ${summary[field + 'Kadin']}</small>` : '';
                    return `<span><b>${value}</b>${breakdown}${label}</span>`;
                }).join('')}</div></article>`;
            }).join('') : `<div class="dashboard-empty">${emptyText}</div>`;
        };
        renderTargets(active, generalTarget, branchTarget, 'Kayıtlı aktif personel bulunmuyor.');
        const departed = personeller.filter(p => aktifSirketeAit(p) && p.cikisTarihi && String(p.cikisTarihi) !== 'null');
        renderTargets(departed, document.getElementById('ayrilanGenelOzet'), document.getElementById('ayrilanSubeOzet'), 'Kayıtlı ayrılan personel bulunmuyor.');
    }

    function personelEvetMi(deger) {
        return deger === true || String(deger || '').trim().toLocaleLowerCase('tr-TR') === 'evet';
    }

    function personelDurumFiltresineUyar(personel, alan, filtre) {
        if (!filtre) return true;
        return personelEvetMi(personel?.[alan]) === (filtre === 'evet');
    }

    function filtrelenmisAktifPersonelleriGetir() {
        const arama = String(document.getElementById('fAktifArama')?.value || '').trim().toLocaleLowerCase('tr-TR');
        const sube = document.getElementById('fAktifSube')?.value || '';
        const yil = document.getElementById('fAktifYil')?.value || '';
        const engelli = document.getElementById('fAktifEngelli')?.value || '';
        const emekli = document.getElementById('fAktifEmekli')?.value || '';
        const siralama = document.getElementById('fAktifSiralama')?.value || 'sube-asc';

        const liste = personeller.filter(personel => {
            if (!aktifSirketeAit(personel)) return false;
            if (personel.cikisTarihi && String(personel.cikisTarihi) !== 'null') return false;
            if (isPersonelUser() && String(personel.id) !== String(activeUser.tcNo)) return false;
            const ad = String(personel.ad || '').toLocaleLowerCase('tr-TR');
            if (arama && !ad.includes(arama) && !String(personel.id || '').includes(arama)) return false;
            if (sube && personel.sube !== sube) return false;
            if (yil && !String(personel.girisTarihi || '').startsWith(yil)) return false;
            if (!personelDurumFiltresineUyar(personel, 'engelli', engelli)) return false;
            if (!personelDurumFiltresineUyar(personel, 'emekli', emekli)) return false;
            return true;
        });

        liste.sort((x, y) => {
            if (siralama === 'ad-asc') return String(x.ad || '').localeCompare(String(y.ad || ''), 'tr');
            if (siralama === 'ad-desc') return String(y.ad || '').localeCompare(String(x.ad || ''), 'tr');
            if (siralama === 'sube-asc') return String(x.sube || 'Merkez').localeCompare(String(y.sube || 'Merkez'), 'tr') || String(x.ad || '').localeCompare(String(y.ad || ''), 'tr');
            if (siralama === 'tarih-yeni') return new Date(y.girisTarihi || 0) - new Date(x.girisTarihi || 0);
            if (siralama === 'tarih-eski') return new Date(x.girisTarihi || 0) - new Date(y.girisTarihi || 0);
            return 0;
        });
        return liste;
    }
    function renderPersonelTables() {
        renderPersonelOzetleri();
        const tAktif = document.querySelector('#tabloAktifPersonel tbody');
        const tAyrilan = document.querySelector('#tabloAyrilanPersonel tbody');
        tAktif.innerHTML = ''; tAyrilan.innerHTML = '';
        let aCount = 0, cCount = 0;
        const aktifSatirlar = [];
        const ayrilanSatirlar = [];

        const isAdmin = isManagerUser();

        const ayArama = document.getElementById('fAyrilanArama').value.toLocaleLowerCase('tr-TR');
        const aySube = document.getElementById('fAyrilanSube').value;
        const ayCikisYili = document.getElementById('fAyrilanCikisYili').value;
        const ayEngelli = document.getElementById('fAyrilanEngelli')?.value || '';
        const ayEmekli = document.getElementById('fAyrilanEmekli')?.value || '';

        const aktifListe = filtrelenmisAktifPersonelleriGetir();

        aktifListe.forEach((p) => {
            aCount++;
            const subeVal = p.sube || 'Merkez';
            const subeStyle = getSubeBadgeStyle(subeVal);
            const fotografAdresi = personelFotografAdresi(p);
            const foto = fotografAdresi ? `<img src="${fotografAdresi}" class="user-img-thumb">` : '👤';

            let actionButtons = isPersonelUser()
                ? `<div class="action-btns"><button class="btn-modern btn-detail-modern" onclick="openPersonelDetayModal('${p.id}')">📋 Detay</button>`
                : `<div class="action-btns"><button class="btn-modern btn-edit-modern" onclick="personelDuzenle('${p.id}')">✏️ Düzenle</button>`;
            if (isAdmin) {
                actionButtons += `<button class="btn-modern btn-del-modern" onclick="personelSil('${p.id}')">🗑️ Sil</button>`;
            }
            actionButtons += `</div>`;

            aktifSatirlar.push(`
                <tr>
                    <td>${aCount}</td>
                    <td>${foto}</td>
                    <td><span class="tc-link" onclick="openPersonelDetayModal('${p.id}')">${p.id}</span></td>
                    <td>${p.ad}</td>
                    <td><span class="badge" style="${subeStyle}">${subeVal}</span></td>
                    <td>${p.gorev || '-'}</td>
                    <td>${p.telefon || '-'}</td>
                    <td>${tarihFormati(p.girisTarihi)}</td>
                    <td>${actionButtons}</td>
                </tr>
            `);
        });

        [...personeller].sort((x, y) => String(x.sube || 'Merkez').localeCompare(String(y.sube || 'Merkez'), 'tr') || String(x.ad || '').localeCompare(String(y.ad || ''), 'tr')).forEach((p) => {
            if (!aktifSirketeAit(p)) return;
            const isAyrilan = Boolean(p.cikisTarihi && String(p.cikisTarihi) !== "null");
            if (!isAyrilan) return;
            if (isPersonelUser() && String(p.id) !== String(activeUser.tcNo)) return;

            if (ayArama && !p.ad.toLowerCase().includes(ayArama) && !String(p.id).includes(ayArama)) return;
            if (aySube && p.sube !== aySube) return;
            if (ayCikisYili && (!p.cikisTarihi || !p.cikisTarihi.startsWith(ayCikisYili))) return;
            if (!personelDurumFiltresineUyar(p, 'engelli', ayEngelli)) return;
            if (!personelDurumFiltresineUyar(p, 'emekli', ayEmekli)) return;

            cCount++;
            const subeVal = p.sube || 'Merkez';
            const subeStyle = getSubeBadgeStyle(subeVal);
            const fotografAdresi = personelFotografAdresi(p);
            const foto = fotografAdresi ? `<img src="${fotografAdresi}" class="user-img-thumb">` : '👤';

            let actionButtons = isPersonelUser()
                ? `<div class="action-btns"><button class="btn-modern btn-detail-modern" onclick="openPersonelDetayModal('${p.id}')">📋 Detay</button>`
                : `<div class="action-btns"><button class="btn-modern btn-edit-modern" onclick="personelDuzenle('${p.id}')">✏️ Düzenle</button>`;
            if (isAdmin) {
                actionButtons += `<button class="btn-modern btn-del-modern" onclick="personelSil('${p.id}')">🗑️ Sil</button>`;
            }
            actionButtons += `</div>`;

            ayrilanSatirlar.push(`
                <tr>
                    <td>${cCount}</td>
                    <td>${foto}</td>
                    <td><span class="tc-link" onclick="openPersonelDetayModal('${p.id}')">${p.id}</span></td>
                    <td>${p.ad}</td>
                    <td><span class="badge" style="${subeStyle}">${subeVal}</span></td>
                    <td>${p.gorev || '-'}</td>
                    <td>${p.telefon || '-'}</td>
                    <td>${tarihFormati(p.girisTarihi)}</td>
                    <td><strong style="color:#ef4444;">${tarihFormati(p.cikisTarihi)}</strong></td>
                    <td>${actionButtons}</td>
                </tr>
            `);
        });

        tAktif.innerHTML = aktifSatirlar.join('');
        tAyrilan.innerHTML = ayrilanSatirlar.join('');
        document.getElementById('badgeAktifSayisi').innerText = `${aCount} Kişi`;
        document.getElementById('badgeAyrilanSayisi').innerText = `${cCount} Kişi`;
    }

    const PERSONEL_EXPORT_FIELDS = [
        { key: 'fotografUrl', label: 'Fotoğraf Bağlantısı' }, { key: 'id', label: 'T.C. No' }, { key: 'ad', label: 'Ad Soyad' }, { key: 'sube', label: 'Şube / Şantiye' }, { key: 'departman', label: 'Departman' }, { key: 'gorev', label: 'Görevi / Ünvan' }, { key: 'kadro', label: 'Kadro' }, { key: 'yonetici', label: 'Bağlı Yönetici' },
        { key: 'telefon', label: 'Telefon' }, { key: 'kurumsalTelefon', label: '2. Telefon' }, { key: 'eposta', label: 'E-posta' }, { key: 'adres', label: 'Adres' }, { key: 'acilDurumAd', label: 'Acil Durum Kişisi' }, { key: 'acilDurumYakinlik', label: 'Acil Durum Yakınlığı' }, { key: 'acilDurumTelefon', label: 'Acil Durum Telefonu' },
        { key: 'dogumTarihi', label: 'Doğum Tarihi', date: true }, { key: 'cinsiyet', label: 'Cinsiyet' }, { key: 'medeniDurum', label: 'Medeni Durum' }, { key: 'cocukSayisi', label: 'Çocuk Sayısı' }, { key: 'kimlikSeriNo', label: 'Kimlik Seri No' }, { key: 'girisTarihi', label: 'İşe Giriş Tarihi', date: true }, { key: 'cikisTarihi', label: 'İşten Çıkış Tarihi', date: true },
        { key: 'kanGrubu', label: 'Kan Grubu' }, { key: 'isyeriHekimi', label: 'İş Yeri Hekimi' }, { key: 'sonSaglikTaramasi', label: 'Son Sağlık Taraması', date: true }, { key: 'kronikRahatsizlik', label: 'Kronik Rahatsızlıklar' }, { key: 'alerjiler', label: 'Alerjiler' }, { key: 'saglikNotu', label: 'Sağlık / İSG Notu' },
        { key: 'askerlikDurumu', label: 'Askerlik Durumu' }, { key: 'terhisTarihi', label: 'Terhis Tarihi', date: true }, { key: 'tecilBitis', label: 'Tecil Bitiş Tarihi', date: true }, { key: 'engelli', label: 'Engelli Durumu' }, { key: 'emekli', label: 'Emeklilik Durumu' }, { key: 'emeklilikTuru', label: 'Emeklilik Türü' }, { key: 'sgkNo', label: 'SGK Sicil No' }, { key: 'vergiMuafiyet', label: 'Vergi Muafiyeti' },
        { key: 'bankaAdi', label: 'Banka Adı' }, { key: 'iban', label: 'IBAN' }, { key: 'ucretTipi', label: 'Ücret Tipi' }, { key: 'ucret', label: 'Ücret Tutarı' }, { key: 'ekOdemeTuru', label: 'Ek Ödeme Türü' }, { key: 'ekOdemeTutari', label: 'Ek Ödeme Tutarı' }, { key: 'yolUcreti', label: 'Yol Ücreti' }, { key: 'primVar', label: 'Prim Uygulanır mı?' },
        { key: 'egitimSeviyesi', label: 'Eğitim Seviyesi' }, { key: 'okulBolum', label: 'Okul / Bölüm' }, { key: 'mezuniyetYili', label: 'Mezuniyet Yılı' }, { key: 'belgeler', label: 'Aldığı Belgeler' }, { key: 'sertifikalar', label: 'Sertifikalar' }, { key: 'sertifikaBitis', label: 'Sertifika Bitiş Tarihi', date: true }, { key: 'ehliyetDil', label: 'Ehliyetler ve Yabancı Dil' },
        { key: 'zimmetNotu', label: 'Zimmet Bilgisi' }, { key: 'terfiGecmisi', label: 'Terfi / Ünvan Geçmişi' }, { key: 'performansNotu', label: 'Performans / Ödül Notları' }, { key: 'aciklama', label: 'Açıklamalar' }
    ];
    let personelExportType = 'excel';
    let personelSeciliExportAlanlari = new Set(['ad']);

    function personelExportSecimOzetiniGuncelle() {
        const sayac = document.getElementById('personelExportSecimSayisi');
        if (sayac) sayac.textContent = `${personelSeciliExportAlanlari.size} alan seçildi`;
    }

    function personelExportAlanSecimiDegisti(input) {
        const key = String(input?.dataset?.exportKey || '');
        if (!key) return;
        if (input.checked) personelSeciliExportAlanlari.add(key);
        else personelSeciliExportAlanlari.delete(key);
        const label = input.closest('label');
        if (label) {
            label.style.borderColor = input.checked ? '#38bdf8' : '#dce8f1';
            label.style.background = input.checked ? '#f0f9ff' : '#fff';
        }
        personelExportSecimOzetiniGuncelle();
    }

    function personelExportAlanlariniDegistir(hepsini) {
        personelSeciliExportAlanlari = new Set();
        document.querySelectorAll('#personelExportFields input[type="checkbox"]').forEach(input => {
            input.checked = Boolean(hepsini);
            if (input.checked) personelSeciliExportAlanlari.add(String(input.dataset.exportKey || ''));
            const label = input.closest('label');
            if (label) {
                label.style.borderColor = input.checked ? '#38bdf8' : '#dce8f1';
                label.style.background = input.checked ? '#f0f9ff' : '#fff';
            }
        });
        personelSeciliExportAlanlari.delete('');
        personelExportSecimOzetiniGuncelle();
    }

    function openPersonelExportModal(type) {
        personelExportType = type;
        personelSeciliExportAlanlari = new Set(['ad']);
        const fields = document.getElementById('personelExportFields');
        fields.innerHTML = PERSONEL_EXPORT_FIELDS.map((field, index) => {
            const checked = field.key === 'ad';
            return `<label for="personelExportField_${index}" class="remember-login" style="margin:0;padding:9px;border:1px solid ${checked ? '#38bdf8' : '#dce8f1'};border-radius:8px;background:${checked ? '#f0f9ff' : '#fff'};"><input id="personelExportField_${index}" type="checkbox" data-export-key="${field.key}" ${checked ? 'checked' : ''} onchange="personelExportAlanSecimiDegisti(this)"> ${field.label}</label>`;
        }).join('');
        personelExportSecimOzetiniGuncelle();
        document.getElementById('btnConfirmPersonelExport').textContent = type === 'pdf' ? 'PDF Oluştur' : 'Excel Oluştur';
        document.getElementById('btnConfirmPersonelExport').onclick = exportSelectedPersonelFields;
        document.getElementById('modalPersonelExport').style.display = 'flex';
    }

    function closePersonelExportModal() {
        document.getElementById('modalPersonelExport').style.display = 'none';
    }

    function exportSelectedPersonelFields() {
        const selected = [...personelSeciliExportAlanlari];
        if (!selected.length) { alert('Lütfen en az bir alan seçin.'); return; }
        const fields = selected.map(key => PERSONEL_EXPORT_FIELDS.find(field => field.key === key)).filter(Boolean);
        const records = filtrelenmisAktifPersonelleriGetir();
        if (!records.length) { alert('Seçili filtrelere uygun dışa aktarılacak personel bulunamadı.'); return; }
        const rows = records.map(person => fields.map(field => {
            const value = field.key === 'mezuniyetYili' ? mezuniyetYiliniDuzelt(person.mezuniyetYili || person.mezuniyetTarihi) : field.key === 'ucret' && person.fdUcretDonemleri?.length ? paraFormatla(personelGunlukUcretiniGetir(person)) : person[field.key];
            if (field.date) return value ? tarihFormati(value) : '';
            if (field.key === 'engelli' || field.key === 'emekli') return personelEvetMi(value) ? 'Evet' : 'Hayır';
            return value ?? '';
        }));
        closePersonelExportModal();

        if (personelExportType === 'excel') {
            const worksheet = XLSX.utils.aoa_to_sheet([fields.map(field => field.label), ...rows]);
            worksheet['!cols'] = fields.map((field, index) => ({ wch: Math.min(45, Math.max(field.label.length + 2, ...rows.map(row => String(row[index] ?? '').length + 2))) }));
            const workbook = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(workbook, worksheet, 'Aktif Personeller');
            XLSX.writeFile(workbook, 'Aktif_Personel_Listesi.xlsx');
            return;
        }

        const wrapper = document.createElement('div');
        wrapper.innerHTML = `<table><thead><tr>${fields.map(field => `<th>${escapeDashboardText(field.label)}</th>`).join('')}</tr></thead><tbody>${rows.map(row => `<tr>${row.map(value => `<td>${escapeDashboardText(value)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
        return window.fdTabloPdfOnizle?.(wrapper.querySelector('table'),'AKTİF PERSONEL LİSTESİ','Aktif_Personel_Listesi.pdf',{yon:'landscape',format:fields.length>8?'a3':'a4',altBaslik:'Aktif Personel Listesi'});
    }
    function exportPersonelToPDF() {
        const table = document.getElementById('tabloAktifPersonel');
        return window.fdTabloPdfOnizle?.(table,'AKTİF PERSONEL LİSTESİ','Aktif_Personel_Listesi.pdf',{yon:'landscape',format:'a3',altBaslik:'Aktif Personel Listesi'});
    }

    function exportPersonelToExcel() {
        const originalTable = document.getElementById('tabloAktifPersonel');
        const cloneTable = originalTable.cloneNode(true);
        
        const rows = cloneTable.querySelectorAll('tr');
        rows.forEach(row => {
            if (row.cells.length > 11) row.deleteCell(11);
            if (row.cells.length > 1) row.deleteCell(1);
        });

        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, XLSX.utils.table_to_sheet(cloneTable), "Aktif Personeller");
        XLSX.writeFile(wb, "Aktif_Personel_Listesi.xlsx");
    }

